export const SUBAGENT_WARNING_SCHEMA_OVERRIDDEN =
	"SYSTEM WARNING: Subagent exhausted schema-retry budget; result was accepted despite failing the output schema.";
export const SUBAGENT_WARNING_NULL_YIELD = "SYSTEM WARNING: Subagent called yield with null data.";
export const SUBAGENT_WARNING_MISSING_YIELD =
	"SYSTEM WARNING: Subagent exited without calling yield tool after 3 reminders.";
export const SUBAGENT_WARNING_EMPTY_MESSAGE = "SYSTEM WARNING: Subagent ended without a final message.";

/** Build a schema_violation outcome — surfaced as a non-zero exit so callers treat it as a failure. */
function buildSchemaViolationOutcome(
	failure: { message: string; missingRequired: string[] },
	data: unknown,
): { rawOutput: string; stderr: string; exitCode: number } {
	const missing = failure.missingRequired;
	const headline =
		missing.length > 0
			? `schema_violation: missing required fields: ${missing.join(", ")}`
			: `schema_violation: ${failure.message}`;
	const payload = {
		error: "schema_violation",
		message: failure.message,
		missingRequired: missing,
		data: previewOffendingData(data),
	};
	let rawOutput: string;
	try {
		rawOutput = JSON.stringify(payload, null, 2);
	} catch {
		rawOutput = `{"error":"schema_violation","message":${JSON.stringify(headline)}}`;
	}
	return { rawOutput, stderr: headline, exitCode: 1 };
}

export function finalizeSubprocessOutput(args: FinalizeSubprocessOutputArgs): FinalizeSubprocessOutputResult {
	let { rawOutput, exitCode, stderr } = args;
	const { yieldItems, doneAborted, signalAborted, outputSchema, lastAssistantText } = args;
	const mode = args.outputSchemaMode ?? "permissive";
	const source = args.outputSchemaSource ?? (outputSchema === undefined ? "none" : "session");
	const includeStructuredOutput = source !== "none";
	let structuredOutput: StructuredSubagentOutput | undefined;
	let abortedViaYield = false;
	const hasYield = Array.isArray(yieldItems) && yieldItems.length > 0;
	const hadFailureBeforeYield = exitCode !== 0 && stderr.trim().length > 0;

	if (hasYield) {
		const lastYield = yieldItems[yieldItems.length - 1];
		if (lastYield?.status === "aborted") {
			abortedViaYield = true;
			exitCode = 0;
			stderr = lastYield.error || "Subagent aborted task";
			try {
				rawOutput = JSON.stringify({ aborted: true, error: lastYield.error }, null, 2);
			} catch {
				rawOutput = `{"aborted":true,"error":"${lastYield.error || "Unknown error"}"}`;
			}
		} else {
			const assembled = assembleYieldResult(yieldItems, lastAssistantText, yieldSectionShapes(outputSchema));
			if (!assembled || assembled.missingData) {
				rawOutput = rawOutput ? `${SUBAGENT_WARNING_NULL_YIELD}\n\n${rawOutput}` : SUBAGENT_WARNING_NULL_YIELD;
				if (includeStructuredOutput) {
					structuredOutput = { source, mode, status: "invalid", error: SUBAGENT_WARNING_NULL_YIELD };
				}
				// Strict mode promises a schema violation fails the run, not a
				// warning-decorated success (exitCode 0); build the same
				// non-zero-exit outcome the validated-data path uses below so
				// async job delivery marks the job failed instead of completed.
				if (mode === "strict" && includeStructuredOutput) {
					const { validator } = buildOutputValidator(outputSchema);
					const outcome = buildSchemaViolationOutcome(
						{ message: SUBAGENT_WARNING_NULL_YIELD, missingRequired: [...(validator?.requiredFields ?? [])] },
						undefined,
					);
					rawOutput = outcome.rawOutput;
					stderr = outcome.stderr;
					exitCode = outcome.exitCode;
				}
			} else {
				const { validator, error: schemaError, normalized } = buildOutputValidator(outputSchema);
				const submittedData = assembled.rawText ? assembled.data : parseStringifiedJson(assembled.data ?? null);
				const completeData =
					mode === "strict" ? (validator?.normalize(submittedData) ?? submittedData) : submittedData;
				const validation = validator?.validate(completeData);
				const failure =
					validation && !validation.success
						? summarizeValidationFailure(validation, completeData, validator?.requiredFields ?? [])
						: assembled.schemaOverridden
							? { message: SUBAGENT_WARNING_SCHEMA_OVERRIDDEN, missingRequired: [] }
							: schemaError
								? { message: `invalid output schema: ${schemaError}`, missingRequired: [] }
								: undefined;
				if (includeStructuredOutput) {
					structuredOutput =
						schemaError || normalized === undefined
							? {
									source,
									mode,
									status: "unavailable",
									data: completeData,
									error: schemaError ? `invalid output schema: ${schemaError}` : undefined,
								}
							: failure
								? { source, mode, status: "invalid", data: completeData, error: failure.message }
								: { source, mode, status: "valid", data: completeData };
				}
				const mustReject =
					failure !== undefined && (mode === "strict" || (!assembled.schemaOverridden && !schemaError));
				if (mustReject && failure) {
					const outcome = buildSchemaViolationOutcome(failure, completeData);
					rawOutput = outcome.rawOutput;
					stderr = outcome.stderr;
					exitCode = outcome.exitCode;
				} else {
					try {
						rawOutput =
							assembled.rawText && typeof completeData === "string"
								? completeData
								: (JSON.stringify(completeData, null, 2) ?? "null");
					} catch (err) {
						const errorMessage = err instanceof Error ? err.message : String(err);
						rawOutput = `{"error":"Failed to serialize yield data: ${errorMessage}"}`;
					}
					if (!hadFailureBeforeYield) {
						exitCode = 0;
						stderr = assembled.schemaOverridden
							? SUBAGENT_WARNING_SCHEMA_OVERRIDDEN
							: (structuredOutput?.error ?? "");
					} else if (!stderr) {
						stderr = "Subagent failed after yielding a result.";
					}
				}
			}
		}
	} else if (args.structured === false) {
		// The final assistant message is the result verbatim; only an empty one fails.
		if (exitCode === 0 && !rawOutput.trim()) {
			rawOutput = SUBAGENT_WARNING_EMPTY_MESSAGE;
			stderr = SUBAGENT_WARNING_EMPTY_MESSAGE;
			exitCode = 1;
		}
	} else {
		const allowFallback = exitCode === 0 && !doneAborted && !signalAborted;
		const { normalized: normalizedSchema, error: schemaError } = normalizeSchema(outputSchema);
		const hasOutputSchema = normalizedSchema !== undefined && !schemaError;
		const fallback = allowFallback ? resolveFallbackCompletion(rawOutput, outputSchema) : null;
		if (fallback) {
			const { validator } = buildOutputValidator(outputSchema);
			const completeData = parseStringifiedJson(fallback.data ?? null);
			const result = validator?.validate(completeData) ?? { success: true as const };
			if (!result.success) {
				const summary = summarizeValidationFailure(result, completeData, validator?.requiredFields ?? []);
				if (includeStructuredOutput) {
					structuredOutput = { source, mode, status: "invalid", data: completeData, error: summary.message };
				}
				const outcome = buildSchemaViolationOutcome(summary, completeData);
				rawOutput = outcome.rawOutput;
				stderr = outcome.stderr;
				exitCode = outcome.exitCode;
			} else {
				if (includeStructuredOutput) {
					structuredOutput = {
						source,
						mode,
						status: "valid",
						data: completeData,
					};
				}
				try {
					rawOutput = JSON.stringify(completeData, null, 2) ?? "null";
				} catch (err) {
					const errorMessage = err instanceof Error ? err.message : String(err);
					rawOutput = `{"error":"Failed to serialize fallback completion: ${errorMessage}"}`;
				}
				exitCode = 0;
				stderr = "";
			}
		} else if (!hasOutputSchema && allowFallback && rawOutput.trim().length > 0) {
			exitCode = 0;
			stderr = "";
		} else if (exitCode === 0) {
			const hasRawOutput = rawOutput.trim().length > 0;
			rawOutput = rawOutput ? `${SUBAGENT_WARNING_MISSING_YIELD}\n\n${rawOutput}` : SUBAGENT_WARNING_MISSING_YIELD;
			if (hasOutputSchema || !hasRawOutput) {
				exitCode = 1;
				stderr = SUBAGENT_WARNING_MISSING_YIELD;
			}
		}
	}

	return { rawOutput, exitCode, stderr, abortedViaYield, hasYield, structuredOutput };
}

function formatToolArgsPreview(value: string, key: string): { value: string; key: string } {
	const safe = shortenToolArgumentPaths(replaceTabs(sanitizeText(value)), key);
	return { value: previewLine(safe, TRUNCATE_LENGTHS.CONTENT), key };
}

/**
 * Extract bounded display arguments after path and terminal sanitation. The key names which argument
 * was chosen so the renderer can shorten home paths in path-valued arguments without rewriting a
 * literal search pattern.
 */
function extractToolArgsPreview(
	args: Record<string, unknown>,
	toolName: string,
	editMode?: EditMode,
): { value: string; key: string } | undefined {
	// Priority order for preview
	const previewKeys = ["command", "file_path", "path", "pattern", "query", "url", "task", "prompt"];
	const isEdit = toolName === "edit" || toolName === "apply_patch";
	if (isEdit && typeof args.input === "string") {
		const paths = getEditInputPaths(args.input, editMode);
		if (paths.length > 0) return formatToolArgsPreview(paths.join(", "), "path");
	}
	const compoundEdits = args.edits;
	if (isEdit && Array.isArray(compoundEdits)) {
		const paths = new Set<string>();
		if (typeof args.path === "string" && args.path) paths.add(args.path);
		for (const edit of compoundEdits) {
			if (!isRecord(edit)) continue;
			if (typeof edit.path === "string" && edit.path) paths.add(edit.path);
			if (typeof edit.rename === "string" && edit.rename) paths.add(edit.rename);
		}
		if (paths.size > 0) return formatToolArgsPreview([...paths].join(", "), "path");
	}
	for (const key of previewKeys) {
		if (typeof args[key] === "string" && args[key]) {
			return formatToolArgsPreview(args[key] as string, key);
		}
	}
	return undefined;
}

function getNumberField(record: Record<string, unknown>, key: string): number | undefined {
	if (!Object.hasOwn(record, key)) return undefined;
	const value = record[key];
	return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

function firstNumberField(record: Record<string, unknown>, keys: string[]): number | undefined {
	for (const key of keys) {
		const value = getNumberField(record, key);
		if (value !== undefined) return value;
	}
	return undefined;
}

/**
 * Tokens for progress display: input + output + cacheWrite per turn.
 *
 * Deliberately excludes cacheRead. With prompt caching, cacheRead in each turn
 * equals the full cached context (potentially hundreds of KB), so summing it
 * across all turns produces a cumulative total that is N×context_size — far
 * larger than the context window and misleading as a "work done" metric.
 * cacheWrite is kept because each byte is written once, not repeated per turn.
 * The cost segment handles billing; dedicated cache_read/cache_write segments
 * handle cache-specific monitoring.
 */
function getUsageTokens(usage: unknown): number {
	if (!usage || typeof usage !== "object") return 0;
	const record = usage as Record<string, unknown>;

	const input = firstNumberField(record, ["input", "input_tokens", "inputTokens"]) ?? 0;
	const output = firstNumberField(record, ["output", "output_tokens", "outputTokens"]) ?? 0;
	const cacheWrite = firstNumberField(record, ["cacheWrite", "cache_write", "cacheWriteTokens"]) ?? 0;
	const computed = input + output + cacheWrite;
	if (computed > 0) return computed;
	// Fallback for providers that only surface a pre-summed total without individual
	// field breakdown. This total includes cacheRead, but returning it is still better
	// than silently showing 0 for those providers.
	return firstNumberField(record, ["totalTokens", "total_tokens"]) ?? 0;
}

/**
 * Create proxy tools that reuse the parent's MCP connections.
 *
 * Each proxy delegates to the current source `MCPTool`/`DeferredMCPTool` rather
 * than rebuilding a raw `tools/call` request, so the Task/subagent path shares
 * the source tool's authoritative outbound boundary: harness-intent (`i`)
 * stripping, optional-placeholder pruning, local-URL resolution, reconnect
 * retry, abort handling, and result/provider metadata. The source tool is
 * re-resolved on every call by raw MCP server/tool metadata (not the normalized
 * display name), so a reconnect that swaps the instance in `getTools()` is
 * always honored. The source transport owns the configured MCP deadline,
 * including timeout=0; a second Task deadline would silently cap longer calls.
 * The proxy only races caller cancellation around source execution.
 */
export function createMCPProxyTools(mcpManager: MCPManager): CustomTool[] {
	return mcpManager.getTools().map(tool => {
		const serverName = tool.mcpServerName ?? "";
		const mcpToolName = tool.mcpToolName ?? "";
		return {
			name: tool.name,
			label: tool.label ?? tool.name,
			description: tool.description ?? "",
			parameters: tool.parameters,
			strict: tool.strict,
			mcpServerName: serverName,
			mcpToolName,
			execute: async (toolCallId, params, onUpdate, ctx, signal) => {
				if (signal?.aborted) {
					throw new ToolAbortError();
				}
				// Re-resolve by raw MCP metadata so a reconnect that replaced the
				// source instance is picked up; the display name alone is not enough.
				const source = mcpManager
					.getTools()
					.find(t => t.mcpServerName === serverName && t.mcpToolName === mcpToolName);
				if (!source?.execute) {
					return {
						content: [{ type: "text" as const, text: `MCP error: tool ${mcpToolName} no longer available` }],
						details: { serverName, mcpToolName, isError: true },
					};
				}
				try {
					return await untilAborted(signal, source.execute(toolCallId, params, onUpdate, ctx, signal));
				} catch (error) {
					if (error instanceof ToolAbortError) {
						throw error;
					}
					if (signal?.aborted) {
						throw new ToolAbortError();
					}
					return {
						content: [
							{
								type: "text" as const,
								text: `MCP error: ${error instanceof Error ? error.message : String(error)}`,
							},
						],
						details: { serverName, mcpToolName, isError: true },
					};
				}
			},
		};
	});
}

/** Session surface {@link followMCPTools} drives: the child's MCP rebind plus its teardown hook. */
export type MCPToolFollowerSession = Pick<AgentSession, "refreshMCPTools" | "addDisposer">;

/** Subscription created by {@link followMCPTools}; bind it to the session the proxies went into. */
export interface MCPToolFollower {
	/** Attach the created session; replays any change seen since subscribing, then follows later ones. */
	bind(session: MCPToolFollowerSession): void;
	/** Drop the subscription when the session was never created. */
	dispose(): void;
}

/**
 * Keep a child session's MCP proxy tools in step with the parent's shared
 * manager. A child gets a spawn-time {@link createMCPProxyTools} snapshot and
 * never owns the manager's single-slot tool callback, so without this a
 * `/mcp reload` — or a server added, removed, or reconnected later — only
 * reaches the owning session and every live subagent keeps its stale set.
 *
 * Subscribe BEFORE building the child's proxies: a change landing while the
 * session is still being created is recorded and replayed on {@link
 * MCPToolFollower.bind}, so no window exists where an update is lost. Bursts
 * (a reload re-placing every server) coalesce into one rebind per tick.
 *
 * `reservedNames` are the child's explicitly supplied tool names (e.g.
 * kernel-defined `mcp__…` tools): `createAgentSession` drops same-named proxies
 * so those tools win, and every rebind must keep dropping them, or the first
 * reload would replace the child's own tool with the MCP capability.
 */
export function followMCPTools(mcpManager: MCPManager, reservedNames?: ReadonlySet<string>): MCPToolFollower {
	let session: MCPToolFollowerSession | undefined;
	let pending = false;
	let scheduled = false;
	const flush = (): void => {
		scheduled = false;
		if (!session || !pending) return;
		pending = false;
		const proxies = createMCPProxyTools(mcpManager);
		const tools = reservedNames?.size ? proxies.filter(tool => !reservedNames.has(tool.name)) : proxies;
		session.refreshMCPTools(tools).catch(error => {
			logger.warn("Subagent MCP tool refresh failed", {
				error: error instanceof Error ? error.message : String(error),
			});
		});
	};
	const schedule = (): void => {
		if (scheduled) return;
		scheduled = true;
		queueMicrotask(flush);
	};
	const unsubscribe = mcpManager.addToolsChangedListener(() => {
		pending = true;
		if (session) schedule();
	});
	return {
		bind(next) {
			session = next;
			next.addDisposer(unsubscribe);
			if (pending) schedule();
		},
		dispose: unsubscribe,
	};
}

/**
 * Per-family tiers a subagent inherits: the parent's live tiers when a live session supplied
 * them, else its configured `tier.*`. Live entries a family can't realize (a resumed session
 * file may carry `{anthropic: "flex"}`) are dropped — the subagent overlay rejects them.
 */
function inheritedSubagentServiceTiers(
	baseSettings: Settings,
	inheritedServiceTier?: ServiceTierByFamily | null,
): ServiceTierByFamily {
	if (inheritedServiceTier === undefined) {
		return buildServiceTierByFamily(
			cfgTierOpenai.get(baseSettings),
			cfgTierAnthropic.get(baseSettings),
			cfgTierGoogle.get(baseSettings),
		);
	}
	const tiers: ServiceTierByFamily = {};
	for (const family of ["openai", "anthropic", "google"] as const) {
		const tier = inheritedServiceTier?.[family];
		if (isServiceTierForFamily(family, tier)) tiers[family] = tier;
	}
	return tiers;
}

/**
 * Compaction thresholds of the root (non-subagent) settings a subagent chain
 * started from. Per-agent `task.agentCompactionThresholdOverrides` entries
 * replace `compaction.threshold*` and switch off `compaction.modelThresholds`
 * only for the agent they name; every other descendant resolves against these
 * root values, not an ancestor's override.
 */
const kRootCompactionThresholds = Symbol("task.rootCompactionThresholds");

interface RootCompactionThresholds extends CompactionThresholdPair {
	modelThresholdsEnabled: boolean;
}

/** Settings from {@link createSubagentSettings}, tagged with its chain's root compaction thresholds. */
interface SubagentChainSettings extends Settings {
	[kRootCompactionThresholds]?: RootCompactionThresholds;
}

/**
 * Settings overrides applying an exact-name compaction threshold entry to one
 * subagent. The agent entry outranks `compaction.modelThresholds`, including
 * entries added while the agent runs, so model entries are switched off for it.
 */
export function compactionThresholdSettings(
	threshold: CompactionThresholdPair | undefined,
): Readonly<Record<string, unknown>> | undefined {
	return threshold === undefined
		? undefined
		: {
				"compaction.thresholdPercent": threshold.thresholdPercent,
				"compaction.thresholdTokens": threshold.thresholdTokens,
				"compaction.modelThresholdsEnabled": false,
			};
}

export function createSubagentSettings(
	baseSettings: SubagentChainSettings,
	overrides?: Readonly<Record<string, unknown>>,
	inheritedServiceTier?: ServiceTierByFamily | null,
): Settings {
	// Resolve the subagent's per-family tiers from `tier.subagent` ("inherit" =
	// match the parent's live tiers when a live session supplied them, else the
	// subagent's own configured tier.* settings). The result is stamped onto the
	// overlay so createAgentSession's tier.* reads pick it up.
	const inheritedTiers = inheritedSubagentServiceTiers(baseSettings, inheritedServiceTier);
	const subagentTiers = resolveSubagentServiceTier(cfgTierSubagent.get(baseSettings), inheritedTiers);
	// A parent subagent's own per-agent threshold must not leak to its children: descendants
	// of a subagent pin the root's thresholds. A root parent's children read them through live.
	const inheritedRootThresholds = baseSettings[kRootCompactionThresholds];
	const rootThresholds = inheritedRootThresholds ?? {
		thresholdPercent: cfgCompactionThresholdPercent.get(baseSettings),
		thresholdTokens: cfgCompactionThresholdTokens.get(baseSettings),
		modelThresholdsEnabled: cfgCompactionModelThresholdsEnabled.get(baseSettings),
	};
	// Every other setting reads through to the parent live; writes on the overlay stay local.
	const subagentSettings: SubagentChainSettings = baseSettings.overlay(
		{
			...(inheritedRootThresholds && {
				"compaction.thresholdPercent": inheritedRootThresholds.thresholdPercent,
				"compaction.thresholdTokens": inheritedRootThresholds.thresholdTokens,
				"compaction.modelThresholdsEnabled": inheritedRootThresholds.modelThresholdsEnabled,
			}),
			// A subagent's thinking level is chosen at spawn (agent definition, `effort`, or this
			// snapshot of the parent default); a later parent default edit must not re-steer it.
			defaultThinkingLevel: cfgDefaultThinkingLevel.get(baseSettings),
			"tier.openai": subagentTiers.openai ?? "none",
			"tier.anthropic": subagentTiers.anthropic ?? "none",
			"tier.google": subagentTiers.google ?? "none",
			// Async jobs and bash/eval auto-backgrounding are inherited from the parent:
			// background jobs are owner-routed to the subagent's own session, and
			// the run driver's quiescence barrier + teardown reap guarantee no
			// owner job outlives the run, so worktree capture/cleanup stays
			// race-free (previously both were force-disabled here).

			// Subagents run headless — there is no UI to confirm prompts against, so
			// the parent task approval is the authorization boundary. Use yolo mode
			// to preserve unattended subagent execution. User `tools.approval` policies still apply.
			"tools.approvalMode": "yolo",
			// Subagents run unadvised by default; runSubprocess opts a spawn back in
			// per agent (frontmatter `advisor` / `task.agentAdvisor`) via overrides.
			"advisor.enabled": false,
			// A subagent assignment is one turn: its tool loop ends only when the run
			// yields, so post-turn `checkCompaction` (driven from `agent_end`) fires
			// after the run is over and `maintainContextMidRun` is the only proactive
			// compaction the child ever reaches. `compaction.midTurnEnabled` encodes an
			// interactive preference — keep compaction boundaries on real user turns —
			// that has no counterpart here, so inheriting `false` left hours-long
			// worker runs sailing past the configured threshold until the provider
			// rejected the context (#13211). A per-spawn override still wins.
			"compaction.midTurnEnabled": true,
			...overrides,
		},
		{ derived: true },
	);
	subagentSettings[kRootCompactionThresholds] = rootThresholds;
	return subagentSettings;
}

export type AbortReason = "signal" | "shutdown" | "terminate" | "timeout" | "budget";

/** A tool call a subagent finished, as {@link ExecutorOptions.onToolResult} reports it. */
export interface SubagentToolResult {
	tool: string;
	/** Intent the model attached to the call, when it carried one. */
	intent?: string;
	/** The result's text parts, joined by newlines; empty when it had none. */
	text: string;
	isError: boolean;
}

const MAX_YIELD_TOOL_ERRORS = 6;

/** Inputs for the run monitor driving one subagent assignment. */
interface RunMonitorArgs {
	index: number;
	id: string;
	agent: AgentDefinition;
	task: string;
	assignment?: string;
	description?: string;
	/** Parent model registry for tiny-model label generation; absent → skip labeling. */
	modelRegistry?: ModelRegistry;
	/** Parent settings for tiny-model label generation. */
	settings?: Settings;
	modelOverride?: string | string[];
	/** Explicit pre-expansion model role alias selected for this run. */
	modelRole?: string;
	/** Extension routing note for the chosen model. */
	modelRoute?: string;
	signal?: AbortSignal;
	onProgress?: (progress: AgentProgress) => void;
	/** See {@link ExecutorOptions.onToolResult}. */
	onToolResult?: (result: SubagentToolResult) => void;
	eventBus?: EventBus;
	subagentEventBus?: EventBus;
	parentToolCallId?: string;
	detached?: boolean;
	sessionFile?: string;
	/** Soft assistant-request budget; 0 disables the guard. */
	softRequestBudget: number;
	/** Whether crossing the soft budget injects a wrap-up steering notice. */
	softRequestBudgetNotice: boolean;
	/** Wall-clock cap in ms; 0 disables the timer. */
	maxRuntimeMs: number;
	/** Whether to periodically ask the agent for a completion estimate; see {@link isCompletionProbeEnabled}. */
	completionProbe: boolean;
	/** Fires each time a terminal `yield` is recorded for this run. */
	onYieldAccepted?: () => void;
}

/**
 * The run-monitoring core of {@link runSubprocess}: progress tracking, event
 * processing, abort/budget machinery, usage accumulation, and output capture
 * for one assignment run.
 */
interface SubagentRunMonitor {
	readonly progress: AgentProgress;
	/** Fires when the run was asked to stop (caller signal, timeout, budget, terminate). */
	readonly abortSignal: AbortSignal;
	readonly accumulatedUsage: Usage;
	hasUsage(): boolean;
	yieldCalled(): boolean;
	/**
	 * Latch or clear the reminder ladder's forced final `yield`. While set, the
	 * next accepted `yield` is terminal even when it carries incremental
	 * section labels, so a model pinned to `yield` by `toolChoice` cannot
	 * satisfy the pin forever without ending the run.
	 */
	markFinalYieldForced(forced: boolean): void;
	/** Epoch ms when the run's terminal `yield` was recorded; undefined while none is latched. */
	yieldAcceptedAt(): number | undefined;
	runtimeLimitExceeded(): boolean;
	/** True once the soft-budget stop fired: the free-running turn was aborted and the run is being driven to a forced final yield. */
	budgetStopRequested(): boolean;
	/** Resolves when the budget-stop session abort has settled (immediately when no stop fired). */
	waitForBudgetStop(): Promise<void>;
	/**
	 * True when a recorded yield was invalidated by a later async-result
	 * injection and no fresh yield has landed since: the yield payload
	 * predates background job outcomes the model was shown.
	 */
	yieldInvalidatedByAsync(): boolean;
	/**
	 * True once a terminal yield with pending owner async work stopped the
	 * free-running turn (recoverable, like a budget stop) instead of
	 * terminating the run. Cleared when {@link waitForYieldTurnStop} settles.
	 */
	yieldTurnStopRequested(): boolean;
	/** Resolves when the yield turn-stop session abort has settled (immediately when none fired). */
	waitForYieldTurnStop(): Promise<void>;
	/** The abort kind for this run, when an abort was requested. */
	abortKind(): AbortReason | undefined;
	terminalError(): string | undefined;
	/** True when the abort carries a precise external reason (signal / wall-clock / budget). */
	hasExplicitAbortReason(): boolean;
	/** Whether the (attempted) abort counts as a cancelled run rather than an internal failure. */
	isAbortedRun(): boolean;
	requestAbort(reason: AbortReason): void;
	failWithError(message: string): void;
	abortActiveSession(): Promise<void>;
	waitForActiveSessionAbort(): Promise<void>;
	resolveSignalAbortReason(): string;
	resolveAbortReasonText(): string;
	setActiveSession(session: AgentSession | null): void;
	/** Return and clear the active session reference. */
	takeActiveSession(): AgentSession | null;
	/** Subscribe the monitor to a session's events. Returns the unsubscribe function. */
	attach(session: AgentSession): () => void;
	/** Best-effort capture of the last assistant text for cancelled-run salvage. */
	captureSalvage(session: AgentSession): void;
	lastAssistantSalvageText(): string | undefined;
	/**
	 * Text of the last assistant turn that read as a report — prose, with no
	 * further work started. Source for `yield`'s data-less finalize.
	 */
	lastReportTurnText(): string | undefined;
	/** Whether any assistant message ended while this monitor was attached. */
	sawAssistantMessage(): boolean;
	/** Final raw output: end-of-run assistant text when available, else accumulated chunks. */
	rawOutput(): string;
	scheduleProgress(flush?: boolean): void;
	/** Stop processing events and clear listeners/timers. Call once the run settled. */
	finish(): void;
}

/**
 * True when `message` is the session-injected async-result follow-up
 * ({@link ASYNC_RESULT_MESSAGE_TYPE}): the transcript-ordered signal that a
 * background job outcome landed after whatever the model said before it.
 */
function isAsyncResultInjection(message: AgentMessage | undefined): boolean {
	return message?.role === "custom" && message.customType === ASYNC_RESULT_MESSAGE_TYPE;
}

function createSubagentRunMonitor(args: RunMonitorArgs): SubagentRunMonitor {
	const {
		index,
		id,
		agent,
		task,
		assignment,
		signal,
		onProgress,
		softRequestBudget,
		softRequestBudgetNotice,
		maxRuntimeMs,
		completionProbe,
	} = args;
	const startTime = Date.now();

	const progress: AgentProgress = {
		index,
		id,
		agent: agent.name,
		agentSource: agent.source,
		status: "running",
		task,
		assignment,
		description: args.description,
		lastIntent: undefined,
		recentTools: [],
		recentOutput: [],
		toolCount: 0,
		requests: 0,
		tokens: 0,
		cost: 0,
		durationMs: 0,
		modelOverride: args.modelOverride,
		modelRole: args.modelRole,
		resolvedModelRoute: args.modelRoute,
	};

	const outputChunks: string[] = [];
	const finalOutputChunks: string[] = [];
	const RECENT_OUTPUT_TAIL_BYTES = 8 * 1024;
	let recentOutputTail = "";
	let recentOutputDirty = false;
	let resolved = false;
	let abortSent = false;
	let abortReason: AbortReason | undefined;
	let runtimeLimitExceeded = false;
	const listenerController = new AbortController();
	const listenerSignal = listenerController.signal;
	const abortController = new AbortController();
	const abortSignal = abortController.signal;
	let activeSession: AgentSession | null = null;
	let completionProbeStarted = false;
	let yieldCalled = false;
	let yieldCallPending = false;
	/**
	 * A `yield` awaiting validation suppresses the soft-budget check for its
	 * own turn (#5006). The check is deferred, not dropped: every turn that
	 * carries a yield latches {@link yieldCallPending}, so dropping it lets a
	 * run of yield-only turns bypass the budget entirely.
	 */
	let budgetCheckDeferred = false;
	/** True while the reminder ladder's forced final `yield` is outstanding. */
	let finalYieldForced = false;
	let yieldInvalidatedByAsync = false;
	/** Epoch ms the current terminal yield was recorded; cleared when it is invalidated. */
	let yieldAcceptedAt: number | undefined;
	let yieldTurnStopRequested = false;
	let yieldTurnStopPromise: Promise<void> | null = null;

	// Accumulate usage incrementally from message_end events (no memory for streaming events)
	const accumulatedUsage: Usage = {
		input: 0,
		output: 0,
		cacheRead: 0,
		cacheWrite: 0,
		totalTokens: 0,
		reasoningTokens: 0,
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
	};
	let hasUsage = false;
	let budgetSteerSent = false;
	let budgetLimitExceeded = false;
	let budgetStopRequested = false;
	let budgetStopAbortPromise: Promise<void> | undefined;
	let terminalError: string | undefined;
	let consecutiveYieldToolErrors = 0;
	let lastAssistantSalvageText: string | undefined;
	// The latest prose that can describe completed work. Locally runnable work
	// invalidates it; after tools Cursor already ran server-side, only text
	// following the last such call qualifies. A text-less yield turn may still
	// finalize the preceding report.
	let lastReportTurnText: string | undefined;
	let sawAssistantMessage = false;
	let activeSessionAbortPromise: Promise<void> | undefined;

	const abortActiveSession = (): Promise<void> => {
		const session = activeSession;
		if (!session) return Promise.resolve();
		activeSessionAbortPromise ??= session.abort().catch(error => {
			logger.debug("Subagent session abort cleanup failed", {
				error: error instanceof Error ? error.message : String(error),
			});
		});
		return activeSessionAbortPromise;
	};

	const waitForActiveSessionAbort = async (): Promise<void> => {
		if (activeSessionAbortPromise) await activeSessionAbortPromise;
	};

	const requestAbort = (reason: AbortReason) => {
		if (abortSent) {
			// Shutdown supersedes every resumable abort: a process teardown that
			// races a budget, timeout, or caller abort must still follow the
			// shutdown release path (dispose + unregister, restorable from disk)
			// instead of the resumable path, which would leave the subagent
			// adopted and alive past AgentLifecycleManager.dispose(). A committed
			// `terminate` keeps its outcome, and shutdown is never downgraded
			// back to signal.
			if (reason === "shutdown" && abortReason !== "terminate") {
				abortReason = "shutdown";
			} else if (
				reason === "signal" &&
				abortReason !== "signal" &&
				abortReason !== "timeout" &&
				abortReason !== "shutdown"
			) {
				abortReason = "signal";
			}
			return;
		}
		if (resolved) return;
		// Limit flags must stay below the abortSent/resolved guards, next to the
		// abortReason they mirror. The wall-clock timer can fire during teardown —
		// after a budget hard-abort or a committed yield has already settled the
		// run — and resolveAbortReasonText/finalizeRunResult read these flags
		// (not abortReason), so a post-commitment timeout must not set them or it
		// rewrites the real outcome (budget kill mislabeled, completed yield tagged
		// aborted).
		if (reason === "timeout") {
			runtimeLimitExceeded = true;
		}
		if (reason === "budget") {
			budgetLimitExceeded = true;
		}
		abortSent = true;
		abortReason = reason;
		abortController.abort();
		void abortActiveSession();
	};

	// Soft-budget stop: cancel the free-running turn WITHOUT aborting the
	// monitor, so driveSessionToResult can still drive one forced final report.
	// Deliberately not routed through abortActiveSession(): that memoizes its
	// promise, and a later hard abort (grace exhausted) must be able to abort
	// the session again.
	const requestBudgetStop = () => {
		if (budgetStopRequested || abortSent || resolved) return;
		budgetStopRequested = true;
		const session = activeSession;
		budgetStopAbortPromise = session
			? session.abort().catch(error => {
					logger.debug("Subagent budget-stop abort failed", {
						error: error instanceof Error ? error.message : String(error),
					});
				})
			: Promise.resolve();
	};

	const failWithError = (message: string) => {
		terminalError ??= message;
		requestAbort("terminate");
	};
	// Yield turn-stop: a terminal yield recorded while owner async work is
	// still pending is a scheduling pause, not run completion. Stop the
	// free-running turn exactly like a budget stop (session abort, monitor
	// signal untouched) so driveSessionToResult's quiescence barrier can settle
	// the jobs, fold their results in, and demand a fresh yield. Terminating
	// here instead would abort the run signal and make the barrier
	// unreachable, completing the run with a payload that predates the job
	// outcomes.
	const requestYieldTurnStop = () => {
		if (yieldTurnStopRequested || abortSent || resolved) return;
		yieldTurnStopRequested = true;
		const session = activeSession;
		yieldTurnStopPromise = session
			? session.abort().catch(error => {
					logger.debug("Subagent yield turn-stop abort failed", {
						error: error instanceof Error ? error.message : String(error),
					});
				})
			: Promise.resolve();
	};

	/** Owner async work that can still re-wake the run (quiescence barrier predicate). */
	const sessionHasPendingAsyncWork = (): boolean => activeSession?.hasPendingAsyncWork?.() ?? false;

	// Handle abort signal
	if (signal) {
		signal.addEventListener(
			"abort",
			() => {
				if (!resolved) requestAbort(signal.reason === ASYNC_JOB_MANAGER_SHUTDOWN_REASON ? "shutdown" : "signal");
			},
			{ once: true, signal: listenerSignal },
		);
	}

	// Wall-clock hard limit. Defense-in-depth for the case where a provider stream
	// hang escapes the inference-layer watchdog (see openai-completions
	// `isOpenAICompletionsProgressChunk`). Disabled by default; set
	// `task.maxRuntimeMs > 0` to cap each subagent's lifetime.
	let runtimeTimeoutId: NodeJS.Timeout | undefined;
	if (maxRuntimeMs > 0) {
		runtimeTimeoutId = setTimeout(() => {
			if (!resolved) {
				logger.warn("Subagent runtime limit exceeded; aborting", {
					id,
					agent: agent.name,
					maxRuntimeMs,
				});
				requestAbort("timeout");
			}
		}, maxRuntimeMs);
	}

	const resolveSignalAbortReason = (): string => {
		if (signal?.reason === ASYNC_JOB_MANAGER_SHUTDOWN_REASON) return "Async job manager shutdown";
		const reason = signal?.reason;
		if (reason instanceof Error) {
			const message = reason.message.trim();
			if (message.length > 0) return message;
		} else if (typeof reason === "string") {
			const message = reason.trim();
			if (message.length > 0) return message;
		}
		return "Cancelled by caller";
	};
	const resolveAbortReasonText = (): string => {
		if (runtimeLimitExceeded) {
			return `Subagent runtime limit exceeded (task.maxRuntimeMs=${maxRuntimeMs})`;
		}
		if (budgetLimitExceeded) {
			return `Soft request budget exceeded (${progress.requests} requests; budget ${softRequestBudget}) — agent did not yield when force-stopped`;
		}
		if (budgetStopRequested) {
			return `Soft request budget exceeded (${progress.requests} requests; budget ${softRequestBudget})`;
		}
		return resolveSignalAbortReason();
	};
	const PROGRESS_COALESCE_MS = 150;
	let lastProgressEmitMs = 0;
	let progressTimeoutId: NodeJS.Timeout | null = null;

	// Recompute progress.recentOutput from the capped tail. Deferred: text_delta
	// appends only extend the tail and mark it dirty; the (up to 8KB) split/filter
	// runs synchronously here, immediately before the ONLY places the progress
	// object is snapshotted ({...progress} for onProgress and the eventBus
	// progress channel, both inside emitProgressNow — including the
	// scheduleProgress(flush) finalize/error/cancel paths). Observers therefore
	// always see exact state; no staleness beyond the existing 150ms coalescing.
	const refreshRecentOutput = () => {
		if (!recentOutputDirty) return;
		recentOutputDirty = false;
		const tail =
			recentOutputTail.length > RECENT_OUTPUT_TAIL_BYTES
				? recentOutputTail.slice(-RECENT_OUTPUT_TAIL_BYTES)
				: recentOutputTail;
		const filtered = tail.split("\n").filter(line => line.trim());
		progress.recentOutput = filtered.slice(-8).reverse();
	};

	const emitProgressNow = () => {
		refreshRecentOutput();
		progress.durationMs = Date.now() - startTime;
		onProgress?.({ ...progress });
		const activityGist =
			progress.lastIntent ?? (progress.currentTool ? `running ${progress.currentTool}` : undefined);
		if (activityGist) AgentRegistry.global().setActivity(id, activityGist);
		const progressPayload = {
			index,
			agent: agent.name,
			agentSource: agent.source,
			task,
			parentToolCallId: args.parentToolCallId,
			detached: args.detached,
			assignment,
			progress: { ...progress },
			sessionFile: args.sessionFile,
		};
		emitSubagentFrame(args.eventBus, args.subagentEventBus, TASK_SUBAGENT_PROGRESS_CHANNEL, progressPayload);
		lastProgressEmitMs = Date.now();
	};

	const scheduleProgress = (flush = false) => {
		if (flush) {
			if (progressTimeoutId) {
				clearTimeout(progressTimeoutId);
				progressTimeoutId = null;
			}
			emitProgressNow();
			return;
		}
		const now = Date.now();
		const elapsed = now - lastProgressEmitMs;
		if (lastProgressEmitMs === 0 || elapsed >= PROGRESS_COALESCE_MS) {
			if (progressTimeoutId) {
				clearTimeout(progressTimeoutId);
				progressTimeoutId = null;
			}
			emitProgressNow();
			return;
		}
		if (progressTimeoutId) return;
		progressTimeoutId = setTimeout(() => {
			progressTimeoutId = null;
			emitProgressNow();
		}, PROGRESS_COALESCE_MS - elapsed);
	};

	// The task wire schema carries no description: when the caller didn't pre-set
	// a UI label (e.g. the eval bridge's `label`), compress the assignment into a
	// tiny-model one-sentence label off the spawn's critical path. Best-effort —
	// a late label still lands via the finalize-time reads of `progress.description`;
	// failures just leave the label unset.
	const labelSource = assignment?.trim();
	if (!args.description && args.modelRegistry && args.settings && labelSource) {
		generateTaskLabel(labelSource, args.modelRegistry, args.settings, id, abortSignal)
			.then(label => {
				if (!label || abortSignal.aborted || progress.description) return;
				progress.description = label;
				if (!resolved) scheduleProgress();
			})
			.catch(err => {
				logger.debug("Subagent label generation failed", {
					id,
					error: err instanceof Error ? err.message : String(err),
				});
			});
	}

	const getMessageContent = (message: unknown): unknown => {
		if (!isRecord(message) || !("content" in message)) {
			return undefined;
		}
		return message.content;
	};

	const getMessageUsage = (message: unknown): unknown => {
		if (!isRecord(message) || !("usage" in message)) {
			return undefined;
		}
		return message.usage;
	};

	// Hysteresis: let the tail grow to 2x the cap before trimming, so the
	// 8KB slice copy runs once per ~8KB of output instead of on every token
	// once the cap is reached. refreshRecentOutput() re-applies the exact cap.
	const trimRecentOutputTail = () => {
		if (recentOutputTail.length > RECENT_OUTPUT_TAIL_BYTES * 2) {
			recentOutputTail = recentOutputTail.slice(-RECENT_OUTPUT_TAIL_BYTES);
		}
	};

	const appendRecentOutputTail = (text: string) => {
		if (!text) return;
		recentOutputTail += text;
		trimRecentOutputTail();
		// O(chunk) hot path: this runs on every text_delta token (hundreds/
		// thousands per second while streaming). Line reconstruction is deferred
		// to refreshRecentOutput() at the emit boundary.
		recentOutputDirty = true;
	};

	const replaceRecentOutputFromContent = (content: unknown[]) => {
		recentOutputTail = "";
		for (const block of content) {
			if (!block || typeof block !== "object") continue;
			const record = block as { type?: unknown; text?: unknown };
			if (record.type !== "text" || typeof record.text !== "string") continue;
			if (!record.text) continue;
			recentOutputTail += record.text;
			trimRecentOutputTail();
		}
		recentOutputDirty = true;
	};

	const resetRecentOutput = () => {
		recentOutputTail = "";
		recentOutputDirty = false;
		progress.recentOutput = [];
	};

	const emitSubagentEvent = (event: AgentSessionEvent) => {
		const payload = { id, event };
		emitSubagentFrame(args.eventBus, args.subagentEventBus, TASK_SUBAGENT_EVENT_CHANNEL, payload);
	};

	const recordExtractedToolData = (toolName: string, data: unknown): void => {
		progress.extractedToolData = progress.extractedToolData || {};
		const existing = progress.extractedToolData[toolName] || [];
		existing.push(data);
		progress.extractedToolData[toolName] = existing;
		if (toolName === "yield") {
			const item = isRecord(data) ? data : undefined;
			const incremental = Array.isArray(item?.type) && item.type.length > 0;
			// A forced final yield ends the run. Once the reminder ladder has
			// pinned `toolChoice` to `yield`, an incremental section satisfies
			// the pin without terminating the run, so re-prompting loops
			// forever: take the section as the final report it was asked for.
			yieldCalled = !incremental || finalYieldForced || item?.complete === true || item?.status === "aborted";
			yieldCallPending = false;
			if (yieldCalled) {
				yieldInvalidatedByAsync = false;
				yieldAcceptedAt = Date.now();
				// Submitted: the remaining work is finalization (or waiting on owned
				// async jobs), so stop showing the last stale self-estimate.
				if (completionProbe) progress.completionPercent = 99;
				args.onYieldAccepted?.();
			}
		}
	};

	/**
	 * Tool calls in flight, by call id. Sibling calls run concurrently, so one call ending must not
	 * blank or relabel another that is still running: the live row shows the newest started call, and
	 * when that call ends it falls back to the oldest one still running.
	 */
	const activeTools = new Map<
		string,
		{ tool: string; args?: string; argsKey?: string; intent?: string; startMs: number }
	>();
	let visibleToolCallId: string | undefined;
	// Providers that run the tool loop server-side (Cursor) execute tools while
	// the assistant message is still streaming. Each such tool result feeds
	// another model step that never surfaces as its own message, so it counts
	// as a request; otherwise one message could run hundreds of steps unbudgeted.
	// Parallel calls of one step count separately: Cursor's stream does not mark
	// step boundaries, so such a turn reaches its budget early.
	let assistantStreaming = false;

	/**
	 * Soft request budget: steer at the budget, stop the free-running turn at
	 * 1.5x, and hard-abort {@link BUDGET_STOP_GRACE_REQUESTS} requests later if
	 * the forced final yield never lands.
	 */
	const evaluateSoftRequestBudget = () => {
		if (softRequestBudget <= 0 || abortSent) return;
		const stopThreshold = softRequestBudget * 1.5;
		if (budgetStopRequested) {
			// Grace window after the stop: the forced yield needs a request or
			// two; a child that keeps burning requests instead of yielding is
			// hard-aborted.
			if (progress.requests >= stopThreshold + BUDGET_STOP_GRACE_REQUESTS) {
				requestAbort("budget");
			}
			return;
		}
		if (progress.requests >= stopThreshold) {
			requestBudgetStop();
			return;
		}
		if (!softRequestBudgetNotice || budgetSteerSent || progress.requests < softRequestBudget) return;
		budgetSteerSent = true;
		const steerSession = activeSession;
		if (!steerSession) return;
		// Build the notice now (the count at crossing time), but send behind an
		// async boundary: a synchronously-throwing send must never take down
		// event processing (which escalates to terminate).
		const notice = buildBudgetNotice(progress.requests, softRequestBudget);
		void Promise.resolve()
			.then(() => steerSession.sendUserMessage(notice, { deliverAs: "steer", attribution: "agent" }))
			.catch(err => {
				logger.warn("Subagent budget steer failed", {
					error: err instanceof Error ? err.message : String(err),
				});
			});
	};

	const processEvent = (event: AgentEvent) => {
		if (resolved) return;
		const now = Date.now();
		let flushProgress = false;

		switch (event.type) {
			case "message_start":
				if (event.message?.role === "assistant") {
					assistantStreaming = true;
					resetRecentOutput();
				}
				// An async-result follow-up injected after a recorded yield
				// supersedes that yield: its payload predates the job outcome the
				// model is now being shown. Un-latch so the quiescence barrier's
				// reminder ladder demands a fresh yield. Guarded on the run signal:
				// once the run is completing, late injections must not destabilize
				// the settled classification.
				if (yieldCalled && !abortSignal.aborted && isAsyncResultInjection(event.message)) {
					yieldCalled = false;
					yieldInvalidatedByAsync = true;
					yieldAcceptedAt = undefined;
				}
				break;

			case "tool_execution_start": {
				progress.toolCount++;
				progress.currentTool = event.toolName;
				let startArgs: Record<string, unknown> = {};
				if ("toolArgs" in event && isRecord(event.toolArgs)) {
					startArgs = event.toolArgs;
				} else if (isRecord(event.args)) {
					startArgs = event.args;
				}
				const editMode =
					event.toolName === "apply_patch"
						? "apply_patch"
						: ((activeSession?.getToolByName(event.toolName) as { mode?: EditMode } | undefined)?.mode ??
							undefined);
				const preview = extractToolArgsPreview(startArgs, event.toolName, editMode);
				progress.currentToolArgs = preview?.value;
				progress.currentToolArgsKey = preview?.key;
				progress.currentToolStartMs = now;
				const intent = event.intent?.trim() || undefined;
				// Per call: intent-optional tools (e.g. MCP) start without one, and
				// `lastIntent` would otherwise label them with the previous call's.
				progress.currentToolIntent = intent;
				activeTools.set(event.toolCallId, {
					tool: event.toolName,
					args: preview?.value,
					argsKey: preview?.key,
					intent,
					startMs: now,
				});
				visibleToolCallId = event.toolCallId;
				// A fast tool may finish before the coalesced update fires.
				// Publish both lifecycle edges rather than dropping its start.
				flushProgress = true;
				if (intent) {
					progress.lastIntent = intent;
				}
				if (event.toolName === "yield" && !yieldCalled) {
					yieldCallPending = true;
				}
				// Reset any prior in-flight task snapshot so we don't show stale
				// nested progress when the agent enters a fresh `task` call.
				if (event.toolName === "task") {
					progress.inflightTaskDetails = undefined;
				}
				break;
			}

			case "tool_execution_end": {
				const finished = activeTools.get(event.toolCallId);
				activeTools.delete(event.toolCallId);
				if (finished) {
					progress.recentTools.unshift({
						tool: finished.tool,
						args: finished.args ?? "",
						argsKey: finished.argsKey,
						intent: finished.intent,
						isError: event.isError,
						endMs: now,
					});
					// Keep only last 5
					if (progress.recentTools.length > 5) {
						progress.recentTools.pop();
					}
				}
				if (args.onToolResult) {
					const content: unknown = isRecord(event.result) ? event.result.content : undefined;
					const text = Array.isArray(content)
						? content
								.flatMap(part =>
									isRecord(part) && part.type === "text" && typeof part.text === "string" ? [part.text] : [],
								)
								.join("\n")
						: "";
					args.onToolResult({
						tool: event.toolName,
						intent: finished?.intent,
						text,
						isError: event.isError === true,
					});
				}
				if (visibleToolCallId === event.toolCallId) {
					const remaining = activeTools.entries().next().value;
					visibleToolCallId = remaining?.[0];
					const visible = remaining?.[1];
					progress.currentTool = visible?.tool;
					progress.currentToolArgs = visible?.args;
					progress.currentToolArgsKey = visible?.argsKey;
					progress.currentToolIntent = visible?.intent;
					progress.currentToolStartMs = visible?.startMs;
				}
				// The finalized TaskToolDetails will be captured below into
				// `extractedToolData.task`; drop the in-flight snapshot so the
				// renderer doesn't double-count it against the final entry.
				if (event.toolName === "task") {
					progress.inflightTaskDetails = undefined;
				}

				// Check for registered subagent tool handler
				const handler = subprocessToolRegistry.getHandler(event.toolName);
				const eventRecord: unknown = event;
				const eventArgs = isRecord(eventRecord) && isRecord(eventRecord.args) ? eventRecord.args : {};
				let endsRun = false;
				if (handler) {
					// Extract data using handler
					if (handler.extractData) {
						const data = handler.extractData({
							toolName: event.toolName,
							toolCallId: event.toolCallId,
							args: eventArgs,
							result: event.result,
							isError: event.isError,
						});
						if (data !== undefined) {
							recordExtractedToolData(event.toolName, data);
						}
					}

					if (event.toolName === "yield") {
						yieldCallPending = false;
						if (budgetCheckDeferred) {
							budgetCheckDeferred = false;
							// The yield validated without ending the run: the turn
							// that submitted it still counts against the budget.
							if (!yieldCalled) evaluateSoftRequestBudget();
						}
					}

					// Check if the handler wants to terminate the session. A forced
					// final yield terminates too: it was accepted as terminal above,
					// and leaving the turn running would let the pinned model answer
					// with another incremental section instead of finishing.
					const wantsTerminate =
						handler.shouldTerminate?.({
							toolName: event.toolName,
							toolCallId: event.toolCallId,
							args: eventArgs,
							result: event.result,
							isError: event.isError,
						}) === true;
					const forcedFinalYield = event.toolName === "yield" && finalYieldForced && yieldCalled;
					endsRun = wantsTerminate || forcedFinalYield;
					if (endsRun) {
						if (event.toolName === "yield" && sessionHasPendingAsyncWork()) {
							// Terminal yield with owner jobs still pending: park the
							// run behind the quiescence barrier instead of completing
							// it (see requestYieldTurnStop).
							requestYieldTurnStop();
						} else {
							requestAbort("terminate");
						}
					}
				}
				if (event.toolName === "yield") {
					if (event.isError && !abortSent) {
						consecutiveYieldToolErrors++;
						let yieldErrorText = "";
						const resultContent = event.result?.content;
						if (Array.isArray(resultContent)) {
							const textParts: string[] = [];
							for (const block of resultContent) {
								if (
									block &&
									typeof block === "object" &&
									"type" in block &&
									block.type === "text" &&
									"text" in block &&
									typeof block.text === "string"
								) {
									textParts.push(block.text);
								}
							}
							yieldErrorText = textParts.join("\n").trim();
						}
						if (consecutiveYieldToolErrors >= MAX_YIELD_TOOL_ERRORS) {
							const suffix = yieldErrorText ? ` Last yield error: ${yieldErrorText}` : "";
							failWithError(
								`Subagent submitted invalid yield results ${consecutiveYieldToolErrors} times; stopping to avoid an infinite submit loop.${suffix}`,
							);
						}
					} else if (!event.isError) {
						consecutiveYieldToolErrors = 0;
					}
				}
				flushProgress = true;
				if (assistantStreaming && !endsRun) {
					progress.requests += 1;
					// A sibling yield still validating may be the run's terminal
					// report; checking now could abort the response before it lands.
					if (yieldCallPending) budgetCheckDeferred = true;
					else evaluateSoftRequestBudget();
				}
				break;
			}

			case "tool_execution_update": {
				// Surface nested-subagent progress mid-flight. The child task
				// tool emits incremental `onUpdate` calls carrying its current
				// `TaskToolDetails` (results + progress); we stash the latest
				// snapshot so the parent UI can render the in-flight subtree
				// without waiting for the call to finish.
				if (event.toolName === "task") {
					const partial = (event as { partialResult?: { details?: unknown } }).partialResult;
					const details = partial && typeof partial === "object" ? partial.details : undefined;
					if (details && typeof details === "object" && "results" in (details as TaskToolDetails)) {
						progress.inflightTaskDetails = details as TaskToolDetails;
						flushProgress = true;
					}
				}
				break;
			}

			case "message_update": {
				if (event.message?.role !== "assistant") break;
				const assistantEvent = (
					event as AgentEvent & {
						assistantMessageEvent?: { type?: string; delta?: string };
					}
				).assistantMessageEvent;
				if (assistantEvent?.type === "text_delta" && typeof assistantEvent.delta === "string") {
					appendRecentOutputTail(assistantEvent.delta);
					break;
				}
				if (assistantEvent && assistantEvent.type !== "text_delta") {
					break;
				}
				const updateContent =
					getMessageContent(event.message) || (event as AgentEvent & { content?: unknown }).content;
				if (updateContent && Array.isArray(updateContent)) {
					replaceRecentOutputFromContent(updateContent);
				}
				break;
			}

			case "message_end": {
				// Extract text from assistant and toolResult messages (not user prompts)
				const role = event.message?.role;
				if (role === "assistant") {
					assistantStreaming = false;
					sawAssistantMessage = true;
					progress.requests += 1;
					const eventContent = isRecord(event) && "content" in event ? event.content : undefined;
					const messageContent = getMessageContent(event.message) || eventContent;
					if (messageContent && Array.isArray(messageContent)) {
						const turnText: string[] = [];
						let startedMoreWork = false;
						let completedServerWork = false;
						for (const block of messageContent) {
							if (!isRecord(block)) continue;
							if (block.type === "text" && typeof block.text === "string") {
								outputChunks.push(block.text);
								if (block.text) turnText.push(block.text);
								continue;
							}
							if (block.type !== "toolCall" || typeof block.name !== "string") continue;
							if (block.name === "yield") {
								if (!yieldCalled) {
									yieldCallPending = true;
									flushProgress = true;
								}
								continue;
							}
							if (isCursorExecResolved(block)) completedServerWork = true;
							else startedMoreWork = true;
							turnText.length = 0;
						}
						// Locally runnable calls make all prose in or before this turn
						// mid-work narration. Cursor exec-resolved calls already ran, so
						// text after the last one is a report; without such text, prior
						// prose predates that work and is invalidated.
						const text = turnText.join("\n");
						if (startedMoreWork) lastReportTurnText = undefined;
						else if (text.trim()) lastReportTurnText = text;
						else if (completedServerWork) lastReportTurnText = undefined;
					}
					// A yield awaiting validation suppresses the budget check for
					// its own turn (#5006). Defer it rather than drop it: every
					// yield turn latches the pending flag, so dropping the check
					// lets a run of yield-only turns never account for a request.
					if (yieldCallPending) budgetCheckDeferred = true;
					else evaluateSoftRequestBudget();
				}
				// Extract and accumulate usage (prefer message.usage, fallback to event.usage)
				const eventUsage = isRecord(event) && "usage" in event ? event.usage : undefined;
				const messageUsage = getMessageUsage(event.message) || eventUsage;
				if (isRecord(messageUsage)) {
					// Only count assistant messages (not tool results, etc.)
					if (role === "assistant") {
						const costRecord = isRecord(messageUsage.cost) ? messageUsage.cost : undefined;
						hasUsage = true;
						accumulatedUsage.input += getNumberField(messageUsage, "input") ?? 0;
						accumulatedUsage.output += getNumberField(messageUsage, "output") ?? 0;
						accumulatedUsage.cacheRead += getNumberField(messageUsage, "cacheRead") ?? 0;
						accumulatedUsage.cacheWrite += getNumberField(messageUsage, "cacheWrite") ?? 0;
						accumulatedUsage.totalTokens += getNumberField(messageUsage, "totalTokens") ?? 0;
						accumulatedUsage.reasoningTokens =
							(accumulatedUsage.reasoningTokens ?? 0) + (getNumberField(messageUsage, "reasoningTokens") ?? 0);
						if (costRecord) {
							accumulatedUsage.cost.input += getNumberField(costRecord, "input") ?? 0;
							accumulatedUsage.cost.output += getNumberField(costRecord, "output") ?? 0;
							accumulatedUsage.cost.cacheRead += getNumberField(costRecord, "cacheRead") ?? 0;
							accumulatedUsage.cost.cacheWrite += getNumberField(costRecord, "cacheWrite") ?? 0;
							accumulatedUsage.cost.total += getNumberField(costRecord, "total") ?? 0;
							progress.cost = accumulatedUsage.cost.total;
						}
					}
					// Accumulate tokens for progress display
					progress.tokens += getUsageTokens(messageUsage);
					// Track latest per-turn context size so the UI can show
					// "current context", not just cumulative billing volume.
					if (role === "assistant") {
						const perTurnTotal = getNumberField(messageUsage, "totalTokens");
						if (perTurnTotal !== undefined && perTurnTotal > 0) {
							progress.contextTokens = perTurnTotal;
						}
					}
				}
				break;
			}

			case "agent_end":
				// Extract final content from assistant messages only (not user prompts)
				if (event.messages && Array.isArray(event.messages)) {
					for (const msg of event.messages) {
						if ((msg as { role?: string })?.role !== "assistant") continue;
						const messageContent = getMessageContent(msg);
						if (messageContent && Array.isArray(messageContent)) {
							for (const block of messageContent) {
								if (block.type === "text" && block.text) {
									finalOutputChunks.push(block.text);
								}
							}
						}
					}
				}
				flushProgress = true;
				break;
		}

		scheduleProgress(flushProgress);
	};

	const publishAdvisorState = (session: AgentSession | null): void => {
		// A runtime can attach after startup when model discovery finishes.
		// Retain this run's advised state through teardown for settled badges.
		if (!progress.advisor && session?.isAdvisorActive() === true) {
			progress.advisor = true;
			scheduleProgress(true);
		}
	};

	const attach = (session: AgentSession): (() => void) => {
		// The session owns attribution: it knows which model produced its output
		// and withholds an armed-but-unproven fallback. Re-deriving that here from
		// the event stream got it wrong twice over — the stream also carries
		// advisor turns running on a different model, and a routing switch was
		// read as evidence the target had served.
		const publishServingModel = (): void => {
			const serving = session.servingModel;
			if (!serving) return;
			const isFallback = serving.isFallback;
			// A model swap moves the window the usage gauge divides by. Without
			// this the Agent Hub kept the startup model's window while labelling
			// the row with the fallback that replaced it. Models with no declared
			// window keep the last known one rather than blanking the gauge.
			const contextWindow =
				serving.contextWindow && serving.contextWindow > 0 ? serving.contextWindow : progress.contextWindow;
			if (
				serving.selector === progress.resolvedModel &&
				serving.modelIdentity === progress.resolvedModelIdentity &&
				serving.thinkingLevel === progress.resolvedThinkingLevel &&
				(progress.resolvedModelIsFallback ?? false) === isFallback &&
				contextWindow === progress.contextWindow
			) {
				return;
			}
			progress.resolvedModel = serving.selector;
			progress.resolvedModelIdentity = serving.modelIdentity;
			progress.resolvedThinkingLevel = serving.thinkingLevel;
			progress.resolvedModelIsFallback = isFallback;
			progress.contextWindow = contextWindow;
			scheduleProgress(true);
		};
		return session.subscribe(event => {
			emitSubagentEvent(event);
			publishAdvisorState(session);
			publishServingModel();
			if (event.type === "auto_retry_start") {
				progress.retryState = {
					attempt: event.attempt,
					maxAttempts: event.maxAttempts,
					delayMs: event.delayMs,
					errorMessage: event.errorMessage,
					startedAtMs: Date.now(),
				};
				progress.retryFailure = undefined;
				scheduleProgress(true);
				return;
			}
			if (event.type === "auto_retry_end") {
				const attempt = progress.retryState?.attempt ?? event.attempt;
				progress.retryState = undefined;
				if (!event.success) {
					progress.retryFailure = {
						attempt,
						errorMessage: event.finalError ?? "Auto-retry failed",
					};
				}
				scheduleProgress(true);
				return;
			}
			if (isAgentEvent(event)) {
				// Breadcrumb the synchronous subagent event handling so the loop
				// watchdog can attribute any block to this in-process subagent.
				pushLoopPhase(`subagent:${id}`);
				try {
					processEvent(event);
				} catch (err) {
					logger.error("Subagent event processing failed", {
						error: err instanceof Error ? err.message : String(err),
					});
					requestAbort("terminate");
				} finally {
					popLoopPhase();
				}
			}
		});
	};

	const captureSalvage = (session: AgentSession): void => {
		// Best-effort salvage: capture the last assistant text so
		// cancelled/aborted children can surface "last activity" instead of
		// "(no output)".
		try {
			const lastContent = session.getLastAssistantMessage()?.content;
			if (Array.isArray(lastContent)) {
				const text = lastContent
					.map(block => (block.type === "text" && typeof block.text === "string" ? block.text : ""))
					.filter(Boolean)
					.join("\n");
				if (text.trim()) {
					lastAssistantSalvageText = text;
				}
			}
		} catch {
			// Salvage is best-effort; partial sessions may not implement it
		}
	};

	return {
		progress,
		abortSignal,
		accumulatedUsage,
		hasUsage: () => hasUsage,
		yieldCalled: () => yieldCalled,
		markFinalYieldForced: (forced: boolean) => {
			finalYieldForced = forced;
		},
		yieldAcceptedAt: () => yieldAcceptedAt,
		runtimeLimitExceeded: () => runtimeLimitExceeded,
		terminalError: () => terminalError,
		hasExplicitAbortReason: () =>
			abortReason === "signal" ||
			abortReason === "shutdown" ||
			runtimeLimitExceeded ||
			budgetLimitExceeded ||
			budgetStopRequested,
		budgetStopRequested: () => budgetStopRequested,
		waitForBudgetStop: () => budgetStopAbortPromise ?? Promise.resolve(),
		yieldInvalidatedByAsync: () => yieldInvalidatedByAsync,
		yieldTurnStopRequested: () => yieldTurnStopRequested,
		waitForYieldTurnStop: async () => {
			const pending = yieldTurnStopPromise;
			if (!pending) {
				yieldTurnStopRequested = false;
				return;
			}
			try {
				await pending;
			} finally {
				// Clear only after the abort settled so the idempotence gate in
				// requestYieldTurnStop stays closed while it is in flight.
				if (yieldTurnStopPromise === pending) {
					yieldTurnStopPromise = null;
					yieldTurnStopRequested = false;
				}
			}
		},
		// A soft stop that never escalated still identifies as a budget abort so
		// the lifecycle can park the agent as resumable instead of killing it.
		abortKind: () => abortReason ?? (budgetStopRequested ? "budget" : undefined),
		isAbortedRun: () =>
			abortReason === "signal" ||
			abortReason === "shutdown" ||
			runtimeLimitExceeded ||
			budgetLimitExceeded ||
			abortReason === undefined,
		requestAbort,
		failWithError,
		abortActiveSession,
		waitForActiveSessionAbort,
		resolveSignalAbortReason,
		resolveAbortReasonText,
		setActiveSession: session => {
			activeSession = session;
			publishAdvisorState(session);
			if (session && completionProbe && !completionProbeStarted) {
				completionProbeStarted = true;
				startCompletionProbe({
					session: () => activeSession,
					signal: AbortSignal.any([listenerSignal, abortSignal]),
					onEstimate: (estimate, cost) => {
						if (resolved) return;
						// A probe in flight when the yield landed must not pull the bar back from 99%
						// or relabel the finished run with a stale step.
						if (!yieldCalled) {
							progress.completionPercent = estimate.percent;
							if (estimate.stage !== undefined) progress.stage = estimate.stage;
						}
						if (estimate.watch !== undefined) progress.watch = estimate.watch;
						progress.cost += cost;
						scheduleProgress(true);
					},
				});
			}
		},
		takeActiveSession: () => {
			const session = activeSession;
			activeSession = null;
			return session;
		},
		attach,
		captureSalvage,
		lastAssistantSalvageText: () => lastAssistantSalvageText,
		lastReportTurnText: () => lastReportTurnText,
		sawAssistantMessage: () => sawAssistantMessage,
		rawOutput: () => (finalOutputChunks.length > 0 ? finalOutputChunks.join("") : outputChunks.join("")),
		scheduleProgress,
		finish: () => {
			resolved = true;
			listenerController.abort();
			if (runtimeTimeoutId !== undefined) {
				clearTimeout(runtimeTimeoutId);
				runtimeTimeoutId = undefined;
			}
			if (progressTimeoutId) {
				clearTimeout(progressTimeoutId);
				progressTimeoutId = null;
			}
		},
	};
}

interface DriveOutcome {
	exitCode: number;
	error?: string;
	aborted: boolean;
	abortReasonText?: string;
}

/**
 * Whether a settled drive handed over its final result — an accepted `yield`,
 * or for a message-result run a clean finish on a non-empty report turn — so
 * the caller can mark the registry ref accepted.
 */
function resultDelivered(outcome: DriveOutcome, monitor: SubagentRunMonitor, structured: boolean): boolean {
	if (structured) return monitor.yieldCalled();
	return outcome.exitCode === 0 && !outcome.aborted && monitor.lastReportTurnText() !== undefined;
}

const MAX_YIELD_RETRIES = 3;
const MAX_PROMPT_DISPATCH_ATTEMPTS = 4;
const PROMPT_DISPATCH_IDLE_TIMEOUT_MS = 5_000;

class PromptDispatchError extends Error {}

/**
 * Drive one assignment through a live session: send the prompt (with `restore`,
 * go on with the turn the previous process left unfinished instead:
 * {@link AgentSession.restoreInterruptedTurn}), wait for idle,
 * remind the agent to `yield` (up to {@link MAX_YIELD_RETRIES} times), then
 * classify the terminal assistant state. A soft-budget stop short-circuits the
 * reminder ladder into a single forced final yield so partial findings still
 * come back as a real report. Without a `yield` tool (`structured: false`) an
 * idle turn already ended on the final message, so only a budget stop prompts
 * again: one tool-less wrap-up turn.
 */
async function driveSessionToResult(
	session: AgentSession,
	monitor: SubagentRunMonitor,
	task: string,
	options: {
		/** Open-endedness description forwarded to the session's `auto` thinking classifier. */
		solutionSpace?: string;
		/** `false` = no `yield` tool; the final assistant message is the result. Default `true`. */
		structured?: boolean;
		/**
		 * Invoked when the initial prompt loses a prompt race (AgentBusyError) before
		 * retrying. Lets the caller restore a safe contract and detach its monitor
		 * while backing off. Absent, the busy error keeps the old path.
		 */
		onPromptBusy?: () => Promise<void>;
		/** Go on with the interrupted turn instead of sending `task`, which only labels the run. */
		restore?: boolean;
		/** Release queued idle deliveries after the initial restored attempt reaches idle. */
		onRestoreSettled?: () => void;
	} = {},
): Promise<DriveOutcome> {
	const { solutionSpace, onPromptBusy, restore } = options;
	const structured = options.structured !== false;
	const abortSignal = monitor.abortSignal;
	let exitCode = 0;
	let error: string | undefined;
	let aborted = false;
	let abortReasonText: string | undefined;
	const checkAbort = () => {
		if (abortSignal.aborted) {
			aborted = monitor.isAbortedRun();
			if (aborted) {
				abortReasonText ??= monitor.resolveAbortReasonText();
			}
			exitCode = 1;
			throw new ToolAbortError();
		}
	};
	const awaitAbortable = async <T>(promise: Promise<T>): Promise<T> => {
		checkAbort();
		const { promise: abortPromise, reject } = Promise.withResolvers<never>();
		const onAbort = () => {
			try {
				checkAbort();
			} catch (err) {
				reject(err);
			}
		};
		abortSignal.addEventListener("abort", onAbort, { once: true });
		try {
			return await Promise.race([promise, abortPromise]);
		} finally {
			abortSignal.removeEventListener("abort", onAbort);
		}
	};
	/**
	 * Send a headless prompt, retrying pre-provider drops (`PromptDroppedError`).
	 * Local slash commands are disabled so an assignment always reaches the
	 * model. `forceFinalYield` arms the monitor's forced-final latch only while
	 * an attempt dispatches, so another turn's incremental `yield` during drop
	 * recovery stays incremental.
	 */
	const dispatchPrompt = async (
		text: string,
		promptOptions: PromptOptions,
		label: string,
		{ forceFinalYield = false }: { forceFinalYield?: boolean } = {},
	): Promise<void> => {
		for (let attempt = 1; attempt <= MAX_PROMPT_DISPATCH_ATTEMPTS; attempt++) {
			if (forceFinalYield) monitor.markFinalYieldForced(true);
			try {
				await awaitAbortable(session.prompt(text, { ...promptOptions, runCommands: false, throwOnDrop: true }));
				return;
			} catch (err) {
				if (!(err instanceof PromptDroppedError)) throw err;
			}
			if (forceFinalYield) monitor.markFinalYieldForced(false);
			if (attempt === MAX_PROMPT_DISPATCH_ATTEMPTS) {
				throw new PromptDispatchError(`${label} dropped before provider dispatch after ${attempt} attempts`);
			}
			const deadline = AbortSignal.timeout(PROMPT_DISPATCH_IDLE_TIMEOUT_MS);
			try {
				await untilAborted(AbortSignal.any([abortSignal, deadline]), () => session.waitForIdle());
			} catch (err) {
				checkAbort();
				if (deadline.aborted) {
					throw new PromptDispatchError(`${label} dropped before provider dispatch; session did not become idle`);
				}
				throw err;
			}
			await untilAborted(abortSignal, () => Bun.sleep(250 * 2 ** (attempt - 1)));
		}
	};

	try {
		try {
			// An IRC wake may own the session when this turn dispatches. Its prompt
			// wins the race and this prompt throws AgentBusyError; back off through
			// the caller hook and retry. Bounded so a wedged worker still resolves
			// instead of hanging the batch.
			let promptAttempts = 0;
			for (;;) {
				try {
					if (restore) {
						try {
							await awaitAbortable(session.restoreInterruptedTurn());
							await awaitAbortable(session.waitForIdle());
						} finally {
							options.onRestoreSettled?.();
						}
					} else await dispatchPrompt(task, { attribution: "agent", solutionSpace }, "initial prompt");
					break;
				} catch (error) {
					promptAttempts++;
					if (!(error instanceof AgentBusyError) || promptAttempts >= 3 || !onPromptBusy) throw error;
					await onPromptBusy();
				}
			}
			await awaitAbortable(session.waitForIdle());
		} catch (err) {
			// A budget stop or a yield turn-stop (terminal yield parked behind
			// the async quiescence barrier) cancels the free-running turn by
			// aborting the session, which can surface here as a rejected
			// prompt. Swallow it and drive the barrier/forced final yield
			// below; real caller/timeout aborts (monitor signal) and genuine
			// failures keep the old path.
			const recoverableStop = monitor.budgetStopRequested() || monitor.yieldTurnStopRequested();
			if (!recoverableStop || abortSignal.aborted || err instanceof PromptDispatchError) throw err;
		}

		// The forced final turn must answer through `yield`, or with no tools at all.
		const reminderToolChoice = structured ? buildNamedToolChoice("yield", session.model) : "none";

		const runYieldLadder = async (): Promise<void> => {
			let retryCount = 0;
			let retriesForced = false;
			while (!monitor.yieldCalled() && retryCount < MAX_YIELD_RETRIES && !abortSignal.aborted) {
				// A budget stop collapses the reminder ladder to a single forced
				// final yield: wait for the stop's session abort to settle, then
				// prompt once with the wrap-up reminder + named tool choice.
				const budgetStop = monitor.budgetStopRequested();
				if (!structured && !budgetStop) break;
				if (budgetStop) {
					retryCount = MAX_YIELD_RETRIES - 1;
					await monitor.waitForBudgetStop();
					if (monitor.yieldCalled() || abortSignal.aborted) break;
				}
				// Skip reminders when the model returned a terminal error (e.g.
				// rate-limit cap hit, auth failure). Re-prompting would just
				// hit the same wall, multiplying the failure noise without
				// any chance of producing a yield.
				const lastBeforeReminder = session.getLastAssistantMessage();
				if (lastBeforeReminder?.stopReason === "error") break;
				// A turn waiting on owner work is a scheduling pause. The outer
				// barrier settles that work before a reminder counts against it.
				if (!budgetStop && session.hasPendingAsyncWork()) break;
				try {
					retryCount++;
					const reminder = prompt.render(submitReminderTemplate, {
						retryCount,
						maxRetries: MAX_YIELD_RETRIES,
						budgetStop,
						structured,
					});

					const isFinalRetry = retryCount >= MAX_YIELD_RETRIES;
					// Last chance: the next accepted yield ends the run, incremental
					// or not, so the pinned model cannot answer the pin forever.
					// Armed for this prompt's turn only — the quiescence barrier's
					// later notice turn may legitimately submit more sections.
					retriesForced = isFinalRetry;
					await dispatchPrompt(
						reminder,
						{
							attribution: "agent",
							synthetic: true,
							...(isFinalRetry && reminderToolChoice ? { toolChoice: reminderToolChoice } : {}),
						},
						"yield reminder",
						{ forceFinalYield: isFinalRetry },
					);
					await awaitAbortable(session.waitForIdle());
				} catch (err) {
					if (err instanceof PromptDispatchError) throw err;
					if (abortSignal.aborted || err instanceof ToolAbortError) {
						// Benign control-flow exit — user cancel (^C) or compaction aborting
						// pending operations both surface here as ToolAbortError. The outer
						// catch and finally already mark the run aborted; logging at ERROR
						// would spam operator dashboards with non-failures.
						logger.debug("Subagent prompt aborted");
					} else {
						logger.error("Subagent prompt failed", {
							error: err instanceof Error ? err.message : String(err),
						});
					}
				} finally {
					if (retriesForced) {
						retriesForced = false;
						monitor.markFinalYieldForced(false);
					}
				}
			}
		};

		// Yield ladder + quiescence barrier (structured concurrency), one
		// loop: a turn without a yield first settles pending owner work, then
		// spends reminders only after there is nothing left to wait for.
		// A yield also waits for quiescence; each delivered result supersedes
		// the previous yield and demands a fresh one.
		//
		// A final yield with owner background jobs still running or
		// undelivered is a scheduling pause, not run completion — the monitor
		// parks such a yield with a recoverable turn-stop instead of
		// terminating the run. Jobs are settled and their results folded into
		// the run as async-result follow-up turns; each delivered result
		// supersedes the yield it postdates, so the reminder ladder re-runs
		// to demand a fresh yield that accounts for it. Only a yield with no
		// pending owner work left is terminal — the isolation runner captures
		// and destroys the worktree right after this run resolves, so no
		// owner job that could still re-wake the session may outlive it.
		// Suppressed (acknowledged / wait-watched) jobs never re-wake the run
		// and are reaped at teardown.
		//
		// Before blocking on running jobs after a yield, tell the model ONCE
		// what it is waiting on so it can stand by or cancel the job. A turn
		// without a yield settles its pending jobs without an extra notice.
		// Runs that exhaust the ladder with no pending work, or hit a terminal
		// model error, skip the barrier; teardown reaps their jobs.
		let asyncPendingNoticeSent = false;
		while (!abortSignal.aborted) {
			if (!monitor.yieldCalled()) {
				await runYieldLadder();
				if (
					!monitor.yieldCalled() &&
					(monitor.budgetStopRequested() ||
						session.getLastAssistantMessage()?.stopReason === "error" ||
						!session.hasPendingAsyncWork())
				)
					break;
			}
			// Let the parked yield's turn-stop session abort settle before
			// prompting again (mirrors waitForBudgetStop).
			await awaitAbortable(monitor.waitForYieldTurnStop());
			if (!session.hasPendingAsyncWork()) {
				if (monitor.yieldCalled()) break;
				continue;
			}
			if (!monitor.yieldCalled()) {
				await awaitAbortable(session.settleAsyncWork());
				continue;
			}
			if (!asyncPendingNoticeSent) {
				asyncPendingNoticeSent = true;
				const running = session.getAsyncJobSnapshot()?.running ?? [];
				if (running.length > 0) {
					const jobs = running.map(job => `${job.id}${job.label ? ` (${job.label})` : ""}`).join(", ");
					const notice = prompt.render(subagentAsyncPendingTemplate, {
						count: running.length,
						multiple: running.length > 1,
						jobs,
					});
					try {
						await dispatchPrompt(notice, { attribution: "agent", synthetic: true }, "async-pending notice");
						await awaitAbortable(session.waitForIdle());
					} catch (err) {
						if (abortSignal.aborted || err instanceof ToolAbortError || err instanceof PromptDispatchError)
							throw err;
						// Other notice-turn failures leave the pending jobs to settle passively.
						logger.warn("Subagent async-pending notice failed", {
							error: err instanceof Error ? err.message : String(err),
						});
					}
					// Re-evaluate: the notice turn may have cancelled, watched, or
					// absorbed the jobs — or already re-yielded.
					continue;
				}
			}
			await awaitAbortable(session.settleAsyncWork());
			// Results delivered during the settle invalidated the recorded
			// yield: the next iteration's ladder demands a fresh one.
		}

		if (!monitor.yieldCalled()) {
			await awaitAbortable(session.waitForIdle());
		}

		const lastAssistant = session.getLastAssistantMessage();
		if (lastAssistant) {
			if (lastAssistant.stopReason === "aborted") {
				if (!monitor.yieldCalled() || monitor.runtimeLimitExceeded()) {
					aborted = monitor.isAbortedRun();
					if (aborted) {
						// A real caller signal or the wall-clock timer carries a precise
						// reason (signal.reason / "runtime limit exceeded"). An internal
						// turn abort does NOT — prefer the assistant message's own
						// errorMessage ("Request was aborted" or a specific stream error)
						// over the misleading "Cancelled by caller".
						abortReasonText ??= monitor.hasExplicitAbortReason()
							? monitor.resolveAbortReasonText()
							: lastAssistant.errorMessage?.trim() || monitor.resolveAbortReasonText();
					}
					exitCode = 1;
				}
			} else if (lastAssistant.stopReason === "error") {
				exitCode = 1;
				error ??= attributeSubagentError(lastAssistant.errorMessage, lastAssistant);
			}
		}

		// A budget-stopped run that still produced no result (no yield, or no
		// clean final message) is a budget abort: surface the precise reason
		// instead of a generic missing-result failure.
		const delivered = structured ? monitor.yieldCalled() : lastAssistant?.stopReason === "stop";
		if (!delivered && monitor.budgetStopRequested() && !aborted) {
			aborted = true;
			abortReasonText ??= monitor.resolveAbortReasonText();
			exitCode = 1;
		}

		// A recorded yield that async-result deliveries superseded and the
		// model never refreshed is stale: fail the run instead of letting the
		// parent act on a payload that predates the background job outcomes
		// the model was shown. The stale payload still ships through
		// finalizeSubprocessOutput's failed-after-yield path (exit 1 + stderr,
		// output preserved as salvage).
		if (monitor.yieldInvalidatedByAsync() && !abortSignal.aborted) {
			exitCode = 1;
			error ??=
				"Background job results arrived after the subagent's last yield; it did not submit a refreshed yield covering them.";
		}
	} catch (err) {
		if (abortSignal.aborted && monitor.yieldCalled() && !monitor.runtimeLimitExceeded()) {
			exitCode = 0;
		} else {
			exitCode = 1;
			if (!abortSignal.aborted) {
				error = err instanceof Error ? err.stack || err.message : String(err);
			}
		}
	} finally {
		error ??= monitor.terminalError();
		if (abortSignal.aborted && (!monitor.yieldCalled() || monitor.runtimeLimitExceeded())) {
			aborted = monitor.isAbortedRun();
			if (aborted) {
				abortReasonText ??= monitor.resolveAbortReasonText();
			}
			if (exitCode === 0) exitCode = 1;
		}
	}

	return { exitCode, error, aborted, abortReasonText };
}

interface FinalizeRunArgs {
	monitor: SubagentRunMonitor;
	done: { exitCode: number; error?: string; aborted?: boolean; abortReason?: string; durationMs: number };
	index: number;
	id: string;
	agent: AgentDefinition;
	task: string;
	assignment?: string;
	modelOverride?: string | string[];
	/** Explicit pre-expansion model role alias selected for this run. */
	modelRole?: string;
	/** `false` = no `yield` tool: the run's last report turn is the result verbatim. Default `true`. */
	structured?: boolean;
	outputSchema?: unknown;
	outputSchemaMode?: StructuredSubagentSchemaMode;
	outputSchemaSource?: StructuredSubagentSchemaSource;
	signal?: AbortSignal;
	artifactsDir?: string;
	eventBus?: EventBus;
	subagentEventBus?: EventBus;
	parentToolCallId?: string;
	detached?: boolean;
	/**
	 * This finalize is a revival/wake or explicit follow-up turn, not the initial
	 * run. Structured turns only republish a real `yield`; message-result turns
	 * republish successful, non-empty reports only when the parent or the user
	 * requested the turn. These follow-up message results exclude peer replies
	 * and cancelled turns; the initial run is unaffected.
	 */
	followUpTurn?: boolean;
	publishMessageResult?: boolean;
	sessionFile?: string;
	startTime: number;
}

/**
 * Turn a settled run into a {@link SingleResult}: resolve the yield payload via
 * {@link finalizeSubprocessOutput}, salvage cancelled-run output, write the
 * `<id>.md` output artifact, flush final progress, and emit the lifecycle end
 * event.
 */
async function finalizeRunResult(args: FinalizeRunArgs): Promise<SingleResult> {
	const { monitor, done, index, id, agent, task, assignment, signal, modelOverride, modelRole } = args;
	const progress = monitor.progress;
	let exitCode = done.exitCode;
	let stderr = done.error ?? "";

	// A structured run finalizes from its yield (falling back to the run's
	// output); a message-result run is exactly its final report turn, never
	// the narration of earlier turns.
	const structured = args.structured !== false;
	let rawOutput = structured ? monitor.rawOutput() : (monitor.lastReportTurnText() ?? "");
	const yieldItems = progress.extractedToolData?.yield as YieldItem[] | undefined;
	// Breadcrumb the synchronous yield-payload shaping (O(rawOutput)) so a block
	// here is attributed to this subagent rather than logged as "unknown".
	pushLoopPhase(`subagent:${id}`);
	let finalized: FinalizeSubprocessOutputResult;
	try {
		finalized = finalizeSubprocessOutput({
			rawOutput,
			exitCode,
			stderr,
			doneAborted: Boolean(done.aborted),
			signalAborted: Boolean(signal?.aborted),
			yieldItems,
			outputSchema: args.outputSchema,
			outputSchemaMode: args.outputSchemaMode,
			outputSchemaSource: args.outputSchemaSource,
			lastAssistantText: monitor.lastReportTurnText(),
			structured,
		});
	} finally {
		popLoopPhase();
	}
	rawOutput = finalized.rawOutput;
	exitCode = finalized.exitCode;
	stderr = finalized.stderr;
	// Salvage for cancelled/aborted children that produced no completed output:
	// surface the last assistant text + stats instead of "(no output)" so the
	// parent doesn't redo work the child already finished.
	const salvageText = monitor.lastAssistantSalvageText();
	if (
		(done.aborted || signal?.aborted || monitor.runtimeLimitExceeded()) &&
		!rawOutput.trim() &&
		salvageText !== undefined
	) {
		rawOutput = `[cancelled after ${progress.requests} req, ${progress.tokens} tok — last activity: "${formatSalvageSnippet(salvageText)}"]`;
	}
	const lastYield = yieldItems?.[yieldItems.length - 1];
	const yieldAbortReason = lastYield?.status === "aborted" ? lastYield.error || "Subagent aborted task" : undefined;
	const { abortedViaYield, hasYield } = finalized;
	const { content: truncatedOutput, truncated } = truncateTail(rawOutput, {
		maxBytes: MAX_OUTPUT_BYTES,
		maxLines: MAX_OUTPUT_LINES,
	});

	// Write output artifact (input and jsonl already written in real-time).
	// Compute output metadata for agent:// URL integration.
	//
	// Structured follow-ups need a real yield so conversational wakes cannot
	// replace the accepted artifact with a missing-yield warning (issue #9518).
	// Message-result agents publish successful reports the parent or the user
	// asked for, not conversational replies to peers or cancelled follow-ups.
	let outputMeta: { lineCount: number; charCount: number } | undefined;
	let outputPath: string | undefined;
	const hasMessageResult =
		args.publishMessageResult &&
		!structured &&
		exitCode === 0 &&
		!done.aborted &&
		!signal?.aborted &&
		!monitor.runtimeLimitExceeded() &&
		rawOutput.trim().length > 0;
	if (args.artifactsDir && (!args.followUpTurn || hasYield || hasMessageResult)) {
		const candidatePath = path.join(args.artifactsDir, `${id}.md`);
		try {
			await writeArtifact(candidatePath, rawOutput);
			outputPath = candidatePath;
			outputMeta = {
				lineCount: rawOutput.split("\n").length,
				charCount: rawOutput.length,
			};
		} catch (error) {
			logger.warn("Failed to persist subagent output artifact", {
				agentId: id,
				path: candidatePath,
				error: error instanceof Error ? error.message : String(error),
			});
		}
		const structured = finalized.structuredOutput;
		const sidecarPath = path.join(args.artifactsDir, `${id}.json`);
		if (outputPath && structured && Object.hasOwn(structured, "data")) {
			try {
				const serialized = JSON.stringify(structured.data, null, 2);
				// `structured.data === undefined` (an own "data" key holding
				// `undefined`) makes JSON.stringify return `undefined` too —
				// neither a write nor a removal, which would leave a stale
				// sidecar from an earlier turn answering agent://<id>/<field>
				// with superseded data (PR #10625 review).
				if (serialized !== undefined) await writeArtifact(sidecarPath, `${serialized}\n`);
				else await fs.rm(sidecarPath, { force: true });
			} catch (error) {
				logger.warn("Failed to persist subagent structured output sidecar", {
					agentId: id,
					path: sidecarPath,
					error: error instanceof Error ? error.message : String(error),
				});
				// A stale sidecar from an earlier turn must not outlive this
				// turn's <id>.md just because the replacement write failed —
				// agent://<id>/<field> would keep answering with superseded data.
				try {
					await fs.rm(sidecarPath, { force: true });
				} catch (rmError) {
					logger.warn("Failed to drop stale subagent structured output sidecar", {
						agentId: id,
						path: sidecarPath,
						error: rmError instanceof Error ? rmError.message : String(rmError),
					});
				}
			}
		} else if (outputPath) {
			// This turn republished <id>.md; a stale sidecar from an earlier
			// turn would keep answering agent://<id>/<field> with the
			// superseded payload, so it must not outlive its <id>.md.
			try {
				await fs.rm(sidecarPath, { force: true });
			} catch (error) {
				logger.warn("Failed to drop stale subagent structured output sidecar", {
					agentId: id,
					path: sidecarPath,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}
	}

	// Update final progress. A wall-clock timeout always wins: if the runtime
	// limit fired we report aborted/failed regardless of whether a yield landed
	// while we were tearing the session down. The yield data is still surfaced
	// to the caller via `progress.extractedToolData`, but the exit status must
	// reflect the timeout so on-call doesn't mistake a stuck run for success.
	const runtimeLimitExceeded = monitor.runtimeLimitExceeded();
	if (runtimeLimitExceeded && exitCode === 0) {
		exitCode = 1;
	}
	const wasAborted =
		runtimeLimitExceeded || Boolean(done.aborted) || abortedViaYield || (!hasYield && Boolean(signal?.aborted));
	const finalAbortReason = wasAborted
		? runtimeLimitExceeded
			? monitor.resolveAbortReasonText()
			: done.aborted
				? (done.abortReason ?? monitor.resolveAbortReasonText())
				: abortedViaYield
					? yieldAbortReason
					: signal?.aborted
						? monitor.resolveSignalAbortReason()
						: monitor.resolveAbortReasonText()
		: undefined;
	progress.status = wasAborted ? "aborted" : exitCode === 0 ? "completed" : "failed";
	monitor.scheduleProgress(true);

	// Emit lifecycle end event after finalization so yield status is reflected
	const settledPayload = {
		id,
		agent: agent.name,
		parentToolCallId: args.parentToolCallId,
		detached: args.detached,
		agentSource: agent.source,
		description: progress.description,
		status: progress.status as "completed" | "failed" | "aborted",
		sessionFile: args.sessionFile,
		index,
	};
	emitSubagentFrame(args.eventBus, args.subagentEventBus, TASK_SUBAGENT_LIFECYCLE_CHANNEL, settledPayload);

	return {
		index,
		id,
		agent: agent.name,
		agentSource: agent.source,
		task,
		assignment,
		description: progress.description,
		lastIntent: progress.lastIntent,
		exitCode,
		output: truncatedOutput,
		stderr,
		truncated: Boolean(truncated),
		...(finalized.structuredOutput ? { structuredOutput: finalized.structuredOutput } : {}),
		durationMs: Date.now() - args.startTime,
		tokens: progress.tokens,
		requests: progress.requests,
		contextTokens: progress.contextTokens,
		contextWindow: progress.contextWindow,
		modelOverride,
		modelRole,
		resolvedModel: progress.resolvedModel,
		resolvedModelIdentity: progress.resolvedModelIdentity,
		resolvedThinkingLevel: progress.resolvedThinkingLevel,
		resolvedModelIsFallback: progress.resolvedModelIsFallback,
		resolvedModelRoute: progress.resolvedModelRoute,
		advisor: progress.advisor,
		error: exitCode !== 0 && stderr ? stderr : undefined,
		aborted: wasAborted,
		abortReason: finalAbortReason,
		usage: monitor.hasUsage() ? monitor.accumulatedUsage : undefined,
		outputPath,
		extractedToolData: progress.extractedToolData,
		retryFailure: progress.retryFailure,
		outputMeta,
	};
}

/** Inputs for {@link attachIrcWakeTurnMonitor}. */
export interface IrcWakeTurnMonitorOptions {
	/** Registry id of the kept-alive subagent whose undriven turns are monitored. */
	id: string;
	index?: number;
	agent: AgentDefinition;
	description?: string;
	modelOverride?: string | string[];
	/** Explicit pre-expansion model role alias selected for this run. */
	modelRole?: string;
	eventBus?: EventBus;
	subagentEventBus?: EventBus;
	parentToolCallId?: string;
	/** Fallback session file when the registry ref carries none. */
	sessionFile?: string;
	maxRuntimeMs?: number;
	/**
	 * Whether a turn the owner's own message woke asks for completion estimates
	 * (see {@link isCompletionProbeEnabled}); a peer-woken turn never does.
	 */
	completionProbe?: boolean;
	/** `false` = the session has no `yield` tool; see {@link ExecutorOptions.structured}. */
	structured?: boolean;
	outputSchema?: unknown;
	outputSchemaMode?: StructuredSubagentSchemaMode;
	outputSchemaSource?: StructuredSubagentSchemaSource;
	artifactsDir?: string;
}

/** Sender + message id of one `irc:incoming` record that woke a turn. */
interface WakeSource {
	from: string;
	messageId?: string;
}

function wakeSources(records: AgentMessage[], selfId: string): WakeSource[] {
	const sources: WakeSource[] = [];
	for (const record of records) {
		if (record.role !== "custom") continue;
		const details = record.details && typeof record.details === "object" ? record.details : undefined;
		const from = details ? Reflect.get(details, "from") : undefined;
		if (typeof from !== "string" || from === selfId || sources.some(source => source.from === from)) continue;
		// Automated wake-turn relays are answers, not wake sources: relaying one
		// back would ping-pong two idle peers forever. A broadcast leg is not one
		// either: it asks no one in particular, so relaying every woken peer's
		// turn back would flood the broadcaster with "not for me" replies.
		// A progress note promises a later answer and asks nothing back.
		if (
			details &&
			(Reflect.get(details, "wakeRelay") === true ||
				Reflect.get(details, "broadcast") === true ||
				Reflect.get(details, "progress") === true)
		)
			continue;
		const messageId = details ? Reflect.get(details, "id") : undefined;
		sources.push({ from, messageId: typeof messageId === "string" ? messageId : undefined });
	}
	return sources;
}

/**
 * Hand a woken subagent's turn output to whoever woke it, when the subagent
 * did not answer them itself. A re-`yield` delivers the `<task-result>`
 * envelope (the artifact was just rewritten, so it carries the `agent://`
 * pointer); a plain turn delivers its final assistant text. Without this, a
 * recipients without a dedicated messaging tool can still answer a sender;
 * otherwise their re-yield silently
 * updates the artifact nobody is told to re-read.
 */
async function relayWakeTurnOutput(args: {
	id: string;
	records: AgentMessage[];
	turnStartTime: number;
	yielded: boolean;
	result: SingleResult | undefined;
	turnText: string;
	/** Short, attributed peer-visible error text (no stack) when the turn died on an error. */
	error: string | undefined;
	/** Whether the turn was aborted (runtime limit, cancellation, hard abort). */
	aborted: boolean;
	/** Reason text for an aborted turn, from {@link SubagentRunMonitor.resolveAbortReasonText}. */
	abortReason: string | undefined;
	/** A {@link finalizeRunResult} throw, so the waiter is notified instead of stranded. */
	finalizeError: unknown;
	/** Waker already receiving this turn's outcome as an async job delivery. */
	jobOwnerId: string | undefined;
}): Promise<void> {
	const bus = IrcBus.global();
	const sources = wakeSources(args.records, args.id);
	if (sources.length === 0) return;
	const failed = wakeTurnFailed(args);
	for (const source of sources) {
		if (source.from === args.jobOwnerId) continue;
		const alreadyMessaged = bus.sentSince(args.id, source.from, args.turnStartTime);
		// A completed turn's answer would duplicate what the agent already sent
		// this waker, so dedup stays. A failed/cancelled turn is a distinct
		// lifecycle fact: `sentSince` cannot tell "already answered you" from
		// "pinged you 'on it'", and suppressing the failure notice on a mere ping
		// strands the waker exactly as before — one message later. So the failure
		// lane always notifies, flavoured to acknowledge the earlier message.
		if (alreadyMessaged && !failed) continue;
		const body = buildWakeRelayBody({ ...args, alreadyMessaged });
		if (!body) continue;
		const receipt = await bus.send({
			from: args.id,
			to: source.from,
			body,
			replyTo: source.messageId,
			wakeRelay: true,
		});
		if (receipt.outcome === "failed") {
			logger.warn("IRC wake-turn relay failed", { from: args.id, to: source.from, error: receipt.error });
		}
	}
}

/** Whether a wake turn died on an error, a cancellation, or a finalization throw instead of completing. */
function wakeTurnFailed(outcome: { error: string | undefined; aborted: boolean; finalizeError: unknown }): boolean {
	return outcome.error !== undefined || outcome.aborted || outcome.finalizeError !== undefined;
}

/**
 * Body for a wake-turn relay, distinguishing the terminal outcomes a waiter
 * would otherwise see as the same generic "stopped without replying" note:
 * a real answer (yield summary or turn text), a provider failure carrying the
 * attributed `[provider/model] <error>`, a cancellation with its reason, a
 * finalization throw, a completed turn whose only output was an IRC message
 * (`alreadyMessaged`, reached from the parent-owned wake job), or a turn that
 * ran and produced nothing. A turn that yielded an artifact before failing is
 * reported via that artifact's summary rather than contradicted with a "no
 * output" claim; on a failed turn, an `alreadyMessaged` waker is told the
 * earlier message was not the answer. Every
 * non-answer notice carries a `history://<id>` pointer so the peer can inspect
 * the transcript. Exported for a focused contract test of the yielded-failure
 * branch, which the observer seam cannot drive.
 */
export function buildWakeRelayBody(args: {
	id: string;
	yielded: boolean;
	result: SingleResult | undefined;
	turnText: string;
	error: string | undefined;
	aborted: boolean;
	abortReason: string | undefined;
	finalizeError: unknown;
	alreadyMessaged: boolean;
}): string {
	const transcript = `See history://${args.id} for details.`;
	// Computed once, above the completed/failed split: a turn that yielded an
	// artifact before failing must be reported, never contradicted.
	const summary =
		args.yielded && args.result?.outputPath
			? formatTaskResultSummary(args.result, { totalDurationMs: args.result.durationMs })
			: undefined;

	const headline = args.error
		? `Wake turn failed: ${args.error}.`
		: args.aborted
			? `Wake turn was cancelled${args.abortReason?.trim() ? `: ${args.abortReason.trim()}` : ""}.`
			: undefined;
	if (headline) {
		if (summary) {
			return `${headline} A result was recorded before the turn ended:\n\n${summary}\n\n${transcript}`;
		}
		const context = args.alreadyMessaged
			? "You received a message earlier in this turn, but that was not the answer and nothing further was sent."
			: "No answer was produced.";
		return `${headline} ${context} ${transcript}`;
	}

	// Peer relays filter already-messaged completed turns upstream; parent-owned
	// wake jobs still need an accurate completion when IRC was the only output.
	const answer = summary ?? args.turnText.trim();
	if (answer) return answer;
	if (args.finalizeError) {
		const message = args.finalizeError instanceof Error ? args.finalizeError.message : String(args.finalizeError);
		return `Wake turn failed to finalize: ${message}. No answer was produced. ${transcript}`;
	}
	if (args.alreadyMessaged) {
		return `Wake turn completed; ${args.id} sent a message during this turn. ${transcript}`;
	}
	return `Wake turn produced no output. ${transcript}`;
}

/** Extracts display text from an IRC/aside record's content, shared by the custom-role and
 *  user-role branches below (both fields share the same string | text-part-array shape). */
function extractIrcRecordText(content: string | ReadonlyArray<{ type: string; text?: string }>): string {
	if (typeof content === "string") return content;
	return content
		.filter(part => part.type === "text")
		.map(part => part.text ?? "")
		.join("\n");
}

/**
 * Bracket a kept-alive subagent's undriven turns — autonomous IRC wakes,
 * focused-session prompts and bare queued/async continuations — with a task
 * run monitor so RPC/collab subscribers see lifecycle/progress frames and
 * accepted results rewrite the artifact. Shared by the live executor reviver
 * and the persisted cold-revive path; the observer finishes after the session
 * has flushed its post-prompt settle (see {@link AgentSession.setIrcWakeTurnObserver}).
 *
 * The turn's output reaches the parent as an async job when its message woke
 * the turn, its mid-turn request was consumed, the turn yielded, or a user
 * prompt completed a message result, and the other waking peers via
 * {@link relayWakeTurnOutput}; the relay is registered as a pending reply on
 * the session up front so a `send await:true` waiter holds its "stopped
 * without replying" verdict until the relay has been delivered.
 */
export function attachIrcWakeTurnMonitor(session: AgentSession, options: IrcWakeTurnMonitorOptions): void {
	const { id, agent } = options;
	const index = options.index ?? 0;
	const maxRuntimeMs = options.maxRuntimeMs ?? 0;
	session.setIrcWakeTurnObserver(records => {
		// Autonomous IRC wake turns reuse the session's YieldTool just like
		// runSubagentFollowUpTurn; clear the prior run's incremental-section flag
		// and retry counters so this wake turn's guards see only its own state.
		resetYieldTurnState(session.getToolByName("yield"));
		const ircTask =
			records
				.map(record => {
					if (record.role === "custom") {
						const body =
							record.details && typeof record.details === "object"
								? Reflect.get(record.details, "message")
								: undefined;
						if (typeof body === "string") return body;
						return extractIrcRecordText(record.content);
					}
					// User prompts: typed text, or the synthetic `.`/`c` continue directive.
					if (record.role === "user" || record.role === "developer") return extractIrcRecordText(record.content);
					return "";
				})
				.filter(Boolean)
				.join("\n\n") || "IRC follow-up";
		const turnStartTime = Date.now();
		const relay = Promise.withResolvers<void>();
		session.trackIrcReply(relay.promise);
		const sessionFile = AgentRegistry.global().get(id)?.sessionFile ?? options.sessionFile ?? undefined;
		// The parent receives this turn's outcome through an owner-routed job:
		// ordinary async-result delivery, and what its `wait` blocks on. A
		// parent wake owns the whole turn; a mid-turn parent request owns it only
		// after its steer is consumed. Otherwise only an accepted yield registers
		// a job, before the ref goes idle.
		const ownerId = AgentRegistry.global().get(id)?.parentId;
		const ownerWoken = wakeSources(records, id).some(source => source.from === ownerId);
		// Cancelling the job cancels the turn it stands for.
		const jobCancel = new AbortController();
		// The turn's finished tool calls, which the job's widget reads like a first run's.
		const tools = new TextTap(TOOLS_SOURCE_ID, TOOLS_SOURCE_LABEL);
		let reportJobProgress: ((progress: AgentProgress) => void) | undefined;
		let wakeJob: { ownerId: string; outcome: PromiseWithResolvers<AsyncJobRunResult> } | undefined;
		const registerWakeJob = (): void => {
			if (wakeJob) return;
			const manager = session.asyncJobManager;
			if (!ownerId || !manager) return;
			const outcome = Promise.withResolvers<AsyncJobRunResult>();
			try {
				manager.register(
					"task",
					id,
					({ signal, reportProgress }) => {
						signal.addEventListener("abort", () => jobCancel.abort(signal.reason), { once: true });
						// The progress record is what `wait` reads the turn's stage and estimate from.
						reportJobProgress = progress => {
							void reportProgress(`Running background task ${id}...`, { progress: [progress] });
						};
						return untilAborted(signal, outcome.promise);
					},
					{
						id,
						agentId: id,
						ownerId,
						widgetInputs: createTaskWidgetInputs({
							manager,
							agentId: id,
							tools: () => tools,
							progress: turnMonitor.progress,
						}),
					},
				);
				wakeJob = { ownerId, outcome };
			} catch (error) {
				logger.warn("IRC wake-turn job registration failed", {
					id,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		};
		const turnMonitor = createSubagentRunMonitor({
			index,
			id,
			agent,
			task: ircTask,
			description: options.description,
			modelOverride: options.modelOverride,
			modelRole: options.modelRole,
			eventBus: options.eventBus,
			subagentEventBus: options.subagentEventBus,
			parentToolCallId: options.parentToolCallId,
			detached: true,
			sessionFile,
			softRequestBudget: 0,
			softRequestBudgetNotice: false,
			maxRuntimeMs,
			// A peer's message gets a short answer, too short to probe; the owner's message is an
			// assignment the owner waits on.
			completionProbe: ownerWoken && options.completionProbe === true,
			signal: jobCancel.signal,
			onProgress: progress => reportJobProgress?.(progress),
			onToolResult: result => appendToolResult(tools, result),
			onYieldAccepted: registerWakeJob,
		});

		const startedPayload = {
			id,
			agent: agent.name,
			parentToolCallId: options.parentToolCallId,
			detached: true,
			agentSource: agent.source,
			description: options.description,
			status: "started",
			sessionFile,
			index,
		} as const;
		emitSubagentFrame(options.eventBus, options.subagentEventBus, TASK_SUBAGENT_LIFECYCLE_CHANNEL, startedPayload);

		turnMonitor.setActiveSession(session);
		const unsubscribeTurn = turnMonitor.attach(session);
		if (ownerWoken) registerWakeJob();
		// Only a message_end from the agent loop proves the queued parent steer
		// entered this turn. Receipt alone cannot claim a peer's earlier answer.
		let ownerPrompted = false;
		const unsubscribeParentSteer = session.subscribe(event => {
			if (event.type !== "message_end" || !session.isParentIrcSteer(event.message)) return;
			ownerPrompted = true;
			registerWakeJob();
		});
		// A focused-session user prompt is the operator driving this agent (#14428):
		// like a parent follow-up, its message-result reply is the agent's new result.
		const userPrompted = records.some(record =>
			record.role === "user" ? record.attribution === "user" : record.role === "developer" && record.userInitiated,
		);
		return async turnError => {
			unsubscribeTurn();
			unsubscribeParentSteer();
			const activeSession = turnMonitor.takeActiveSession();
			if (activeSession) turnMonitor.captureSalvage(activeSession);
			const lastAssistant = session.getLastAssistantMessage();
			const yielded = turnMonitor.yieldCalled();
			const runtimeLimitExceeded = turnMonitor.runtimeLimitExceeded();
			const aborted = runtimeLimitExceeded || (lastAssistant?.stopReason === "aborted" && !yielded);
			// Two error lanes. `error` carries full diagnostics (a thrown turn
			// error's stack) for `done.error`, logs, and lifecycle. `errorForPeer`
			// carries only the short, attributed message: a stack trace injected
			// into another agent's model context is noise, not signal.
			const providerError =
				lastAssistant?.stopReason === "error"
					? attributeSubagentError(lastAssistant.errorMessage, lastAssistant)
					: undefined;
			const thrown = providerError === undefined && turnError !== undefined && !yielded ? turnError : undefined;
			const error =
				providerError ??
				(thrown instanceof Error
					? thrown.stack || thrown.message
					: thrown === undefined
						? undefined
						: String(thrown));
			const errorForPeer =
				providerError ??
				(thrown instanceof Error ? thrown.message : thrown === undefined ? undefined : String(thrown));
			turnMonitor.finish();
			if (yielded) {
				// Acceptance boundary for an autonomous wake turn (#11079): the
				// turn's terminal yield is settled, so terminalize the ref here
				// even when the run-state mirror never delivers `idle`.
				AgentRegistry.global().markResultAccepted(id, session, turnMonitor.yieldAcceptedAt());
			}
			// Read before finalization: a schema-bearing agent that answered in
			// prose gets a missing-yield warning prepended to `result.output`.
			// Like a first run's message result, the answer is the final report
			// turn; the session's last assistant text stands in only when the
			// monitor saw no assistant message, never for narration it set aside.
			const turnText =
				turnMonitor.lastReportTurnText() ??
				(turnMonitor.sawAssistantMessage() ? undefined : turnMonitor.lastAssistantSalvageText()) ??
				"";
			const abortReason = aborted ? turnMonitor.resolveAbortReasonText() : undefined;
			let result: SingleResult | undefined;
			let finalizeError: unknown;
			try {
				result = await finalizeRunResult({
					monitor: turnMonitor,
					done: {
						exitCode: aborted || error ? 1 : 0,
						error,
						aborted,
						abortReason,
						durationMs: Date.now() - turnStartTime,
					},
					index,
					id,
					agent,
					task: ircTask,
					modelOverride: options.modelOverride,
					modelRole: options.modelRole,
					structured: options.structured,
					outputSchema: options.outputSchema,
					outputSchemaMode: options.outputSchemaMode,
					outputSchemaSource: options.outputSchemaSource,
					artifactsDir: options.artifactsDir,
					eventBus: options.eventBus,
					subagentEventBus: options.subagentEventBus,
					parentToolCallId: options.parentToolCallId,
					detached: true,
					followUpTurn: true,
					publishMessageResult: ownerWoken || ownerPrompted || userPrompted,
					// A cancelled wake job must not replace the accepted result.
					signal: jobCancel.signal,
					sessionFile,
					startTime: turnStartTime,
				});
			} catch (caught) {
				finalizeError = caught;
				logger.warn("IRC subagent turn finalization failed", {
					id,
					error: caught instanceof Error ? caught.message : String(caught),
				});
			} finally {
				// A focused-user result can complete without a registered wake job;
				// enqueue its delivery without reserving an execution slot.
				const messageResult =
					(userPrompted || ownerPrompted) && options.structured === false && result?.outputPath !== undefined;
				if (messageResult && !wakeJob && ownerId && session.asyncJobManager && result) {
					const text = formatTaskResultSummary(result, { totalDurationMs: result.durationMs });
					try {
						session.asyncJobManager.publishCompleted("task", id, { text }, { id, agentId: id, ownerId });
					} catch (error) {
						logger.warn("User-resumed subagent result delivery failed", {
							id,
							error: error instanceof Error ? error.message : String(error),
						});
					}
				}
				// Once registered, the wake job carries this turn's outcome to the
				// parent whatever it is: the yield result, the failure that
				// superseded it, or, for a turn that never yielded, the answer a
				// relay would have carried. `agentOutputPublished` tells the
				// delivery whether this turn wrote `<id>.md`: a turn that neither
				// yielded nor produced a message result leaves the previous turn's
				// output there, which `agent://<id>` must not be offered for.
				const outputPublished = result?.outputPath !== undefined;
				if (wakeJob && (yielded || messageResult) && result) {
					const text = formatTaskResultSummary(result, { totalDurationMs: result.durationMs });
					const structured = result.structuredOutput;
					if (result.aborted || result.exitCode !== 0 || result.error !== undefined) {
						wakeJob.outcome.reject(new AsyncJobError(text, structured));
					} else {
						wakeJob.outcome.resolve({
							text,
							agentOutputPublished: outputPublished,
							...(structured ? { structured } : {}),
						});
					}
				} else if (wakeJob && yielded) {
					const message = finalizeError instanceof Error ? finalizeError.message : String(finalizeError);
					wakeJob.outcome.reject(new Error(`Wake turn of ${id} failed to finalize: ${message}`));
				} else if (wakeJob) {
					const outcome = { error: errorForPeer, aborted, finalizeError };
					const text = buildWakeRelayBody({
						...outcome,
						id,
						yielded,
						result,
						turnText,
						abortReason,
						alreadyMessaged: IrcBus.global().sentSince(id, wakeJob.ownerId, turnStartTime),
					});
					if (wakeTurnFailed(outcome)) wakeJob.outcome.reject(new Error(text));
					else wakeJob.outcome.resolve({ text, agentOutputPublished: outputPublished });
				}
				// Unconditional: a failed, cancelled, empty, or even un-finalized
				// wake turn must still tell whoever woke it, or a `send await:true`
				// waiter mistakes a dead peer for a healthy-but-silent one.
				try {
					await relayWakeTurnOutput({
						id,
						records,
						turnStartTime,
						yielded,
						result,
						turnText,
						error: errorForPeer,
						aborted,
						abortReason,
						finalizeError,
						jobOwnerId: wakeJob?.ownerId,
					});
				} catch (relayError) {
					logger.warn("IRC wake-turn relay threw", {
						id,
						error: relayError instanceof Error ? relayError.message : String(relayError),
					});
				} finally {
					relay.resolve();
				}
			}
		};
	});
}

/**
 * Settle a subagent's registry lifecycle after a run: unregister for one-shot
 * helpers, idle + lifecycle adoption for kept-alive agents. An aborted run
 * (caller cancel, user interrupt, wall-clock timeout, soft budget) only stops
 * the run: a kept-alive, revivable agent stays interrogable and resumable
 * (IRC wake / revival) from its transcript. Terminal teardown is reserved for
 * explicit kills and agents nothing can revive.
 */
export async function finalizeSubagentLifecycle(args: {
	id: string;
	session: AgentSession;
	aborted: boolean;
	/** Which watchdog (if any) requested the abort; `shutdown` releases instead of adopting. */
	abortKind?: AbortReason;
	keepAlive: boolean;
	isolated: boolean;
	agentIdleTtlMs: number;
	reviveSession: AgentReviver | null;
	cleanupDeadlineAt?: number;
	onCleanupDeferred?: (completion: Promise<void>) => void;
	onRelease?: () => Promise<void>;
}): Promise<void> {
	const registry = AgentRegistry.global();
	const ref = registry.get(args.id);
	const ownsRef = Boolean(ref && ref.session === args.session);
	const cleanupDeadlineAt = args.cleanupDeadlineAt ?? Date.now() + 5000;
	const disposeSession = async (): Promise<void> => {
		// On a graceful finish (e.g. a `yield`) the advisor's review of the final
		// turn was enqueued at turn end but may still be draining. Give it a
		// chance to land in the transcript before the runtime is torn down —
		// mirroring print mode's headless drain — bounded by the shared cleanup
		// deadline. Hard aborts skip this to keep kill teardown fast.
		if (!args.aborted) {
			args.session.prepareForHeadlessAdvisorDrain();
			await args.session.waitForAdvisorCatchup(Math.max(0, cleanupDeadlineAt - Date.now()));
		}
		const disposal = args.session.dispose();
		const remainingMs = Math.max(0, cleanupDeadlineAt - Date.now());
		try {
			await untilAborted(AbortSignal.timeout(remainingMs), () => disposal);
		} catch (error) {
			if (Date.now() >= cleanupDeadlineAt) {
				args.onCleanupDeferred?.(disposal);
				return;
			}
			logger.warn("Subagent session cleanup failed", {
				id: args.id,
				error: error instanceof Error ? error.message : String(error),
			});
		}
	};
	const releaseOwnedResources = async (): Promise<void> => {
		try {
			await args.onRelease?.();
		} catch (error) {
			logger.warn("Subagent lifecycle resource cleanup failed", { id: args.id, error: String(error) });
		}
	};

	// An aborted run leaves a consistent session with its transcript on disk, so
	// a kept-alive agent with a reviver stays resumable like a finished one.
	// Manager shutdown also preserves the transcript, but disposes and unregisters
	// the process-local session (restorable as parked). An explicit kill (Agent
	// Hub, RPC `cancel_subagent`, collab, vibe) publishes the `aborted` tombstone
	// before the run observes its abort, and stays terminal.
	const resumableAbort =
		args.abortKind !== "shutdown" && args.keepAlive && args.reviveSession !== null && ref?.status !== "aborted";
	if (args.aborted && !resumableAbort) {
		if (ref && ownsRef) {
			if (args.abortKind === "shutdown") {
				try {
					await AgentLifecycleManager.global().release(args.id, ref);
				} catch (error) {
					logger.warn("runSubagent: failed to release session during manager shutdown", {
						id: args.id,
						error: String(error),
					});
					await disposeSession();
					registry.unregister(args.id, ref);
				}
			} else {
				// Route hard kills through the lifecycle owner so the terminal
				// decision is durable and a restart cannot rediscover the transcript
				// as a revivable parked agent.
				try {
					await AgentLifecycleManager.global().release(args.id, ref, { tombstone: true });
				} catch (error) {
					logger.warn("runSubagent: failed to persist kill tombstone", { id: args.id, error: String(error) });
					registry.setStatus(args.id, "aborted", ref);
					registry.detachSession(args.id, ref);
					await disposeSession();
				}
			}
		} else {
			await disposeSession();
		}
		await releaseOwnedResources();
		return;
	}

	if (!args.keepAlive) {
		// One-shot helper: dispose and unregister. No IRC, no revival.
		await disposeSession();
		if (ref && ownsRef) registry.unregister(args.id, ref);
		await releaseOwnedResources();
		return;
	}

	// Keep-alive: finished and failed subagents both stay interrogable.
	// The lifecycle manager owns idle-TTL parking + revival from here on.
	if (!ref || !ownsRef || !registry.setStatus(args.id, "idle", ref)) {
		await disposeSession();
		await releaseOwnedResources();
		return;
	}
	AgentLifecycleManager.global().adopt(
		args.id,
		{
			idleTtlMs: args.agentIdleTtlMs,
			revive: args.reviveSession ?? undefined,
			onRelease: args.onRelease,
		},
		ref,
	);
}

/** Options for {@link runSubagentFollowUpTurn}. */
export interface FollowUpTurnOptions {
	/** Registry id of the (live or parked) subagent to continue. */
	id: string;
	/** Agent definition the session was originally spawned with (drives progress labels + finalize). */
	agent: AgentDefinition;
	/** The follow-up message; sent as the turn's user prompt (with {@link restore}, only the run's label). */
	message: string;
	/**
	 * Go on with the turn the previous process left unfinished instead of sending
	 * `message` (`omp --restore`: {@link AgentSession.restoreInterruptedTurn}).
	 */
	restore?: boolean;
	/** Release queued idle deliveries after the initial restored attempt reaches idle. */
	onRestoreSettled?: () => void;
	index?: number;
	description?: string;
	/** Explicit pre-expansion model role alias retained from the original run. */
	modelRole?: string;
	/** Structured-output state retained from the original invocation; see {@link ExecutorOptions.structured}. */
	structured?: boolean;
	outputSchema?: unknown;
	outputSchemaMode?: StructuredSubagentSchemaMode;
	outputSchemaSource?: StructuredSubagentSchemaSource;
	signal?: AbortSignal;
	onProgress?: (progress: AgentProgress) => void;
	eventBus?: EventBus;
	subagentEventBus?: EventBus;
	parentToolCallId?: string;
	/**
	 * When set, a turn that yields or completes a successful, non-empty message
	 * result when requested by the parent (re)writes `<artifactsDir>/<id>.md` so
	 * `agent://<id>` tracks the latest completion. Structured turns without a
	 * yield and failed, empty, or cancelled message-result turns leave the
	 * existing artifact intact.
	 */
	artifactsDir?: string;
	/** Wall-clock cap in ms for this turn; 0 disables. */
	maxRuntimeMs?: number;
	/** Periodically ask for a completion estimate during this turn; see {@link isCompletionProbeEnabled}. */
	completionProbe?: boolean;
	/** Workpool items accepted by the child yield tool during this turn. */
	workPoolYieldItems?: WorkPoolYieldItem[];
}

/**
 * Continue a previously spawned (keep-alive) subagent with one more monitored
 * turn: revive it if parked, send `message` as a real prompt (or, with
 * `restore`, go on with its interrupted turn), drive it to
 * `yield`, and finalize a {@link SingleResult} exactly like a first run.
 *
 * The session's full conversation history is retained (live session, or JSONL
 * replay through the lifecycle reviver), so the turn sees all prior context.
 * Unlike {@link runSubprocess}, the session is NOT torn down afterwards — it
 * stays adopted by the {@link AgentLifecycleManager} (idle → TTL park →
 * revive), and an aborted turn only aborts the in-flight turn.
 */
export async function runSubagentFollowUpTurn(options: FollowUpTurnOptions): Promise<SingleResult> {
	const { id, agent, message, signal } = options;
	const index = options.index ?? 0;
	const startTime = Date.now();
	let session = await AgentLifecycleManager.global().ensureLive(id);
	// Acquire turn ownership before mutating the shared yield contract: installing
	// pooled items under a running ordinary wake would reject its in-flight tool
	// calls. The check-to-install section below has no await, so once idle is
	// observed no wake dispatch can interleave before the synchronous mutation.
	// Bounded: a worker that never settles fails its batch instead of installing
	// under the active turn or hanging the pool.
	let ownershipWaits = 0;
	const acquireOwnership = async (): Promise<void> => {
		while (session.isStreaming && ownershipWaits < 3) {
			ownershipWaits++;
			if (signal) {
				await untilAborted(signal, () => session.waitForIdle());
			} else {
				await session.waitForIdle();
			}
		}
		if (session.isStreaming) {
			throw new Error(
				`Subagent ${id} stayed busy through 3 ownership waits; refusing to install the pooled yield contract under an active turn`,
			);
		}
	};
	await acquireOwnership();
	// Revalidate until the worker survives an install round-trip unchanged: the
	// waits/rebuild above can outlast the idle TTL, letting park() detach this
	// instance mid-install. Each observed replacement means another full park
	// cycle, so reinstall on the fresh session (a revival restores only the last persisted contract) and check
	// again; genuine churn fails fast instead of driving a stale instance, and
	// a released worker throws instead of driving a corpse. A replacement may
	// already be streaming a wake, so ownership is reacquired every round.
	for (let acquireAttempts = 0; ; acquireAttempts++) {
		await session.setWorkPoolYieldItems(options.workPoolYieldItems ?? []);
		const live = await AgentLifecycleManager.global().ensureLive(id);
		if (live === session) break;
		if (acquireAttempts >= 2) {
			throw new Error(
				`Subagent ${id} was replaced during every install attempt; refusing to drive a stale worker session`,
			);
		}
		session = live;
		await acquireOwnership();
	}
	// A kept-alive session reuses its YieldTool across turns; clear the prior
	// run's incremental-section flag and retry counters so this turn's guards
	// evaluate against its own state, not stale accumulators.
	resetYieldTurnState(session.getToolByName("yield"));
	const ref = AgentRegistry.global().get(id);
	const sessionFile = ref?.sessionFile ?? undefined;

	const monitor = createSubagentRunMonitor({
		index,
		id,
		agent,
		task: message,
		description: options.description,
		modelRole: options.modelRole,
		signal,
		onProgress: options.onProgress,
		eventBus: options.eventBus,
		subagentEventBus: options.subagentEventBus,
		parentToolCallId: options.parentToolCallId,
		detached: true,
		sessionFile,
		softRequestBudget: 0,
		softRequestBudgetNotice: false,
		maxRuntimeMs: options.maxRuntimeMs ?? 0,
		completionProbe: options.completionProbe ?? false,
	});

	const startedPayload = {
		id,
		agent: agent.name,
		parentToolCallId: options.parentToolCallId,
		detached: true,
		agentSource: agent.source,
		description: options.description,
		status: "started",
		sessionFile,
		index,
	} as const;
	emitSubagentFrame(options.eventBus, options.subagentEventBus, TASK_SUBAGENT_LIFECYCLE_CHANNEL, startedPayload);

	monitor.setActiveSession(session);
	// The batch monitor attaches per attempt; the hook below detaches before each
	// backoff and reattaches for the retry, so the teardown always releases the
	// current attempt — including when the drive rejects and no winning attempt
	// was ever assigned.
	let outcome: DriveOutcome;
	// An IRC wake may own the session when this turn dispatches. drive retries the
	// initial prompt through this hook: detach first so the wake turn's `yield`
	// neither marks this batch yielded nor leaks into its result, restore the
	// ordinary contract so the wake cannot consume pooled items, wait it out,
	// then reinstall and reattach for the retry.
	let attemptUnsubscribe = monitor.attach(session);
	const structured = options.structured !== false;
	// As in a first run: this turn's monitor would take a wake turn's answer
	// (or its `yield`) as this turn's result, so non-parent wakes wait for it.
	const releaseIrcWakes = session.holdIrcWakes();
	try {
		try {
			outcome = await driveSessionToResult(session, monitor, message, {
				structured,
				restore: options.restore,
				onRestoreSettled: options.onRestoreSettled,
				onPromptBusy: async () => {
					attemptUnsubscribe();
					logger.debug("Subagent follow-up lost the prompt race to an IRC wake; backing off", { id });
					await session.setWorkPoolYieldItems([]);
					if (signal) {
						await untilAborted(signal, () => session.waitForIdle());
					} else {
						await session.waitForIdle();
					}
					resetYieldTurnState(session.getToolByName("yield"));
					await session.setWorkPoolYieldItems(options.workPoolYieldItems ?? []);
					attemptUnsubscribe = monitor.attach(session);
				},
			});
			if (resultDelivered(outcome, monitor, structured)) {
				// A follow-up turn's accepted result is the run's final result too:
				// terminalize the ref here, not just on the initial run (#11079).
				AgentRegistry.global().markResultAccepted(id, session, monitor.yieldAcceptedAt());
			}
		} finally {
			try {
				await untilAborted(AbortSignal.timeout(5000), () => monitor.waitForActiveSessionAbort());
			} catch {
				// Ignore abort cleanup timeouts; the session stays adopted either way.
			}
			attemptUnsubscribe();
			const active = monitor.takeActiveSession();
			if (active) monitor.captureSalvage(active);
			monitor.finish();
		}

		return await finalizeRunResult({
			monitor,
			done: { ...outcome, abortReason: outcome.abortReasonText, durationMs: Date.now() - startTime },
			index,
			id,
			agent,
			task: message,
			modelRole: options.modelRole,
			structured,
			outputSchema: options.outputSchema,
			outputSchemaMode: options.outputSchemaMode,
			outputSchemaSource: options.outputSchemaSource,
			signal,
			artifactsDir: options.artifactsDir,
			eventBus: options.eventBus,
			subagentEventBus: options.subagentEventBus,
			parentToolCallId: options.parentToolCallId,
			detached: true,
			followUpTurn: true,
			publishMessageResult: true,
			sessionFile,
			startTime,
		});
	} finally {
		releaseIrcWakes();
	}
}

/** Inputs of a subagent's rendered system prompt, fixed at spawn. */
interface SubagentPromptInputs {
	id: string;
	model?: string;
	agentSystemPrompt: string;
	context: string;
	planReference: string;
	planReferencePath: string;
	worktree: string;
	/** Whether the session has a `yield` tool; selects the Completion protocol. */
	structured: boolean;
	outputSchema: unknown;
	outputSchemaOverridesAgent: boolean;
	ircEnabled: boolean;
	/** Root resolved by the latest roster ensure; peer rows render scoped to it, so a session switch hides stale parked trees. */
	ircRoot: { sessionFile?: string };
	/** Peer roster each prompt block the live session rendered shows, keyed by that block. */
	ircRenders: Map<string, IrcPeerRosterData>;
	/** Peer roster of the prompt the parked session held; a warm revive renders it again. */
	ircRoster?: IrcPeerRosterData;
	/** Set while a warm revive rebuilds the session. */
	reviving: boolean;
}

/**
 * The spawn-time inputs of a subagent session. The live run and the lifecycle reviver both build
 * their {@link createAgentSession} options from it, so the reviver retains this plain capture
 * rather than the spawning run's options, monitor, abort signals, progress sinks or settings.
 */
interface SubagentSessionSpec {
	options: Omit<
		CreateAgentSessionOptions,
		| "settings"
		| "sessionManager"
		| "expectedAgentRef"
		| "systemPrompt"
		| "resolveServiceTierByFamily"
		| "onFirstChatDispatch"
	>;
	preparedSession?: Pick<PreparedSeanceSession, "promptSuffix">;
	prompt: SubagentPromptInputs;
}

/** Launch-only session inputs: a revived session restores these from its transcript or goes without. */
interface SubagentLaunchInputs {
	workPoolYieldItems: readonly WorkPoolYieldItem[];
	resolveServiceTierByFamily?: CreateAgentSessionOptions["resolveServiceTierByFamily"];
	onFirstChatDispatch?: () => void;
}

/** Names of the child's explicitly supplied tools; they win over same-named MCP proxies on every rebind. */
function explicitSubagentToolNames(spec: SubagentSessionSpec): ReadonlySet<string> {
	return new Set((spec.options.customTools ?? []).map(tool => tool.name));
}

function buildSubagentSessionOptions(
	spec: SubagentSessionSpec,
	settings: Settings,
	sessionManager: SessionManager,
	expectedAgentRef: CreateAgentSessionOptions["expectedAgentRef"],
	launch?: SubagentLaunchInputs,
): CreateAgentSessionOptions {
	const inputs = spec.prompt;
	// MCP proxies are minted per build, not captured in the spec: a kept-alive
	// subagent revived after `/mcp reload` must see the manager's current tools.
	const mcpTools = spec.options.mcpManager ? createMCPProxyTools(spec.options.mcpManager) : [];
	const customTools = spec.options.customTools ?? [];
	return {
		...spec.options,
		mcpTools: mcpTools.length > 0 ? mcpTools : undefined,
		customTools: customTools.length > 0 ? customTools : undefined,
		settings,
		sessionManager,
		expectedAgentRef,
		resolveServiceTierByFamily: launch?.resolveServiceTierByFamily,
		onFirstChatDispatch: launch?.onFirstChatDispatch,
		// A launch prompts its assignment only after setup; a revive's turns are its IRC wakes.
		awaitingAssignment: launch !== undefined,
		systemPrompt: defaultPrompt => {
			// A revive shows the roster the parked session's prompt held, and a rebuild that leaves the
			// rest of the prompt unchanged keeps the roster the prompt it replaces showed: peer rows carry
			// each peer's live activity, so a re-collected roster changed the prompt's bytes on every such
			// rebuild and the provider wrote the whole conversation to its prompt cache again. A rebuild
			// whose default blocks changed loses the cached prefix anyway, so it catches the roster up.
			const ircRoster = !inputs.ircEnabled
				? undefined
				: inputs.reviving && inputs.ircRoster
					? inputs.ircRoster
					: (heldIrcRoster(inputs, defaultPrompt) ??
						collectIrcPeerRoster(AgentRegistry.global(), inputs.id, inputs.ircRoot.sessionFile));
			const subagentPrompt = prompt.render(subagentSystemPromptTemplate, {
				agent: inputs.agentSystemPrompt,
				context: inputs.context,
				planReference: inputs.planReference,
				planReferencePath: inputs.planReferencePath,
				worktree: inputs.worktree,
				structured: inputs.structured,
				outputSchema: inputs.outputSchema,
				outputSchemaOverridesAgent: inputs.outputSchemaOverridesAgent,
				// Read the live item set through the registry instead of capturing the session, which
				// would pin its whole graph past park. A revive builds while the registry session is
				// null, so it renders the cleared set rather than the launch-time pooled instructions.
				workPoolYieldItems:
					AgentRegistry.global().get(inputs.id)?.session?.getWorkPoolYieldItems?.() ??
					launch?.workPoolYieldItems ??
					[],
				ircPeers: ircRoster?.peers ?? [],
				ircParkedCount: ircRoster?.parkedCount ?? 0,
				ircOmittedCount: ircRoster?.omittedCount ?? 0,
				ircSelfId: inputs.ircEnabled ? inputs.id : "",
			});
			if (ircRoster) recordIrcRender(inputs, subagentPrompt, ircRoster);
			// Per-spawn text (context, worktree, IRC roster) goes after the trailing
			// `<project-context>` block so spawns of the same agent share the static
			// prompt prefix as a cache hit.
			const seancePrompt = spec.preparedSession?.promptSuffix(inputs.model);
			return [...defaultPrompt, subagentPrompt, ...(seancePrompt ? [seancePrompt] : [])];
		},
	};
}

/**
 * The roster the live session's base prompt shows, when that prompt starts with `defaultPrompt`:
 * reusing it then keeps the whole prompt byte-identical. `undefined` before the first render or
 * when the default blocks changed.
 */
function heldIrcRoster(inputs: SubagentPromptInputs, defaultPrompt: readonly string[]): IrcPeerRosterData | undefined {
	const held = AgentRegistry.global().get(inputs.id)?.session?.baseSystemPrompt;
	if (!held || held.length <= defaultPrompt.length) return undefined;
	if (defaultPrompt.some((block, index) => held[index] !== block)) return undefined;
	return held.map(block => inputs.ircRenders.get(block)).find(roster => roster !== undefined);
}

/** Remembers the roster `block` shows, dropping blocks the live session's base prompt no longer holds. */
function recordIrcRender(inputs: SubagentPromptInputs, block: string, roster: IrcPeerRosterData): void {
	const held = AgentRegistry.global().get(inputs.id)?.session?.baseSystemPrompt;
	if (held) {
		for (const rendered of inputs.ircRenders.keys()) {
			if (!held.includes(rendered)) inputs.ircRenders.delete(rendered);
		}
	}
	inputs.ircRenders.set(block, roster);
}

/**
 * When `session` is disposed, keeps the roster its base prompt held for the next warm revive to
 * render again. The base, not the effective prompt: a `before_agent_start` override may rewrite
 * the block, and the revived turn re-runs that hook over the same base.
 */
function trackSubagentIrcRoster(session: AgentSession, inputs: SubagentPromptInputs): void {
	session.addDisposer(() => {
		inputs.ircRoster = session.baseSystemPrompt
			.map(block => inputs.ircRenders.get(block))
			.find(roster => roster !== undefined);
		inputs.ircRenders.clear();
	});
}

/** Re-resolves the IRC roster root a subagent's prompt scopes its peer rows to. */
async function refreshSubagentIrcRoot(
	inputs: SubagentPromptInputs,
	sessionManager: SessionManager,
	sessionFile: string | null,
): Promise<void> {
	if (!inputs.ircEnabled) return;
	const registry = AgentRegistry.global();
	inputs.ircRoot.sessionFile = await ensurePersistedRoster(
		registry,
		sessionManager.getSessionFile() ??
			sessionFile ??
			registry.get(inputs.id)?.sessionFile ??
			registry.get(MAIN_AGENT_ID)?.sessionFile,
	);
}

/** Recipe for a subagent's settings overlay: its parent plus the overlay's own writes. */
interface SubagentSettingsRecipe {
	parent: Settings;
	layers: OverlayLayers;
	rootThresholds: RootCompactionThresholds | undefined;
}

function captureSubagentSettings(parent: Settings, settings: SubagentChainSettings): SubagentSettingsRecipe {
	return { parent, layers: settings.overlayLayers(), rootThresholds: settings[kRootCompactionThresholds] };
}

function restoreSubagentSettings(recipe: SubagentSettingsRecipe): Settings {
	const settings: SubagentChainSettings = recipe.parent.restoreOverlay(recipe.layers);
	settings[kRootCompactionThresholds] = recipe.rootThresholds;
	return settings;
}

/** Everything the lifecycle reviver of a kept-alive subagent needs, captured explicitly. */
interface WarmReviveCapture {
	sessionFile: string;
	spec: SubagentSessionSpec;
	/** A per-call worker never switches models; its warm revive keeps only the exact saved model. */
	perCallModel: boolean;
	/** Re-captured whenever the live session is disposed, so a revive restores its latest settings writes. */
	settings: SubagentSettingsRecipe;
	parentArtifactManager: ArtifactManager | undefined;
	/** Todos are parent-owned and stripped from subagents, except under prewalk (its todo gate needs them). */
	keepTodo: boolean;
	wake: IrcWakeTurnMonitorOptions;
	/** Exact agent name the live `task.agentAccountPools` entry is looked up by on revive. */
	agentName: string;
	/**
	 * Pending, never-promoted family candidate. The stash lives only on the live manager, so park
	 * re-reads it (when the header still carries no task key) and the revive restores it onto the
	 * fresh manager the reviver opens from disk.
	 */
	pendingCacheCandidate: string | undefined;
}

/** Keeps `capture.pendingCacheCandidate` current with `session`'s manager stash until it is disposed. */
function trackSubagentPendingCandidate(session: AgentSession, capture: WarmReviveCapture): void {
	session.addDisposer(() => {
		const manager = session.sessionManager;
		// An already-persisted header is the carrier a revive reconstitutes from —
		// only an unpromoted stash must be carried, so a header stripped on disk
		// (a deliberate drop of persisted affinity) cannot resurrect it.
		capture.pendingCacheCandidate =
			manager.getHeader()?.taskPromptCacheKey === undefined ? manager.getTaskSiblingCandidate() : undefined;
	});
}

/** Keeps `capture.settings` current with `session`'s overlay writes until the session is disposed. */
function trackSubagentSettings(session: AgentSession, capture: WarmReviveCapture): void {
	const parent = capture.settings.parent;
	session.addDisposer(() => {
		capture.settings = captureSubagentSettings(parent, session.settings);
	});
}

/**
 * Runs `before_agent_start` once on a revived subagent's rebuilt extensions. Its wake turns are
 * agent-initiated and skip the hook, so a tool an extension registers from it, as it did at the
 * parked session's first prompt, would never come back. The result is dropped: the transcript
 * already holds what the parked session's turns added.
 */
export async function replayRevivedAgentStart(session: AgentSession): Promise<void> {
	await session.extensionRunner?.emitBeforeAgentStart("", undefined, session.baseSystemPrompt, "revive");
}

/**
 * Lifecycle reviver for a parked subagent: park closed the JSONL writer, so reopening takes the
 * single-writer lock cleanly and restores the full message history (createAgentSession →
 * agent.replaceMessages). Isolated runs keep their worktree for the same lifecycle, so they use
 * this path too. Built at module scope and handed nothing but `capture`: JSC keeps an enclosing
 * function's `arguments` reachable from its arrow closures, so any extra parameter would be pinned.
 */
function createWarmSubagentReviver(capture: WarmReviveCapture): AgentReviver {
	return async expectedAgentRef => {
		const { id } = capture.spec.prompt;
		const reopened = await SessionManager.open(capture.sessionFile, undefined, undefined, {
			suppressBreadcrumb: true,
			throwIfMissing: true,
		});
		if (!hasConversationalHistory(reopened.getEntries())) {
			await reopened.close();
			throw new Error(
				`Cannot revive subagent "${id}": session file "${capture.sessionFile}" has no message history ` +
					`(truncated to header/session_init). The agent was not revived.`,
			);
		}
		if (capture.parentArtifactManager) {
			reopened.adoptArtifactManager(capture.parentArtifactManager);
		}
		// The stash died with the parked manager: hand the pending, never-promoted
		// family candidate to the fresh one so the first eligible request after
		// revival still finds and persists it.
		if (capture.pendingCacheCandidate !== undefined) {
			reopened.setTaskSiblingCandidate(capture.pendingCacheCandidate);
		}
		await refreshSubagentIrcRoot(capture.spec.prompt, reopened, capture.sessionFile);
		const mcpManager = capture.spec.options.mcpManager;
		const mcpFollower = mcpManager ? followMCPTools(mcpManager, explicitSubagentToolNames(capture.spec)) : undefined;
		let revived: AgentSession;
		// Account pools are owner policy: take the live exact-name entry, as
		// dispatch and persisted revival do, never the spawn-time copy.
		const agentAccountPools = validateAgentAccountPools(cfgTaskAgentAccountPools.get(capture.settings.parent));
		capture.spec.prompt.reviving = true;
		// A session-local switch since spawn (a prewalk handoff) owns the model and effort: the
		// transcript restores the effort, and the spawn selection only backs the model up when it is
		// unavailable. The spawn's prewalk stays configured; the coordinator sees it was spent. A seance
		// fork's selections belong to its source run, never to the consult.
		// A per-call worker never switches models, so its warm revive never prepends a session-local switch.
		const sessionLocalModel =
			capture.spec.preparedSession || capture.perCallModel
				? undefined
				: reopened.getSessionLocalModelChange()?.model;
		try {
			try {
				const options = buildSubagentSessionOptions(
					capture.spec,
					restoreSubagentSettings(capture.settings),
					reopened,
					expectedAgentRef,
				);
				({ session: revived } = await createAgentSession({
					...options,
					...(sessionLocalModel
						? {
								model: undefined,
								modelPattern: [
									sessionLocalModel,
									...(options.model
										? [formatModelStringWithRouting(options.model)]
										: options.modelPattern === undefined
											? []
											: [options.modelPattern].flat()),
								],
								modelPatternFallbackRole: undefined,
								modelPatternDefaultFallbackChain: undefined,
								thinkingLevel: undefined,
							}
						: undefined),
					oauthAccountPools: Object.hasOwn(agentAccountPools, capture.agentName)
						? agentAccountPools[capture.agentName]
						: undefined,
				}));
			} catch (error) {
				mcpFollower?.dispose();
				throw error;
			}
			mcpFollower?.bind(revived);
			trackSubagentSettings(revived, capture);
			trackSubagentPendingCandidate(revived, capture);
			trackSubagentIrcRoster(revived, capture.spec.prompt);
			const withoutParentOwnedTools = (toolNames: string[]): string[] =>
				capture.keepTodo ? toolNames : toolNames.filter(name => name !== "todo");
			// Strip what the spawn stripped, before extensions start: the rebuilt session enables its defaults again.
			const revivedToolNames = revived.getEnabledToolNames();
			const subagentToolNames = withoutParentOwnedTools(revivedToolNames);
			if (subagentToolNames.length !== revivedToolNames.length) {
				await revived.setActiveToolsByName(subagentToolNames);
			}
			// Re-run the executor's extension wiring on the rebuilt session. Skipping it leaves the
			// runner pre-init, so a `tool_call` handler touching a runtime action trips the
			// fail-closed gate and blocks every tool (including `yield`) in the revived agent (issue #8824).
			await initializeExtensions(revived, {
				reportSendError: (action, err) => logger.error("Extension send failed", { action, error: err.message }),
				reportRuntimeError: err => logger.error("Extension error", { path: err.extensionPath, error: err.error }),
				filterActiveTools: withoutParentOwnedTools,
			});
			await replayRevivedAgentStart(revived);
		} finally {
			capture.spec.prompt.reviving = false;
		}
		AgentRegistry.global().syncSessionStatus(id, revived);
		attachIrcWakeTurnMonitor(revived, capture.wake);
		return revived;
	};
}

/**
 * Run a single agent in-process.
 */
export async function runSubprocess(options: ExecutorOptions): Promise<SingleResult> {
	const {
		cwd,
		agent,
		task,
		assignment,
		index,
		id,
		worktree,
		modelOverride,
		modelRole,
		thinkingLevel,
		outputSchema,
		enableLsp,
		signal,
		onProgress,
	} = options;
	const preparedSession = options.preparedSession;
	const cleanupGraceMs = options.cleanupGraceMs ?? TASK_ABORT_CLEANUP_GRACE_MS;
	const structured = options.structured !== false;
	const startTime = Date.now();
	// Set by the session's onFirstChatDispatch hook the first time the agent
	// loop dispatches a chat request to the provider — the launch-complete boundary.
	let firstChatDispatchAt: number | undefined;

	// Check if already aborted
	if (signal?.aborted) {
		return {
			index,
			id,
			agent: agent.name,
			agentSource: agent.source,
			task,
			assignment,
			description: options.description,
			exitCode: 1,
			output: "",
			stderr: "Cancelled before start",
			truncated: false,
			durationMs: 0,
			tokens: 0,
			requests: 0,
			modelOverride,
			modelRole,
			error: "Cancelled before start",
			aborted: true,
			abortReason: "Cancelled before start",
		};
	}

	// Set up artifact paths and write input file upfront if artifacts dir provided
	let subtaskSessionFile: string | undefined;
	if (options.artifactsDir) {
		subtaskSessionFile = path.join(options.artifactsDir, `${id}.jsonl`);
	}

	const settings = options.settings ?? Settings.isolated();
	// Per-agent advisor: the agent definition's `advisor` frontmatter or the
	// `task.agentAdvisor` settings override (agent name → "on"/"off"/model
	// pattern) pairs the spawned session with an advisor. Subagents default to
	// no advisor (createSubagentSettings forces `advisor.enabled` off); an
	// explicit model pattern is expanded against this owner's roles (a nested
	// spawn's owner is its parent subagent) and lands on the child's
	// `modelRoles.advisor`. The expanded pattern is also what the session
	// contract persists, so cold revival under root settings reuses it.
	const advisorSelection = preparedSession
		? undefined
		: resolveAgentAdvisorSelection({
				settingsOverride: cfgTaskAgentAdvisor.get(settings)[agent.name],
				agentAdvisor: agent.advisor,
			});
	const advisorRolePattern = advisorSelection?.model
		? resolveAgentAdvisorRolePattern(advisorSelection.model, settings)
		: undefined;
	const subagentSettings = createSubagentSettings(
		settings,
		{
			...compactionThresholdSettings(options.compactionThresholdOverride),
			...(agent.readSummarize === false ? { "read.summarize.enabled": false } : undefined),
			// Isolated runs must not expose roots outside the worktree.
			...(worktree !== undefined ? { "workspace.additionalDirectories": [] } : undefined),
			...(advisorSelection ? { "advisor.enabled": true } : undefined),
			...(advisorRolePattern
				? { modelRoles: { ...settings.getModelRoles(), advisor: advisorRolePattern } }
				: undefined),
		},
		options.parentServiceTier,
	);
	const maxRecursionDepth = cfgTaskMaxRecursionDepth.get(settings);
	const maxRuntimeMs = Math.max(0, Math.trunc(Number(options.maxRuntimeMs ?? cfgTaskMaxRuntimeMs.get(settings)) || 0));
	// TTL before an adopted idle subagent is parked by the lifecycle manager.
	// <= 0 disables parking (the session stays live until process teardown).
	const agentIdleTtlMs = Math.trunc(Number(cfgTaskAgentIdleTtlMs.get(settings)) || 0);
	const configuredDefaultBudget = Math.max(0, Math.trunc(Number(cfgTaskSoftRequestBudget.get(settings)) || 0));
	const softRequestBudget = resolveSoftRequestBudget(
		agent.name,
		configuredDefaultBudget,
		cfgTaskAgentSoftRequestBudget.get(settings),
	);
	const softRequestBudgetNotice = cfgTaskSoftRequestBudgetNotice.get(settings);
	const parentDepth = options.taskDepth ?? 0;
	const childDepth = parentDepth + 1;
	const restrictToolNames = options.restrictToolNames === true || preparedSession !== undefined;
	const atMaxDepth = maxRecursionDepth >= 0 && childDepth >= maxRecursionDepth;

	// Add tools if specified. Unstructured runs never get `yield`, even when
	// the frontmatter lists it.
	let toolNames: string[] | undefined;
	if (agent.tools) {
		toolNames = structured ? agent.tools : agent.tools.filter(name => name !== "yield");
		// Auto-include task tool if spawns defined but task not in tools
		if (agent.spawns !== undefined && !toolNames.includes("task") && !atMaxDepth) {
			toolNames = [...toolNames, "task"];
		}
	}

	if (atMaxDepth && toolNames?.includes("task")) {
		toolNames = toolNames.filter(name => name !== "task");
	}
	if (toolNames?.includes("exec")) {
		const backends = resolveEvalBackends({ settings } as ToolSession);
		const expanded = toolNames.filter(name => name !== "exec");
		if (backends.python || backends.js) expanded.push("eval");
		expanded.push("bash");
		toolNames = Array.from(new Set(expanded));
	}
	// Agents that can start background work (`task`, `bash`) need `wait` to block on it;
	// without it they `sleep`. Runs after `exec` expansion and the max-depth `task` strip.
	// `createTools` still drops it when no wake source (async/IRC/services) is enabled.
	// Restricted sessions own their explicit list and are never widened.
	if (
		toolNames &&
		!options.restrictToolNames &&
		!toolNames.includes("wait") &&
		(toolNames.includes("task") || toolNames.includes("bash"))
	) {
		toolNames = [...toolNames, "wait"];
	}
	// Inbound steering works without messaging; outbound peer coordination requires write.
	const ircEnabled =
		!preparedSession &&
		options.enableIrc !== false &&
		isIrcEnabled(subagentSettings, childDepth) &&
		(toolNames === undefined || toolNames.includes("write"));

	const modelPatterns = normalizeModelPatterns(modelOverride ?? agent.model);
	const sessionFile = subtaskSessionFile ?? null;
	const spawnsEnv = atMaxDepth
		? ""
		: agent.spawns === undefined
			? ""
			: agent.spawns === "*"
				? "*"
				: agent.spawns.join(",");

	const lspEnabled = enableLsp ?? true;
	const skipPythonPreflight = Array.isArray(toolNames) && !toolNames.includes("eval");

	const completionProbe = isCompletionProbeEnabled(settings, parentDepth);
	const monitor = createSubagentRunMonitor({
		index,
		id,
		agent,
		task,
		assignment,
		description: options.description,
		modelRegistry: options.modelRegistry,
		settings,
		modelOverride,
		modelRole,
		modelRoute: options.modelRoute,
		signal,
		onProgress,
		onToolResult: options.onToolResult,
		eventBus: options.eventBus,
		subagentEventBus: options.subagentEventBus,
		parentToolCallId: options.parentToolCallId,
		detached: options.detached,
		sessionFile: subtaskSessionFile,
		softRequestBudget,
		softRequestBudgetNotice,
		maxRuntimeMs,
		completionProbe,
	});
	const progress = monitor.progress;
	let unsubscribe: (() => void) | null = null;
	// Until the run's result is final, an IRC message waits for its own wake
	// turn instead of one this run's monitor would take as the result.
	let releaseIrcWakes: (() => void) | undefined;
	let registryAbortUnsubscribe: (() => void) | null = null;
	let reviveSession: AgentReviver | null = null;
	let pendingSessionManager: Promise<SessionManager> | undefined;
	let openedSessionManager: SessionManager | undefined;
	let untrackedSession: AgentSession | undefined;
	let pendingSessionDisposal: Promise<void> | undefined;
	const wakeOptions: IrcWakeTurnMonitorOptions = {
		id,
		index,
		agent,
		completionProbe,
		description: options.description,
		modelOverride,
		modelRole,
		eventBus: options.eventBus,
		subagentEventBus: options.subagentEventBus,
		parentToolCallId: options.parentToolCallId,
		sessionFile: subtaskSessionFile,
		maxRuntimeMs,
		structured,
		outputSchema,
		outputSchemaMode: options.outputSchemaMode,
		outputSchemaSource: options.outputSchemaSource,
		artifactsDir: options.artifactsDir,
	};

	const runSubagent = async (): Promise<{
		exitCode: number;
		error?: string;
		aborted?: boolean;
		abortReason?: string;
		durationMs: number;
	}> => {
		const sessionAbortController = new AbortController();
		const abortSignal = monitor.abortSignal;
		let exitCode = 0;
		let error: string | undefined;
		let aborted = false;
		let abortReasonText: string | undefined;
		const checkAbort = () => {
			if (abortSignal.aborted) {
				throw new ToolAbortError();
			}
		};
		const awaitAbortable = async <T>(promise: Promise<T>): Promise<T> => {
			checkAbort();
			const { promise: abortPromise, reject } = Promise.withResolvers<never>();
			const onAbort = () => {
				try {
					checkAbort();
				} catch (err) {
					reject(err);
				}
			};
			abortSignal.addEventListener("abort", onAbort, { once: true });
			try {
				return await Promise.race([promise, abortPromise]);
			} finally {
				abortSignal.removeEventListener("abort", onAbort);
			}
		};
		// Launch-latency phase marks (performance.now()); read by the debug log
		// emitted before this closure returns. Left undefined when setup throws
		// before reaching the phase, which itself localizes the cost.
		const perfStart = performance.now();
		let resolvedAt: number | undefined;
		let sessionOpenedAt: number | undefined;
		let sessionCreatedAt: number | undefined;
		let readyAt: number | undefined;

		try {
			checkAbort();
			// Pin authStorage to modelRegistry.authStorage — mirrors the createAgentSession invariant.
			const registryFromParent = options.modelRegistry !== undefined;
			const modelRegistry =
				options.modelRegistry ??
				new ModelRegistry(options.authStorage ?? (await awaitAbortable(discoverAuthStorage())));
			const authStorage = modelRegistry.authStorage;
			if (options.authStorage && options.authStorage !== authStorage) {
				throw new Error(
					"options.authStorage and options.modelRegistry.authStorage must be the same instance when both are provided",
				);
			}
			checkAbort();
			if (!registryFromParent) {
				modelRegistry.refreshInBackground();
			} else {
				logger.debug("runSubagent: reusing parent modelRegistry; skipping refresh");
			}
			checkAbort();

			if (options.perCallModelGrants) {
				await awaitAbortable(modelRegistry.awaitBackgroundRefresh());
			}
			const configuredModelPatterns = resolveConfiguredModelPatterns(modelPatterns, settings);
			const inheritedRetryFallbackChain =
				configuredModelPatterns.length === 1
					? resolveSubagentInheritedRetryFallbackChain(
							subagentSettings,
							modelRegistry,
							modelRole ?? resolveExplicitModelRole(modelPatterns, subagentSettings),
						)
					: undefined;
			const {
				model,
				thinkingLevel: resolvedThinkingLevel,
				explicitThinkingLevel,
				authFallbackUsed,
				warning: modelResolutionWarning,
			} = await awaitAbortable(
				resolveModelOverrideWithAuthFallback(
					modelPatterns,
					options.parentActiveModelPattern,
					modelRegistry,
					settings,
					id,
					options.perCallModelGrants ? { exactOnly: true } : undefined,
				),
			);
			if (options.perCallModelGrants && !model) {
				throw new PerCallModelError(
					`Requested exact model ${JSON.stringify(modelPatterns)} is unavailable. Use an exact provider/model[:level] selector; do not substitute another model.`,
				);
			}
			if (modelResolutionWarning) {
				logger.warn("Subagent model resolution warning", {
					warning: modelResolutionWarning,
					requested: modelPatterns,
				});
			}
			if (authFallbackUsed && model) {
				logger.warn("Subagent model has no working credentials; falling back to parent session model", {
					requested: modelPatterns,
					parentModel: options.parentActiveModelPattern,
					resolvedProvider: model.provider,
					resolvedModel: model.id,
				});
			}
			// Preflight skips these checks while the registry is cold, so hold the model
			// a per-call child actually starts on to them before its session exists.
			if (options.perCallModelGrants && model) {
				assertPerCallModelApproved(model, options.perCallModelGrants, modelRegistry);
			}
			// The exact-name `task.agentServiceTierOverrides` entry dispatch resolved
			// for this agent. The session evaluates it against its final model —
			// including patterns only it can resolve — so a concrete tier lands on
			// exactly that model's family, and persists the result (even empty) so
			// hot and cold revival restore it instead of re-deriving `tier.subagent`.
			const serviceTierOverride = options.serviceTierOverride;
			const resolveServiceTierByFamily =
				serviceTierOverride === undefined
					? undefined
					: (resolvedModel: Model | undefined) =>
							resolveAgentServiceTierOverride(
								serviceTierOverride,
								resolvedModel,
								inheritedSubagentServiceTiers(settings, options.parentServiceTier),
							);
			const retryFallbackRole = installSubagentRetryFallbackChain({
				settings: subagentSettings,
				id,
				candidates: resolveSubagentRetryFallbackCandidates(modelPatterns, modelRegistry, subagentSettings),
				inheritedFallbackChain: inheritedRetryFallbackChain,
				model,
				authFallbackUsed,
			});
			if (retryFallbackRole) {
				logger.debug("Configured subagent runtime model fallback chain", {
					role: retryFallbackRole,
					requested: modelPatterns,
				});
			}
			if (model?.contextWindow && model.contextWindow > 0) {
				progress.contextWindow = model.contextWindow;
			}
			// Caller-requested coarse effort maps onto the resolved model's
			// supported range, then respects the operator-configured ceiling.
			// Undefined (no effort, or no controllable effort surface) falls
			// through to the normal selectors below.
			// The ceiling outlives initial resolution: it rides into the session so
			// retry-fallback recovery can never clamp effort back up past it.
			// A per-call `model` is caller-chosen too, so its `:level` is held to the same
			// ceiling, and a model whose lowest effort is above it fails the spawn
			// exactly as an `effort` hint does.
			const spawnEffortCeiling =
				options.effort !== undefined || options.perCallModelGrants ? cfgTaskMaxEffort.get(settings) : undefined;
			if (model && spawnEffortCeiling) assertModelSupportsEffortCeiling(model, spawnEffortCeiling);
			const effortLevel =
				options.effort !== undefined
					? resolveTaskEffortLevel(model, options.effort, spawnEffortCeiling)
					: undefined;
			const explicitLevel =
				explicitThinkingLevel && resolvedThinkingLevel !== AUTO_THINKING
					? clampThinkingLevelToCeiling(model, resolvedThinkingLevel, spawnEffortCeiling)
					: resolvedThinkingLevel;
			if (model) {
				const displayLevel = effortLevel ?? (explicitThinkingLevel ? explicitLevel : undefined);
				progress.resolvedModelIdentity = formatModelStringWithRouting(model);
				progress.resolvedThinkingLevel = displayLevel;
				progress.resolvedModel =
					displayLevel !== undefined
						? formatModelSelectorValue(progress.resolvedModelIdentity, displayLevel)
						: progress.resolvedModelIdentity;
			}
			// Precedence: caller `effort` > explicit `:level` suffix on the resolved
			// model pattern > agent-definition default (e.g. task's `auto`) >
			// pattern-derived level.
			const effectiveThinkingLevel =
				effortLevel ?? (explicitThinkingLevel ? explicitLevel : (thinkingLevel ?? resolvedThinkingLevel));
			resolvedAt = performance.now();
			const effectiveCwd = worktree ?? cwd;
			const fork = preparedSession?.fork;
			if (fork && !subtaskSessionFile) {
				throw new Error("The prepared session fork requires a persisted child session file.");
			}
			const sessionManagerPromise = fork
				? SessionManager.forkFrom(fork.sourceFile, effectiveCwd, undefined, undefined, {
						seance: true,
						suppressBreadcrumb: true,
						sessionFile: subtaskSessionFile,
						resetInheritedCost: true,
						repairInterruptedTail: true,
					})
				: sessionFile
					? SessionManager.open(sessionFile, undefined, undefined, {
							initialCwd: effectiveCwd,
							parentSession: options.sessionFile ?? undefined,
							suppressBreadcrumb: true,
						})
					: Promise.resolve(SessionManager.inMemory(effectiveCwd));
			if (preparedSession) pendingSessionManager = sessionManagerPromise;
			// Setup below can fail before this promise's consumption boundary.
			// Observe rejection immediately while preserving it for the later await.
			sessionManagerPromise.catch(() => {});
			// Per-agent prewalk: the agent definition's `prewalk` frontmatter or the
			// `task.agentPrewalk` settings override hands the subagent off to a
			// fast/cheap target at its first edit/write — the same mechanism as the
			// session-level --prewalk. The bundled generic `task` agent has no
			// frontmatter default; the `task.prewalk` toggle (default off) arms it.
			// Resolution failures skip prewalk instead of failing the spawn. A per-call
			// worker never switches models, so it never prewalks.
			const perCallModelGrants = options.perCallModelGrants;
			let prewalk: Prewalk | undefined;
			const prewalkPattern =
				preparedSession || perCallModelGrants
					? undefined
					: resolveAgentPrewalkPattern({
							settingsOverride: cfgTaskAgentPrewalk.get(settings)[agent.name],
							agentPrewalk: resolveAgentPrewalkDefault(agent, cfgTaskPrewalk.get(settings)),
						});
			if (prewalkPattern) {
				await awaitAbortable(modelRegistry.awaitBackgroundRefresh());
				const resolvedPrewalk = resolveModelOverride([prewalkPattern], modelRegistry, settings);
				const target = resolvedPrewalk.model;
				if (!target || !modelRegistry.hasConfiguredAuth(target)) {
					logger.warn("Subagent prewalk target unavailable; skipping prewalk", {
						agent: agent.name,
						pattern: prewalkPattern,
						warning: resolvedPrewalk.warning,
					});
				} else if (prewalkWouldBeNoop(model, effectiveThinkingLevel, target, resolvedPrewalk.thinkingLevel)) {
					// Same model AND same effective thinking level: switching would only
					// inject the plan/checklist nudges for no gain — skip. An effort-only
					// delta on the same model still arms (it is a real cheapening hand-off).
					logger.debug("Subagent prewalk target matches starting model and thinking level; skipping prewalk", {
						agent: agent.name,
						pattern: prewalkPattern,
					});
				} else {
					prewalk = { target, thinkingLevel: resolvedPrewalk.thinkingLevel };
				}
			}

			const enableMCP = !restrictToolNames && (options.enableMCP ?? true);
			const mcpManager = enableMCP ? options.mcpManager : undefined;

			// Derive subagent-scoped telemetry from the parent's config so the
			// child loop's spans nest under the parent's active execute_tool span
			// (OTEL context propagation handles parent linkage automatically),
			// carry the subagent's own agent identity, and use the subagent's
			// own session id for `gen_ai.conversation.id`.
			const subagentAgentIdentity: AgentIdentity | undefined = options.parentTelemetry
				? {
						id,
						name: agent.name,
						description: agent.description,
					}
				: undefined;
			const subagentTelemetry: AgentTelemetryConfig | undefined =
				options.parentTelemetry && subagentAgentIdentity
					? {
							...options.parentTelemetry,
							agent: subagentAgentIdentity,
							// Clear parent's conversationId; the child loop falls back to
							// its own AgentLoopConfig.sessionId.
							conversationId: undefined,
						}
					: undefined;

			if (options.parentTelemetry && subagentAgentIdentity) {
				const parentTelemetryHandle = resolveTelemetry(
					options.parentTelemetry,
					options.parentTelemetry.conversationId,
				);
				recordHandoff(parentTelemetryHandle, {
					fromAgent: options.parentTelemetry.agent,
					toAgent: subagentAgentIdentity,
				});
			}

			const { normalized: normalizedOutputSchema } = normalizeSchema(outputSchema);
			// Rebuilding an equivalent session from the same JSONL file re-invokes
			// createAgentSession with this spec (same agent id, tools, model, system
			// prompt, artifacts dir) — only the SessionManager and settings differ.
			const sessionSpec: SubagentSessionSpec = {
				options: {
					cwd: effectiveCwd,
					costGate: options.costGate,
					additionalDirectories: worktree !== undefined ? undefined : options.additionalDirectories,
					authStorage,
					modelRegistry,
					getApiKey: options.getApiKey,
					credentialSourceSessionId: options.credentialSourceSessionId,
					oauthAccountPools: options.oauthAccountPools,
					inheritedSessionAgents: options.inheritedSessionAgents,
					model,
					modelPattern: model || modelOverride === undefined ? undefined : modelPatterns,
					modelPatternAuthFallback:
						model || modelOverride === undefined ? undefined : options.parentActiveModelPattern,
					modelPatternFallbackRole:
						model || modelOverride === undefined ? undefined : subagentRetryFallbackRole(id),
					modelPatternDefaultFallbackChain:
						model || modelOverride === undefined ? undefined : inheritedRetryFallbackChain,
					thinkingLevel: effectiveThinkingLevel,
					...(perCallModelGrants
						? {
								// Every request stays on an approved model that can run at or below the spawn's effort ceiling.
								assertDispatchModel: (dispatchModel: Model) => {
									assertPerCallModelApproved(dispatchModel, perCallModelGrants, modelRegistry);
									if (spawnEffortCeiling) assertModelSupportsEffortCeiling(dispatchModel, spawnEffortCeiling);
								},
								disableModelFallback: true,
								disableServerSideFallback: true,
							}
						: {}),
					thinkingLevelCeiling: spawnEffortCeiling,
					// Subagents are short-lived; never schedule background warm requests.
					cacheWarming: false,
					toolNames,
					outputSchema,
					outputSchemaMode: options.outputSchemaMode,
					restrictToolNames,
					requireYieldTool: structured,
					contextFiles: options.contextFiles,
					noContextFiles: options.noContextFiles,
					// Subagents never receive AGENTS.md, including from additional workspace roots they rediscover.
					excludeAgentsMd: true,
					skills: options.skills,
					promptTemplates: options.promptTemplates,
					workspaceTree: options.workspaceTree,
					rules: options.rules,
					extensionRoots: options.extensionRoots,
					preloadedExtensionPaths: restrictToolNames ? [] : options.preloadedExtensionPaths,
					preloadedPreparedExtensions: options.preloadedPreparedExtensions,
					preloadedCustomToolPaths: restrictToolNames ? [] : options.preloadedCustomToolPaths,
					hasUI: false,
					prewalk,
					spawns: spawnsEnv,
					taskDepth: childDepth,
					// The whole spawn tree shares the root session's observability bus,
					// so nested lifecycle/progress/event frames reach its surfaces
					// without leaking into another root session's traffic.
					subagentEventBus: options.subagentEventBus,
					parentHindsightSessionState: options.parentHindsightSessionState,
					parentMnemopiSessionState: options.parentMnemopiSessionState,
					parentTaskPrefix: id,
					asyncJobManager: options.asyncJobManager,
					parentAgentId: options.parentAgentId,
					agentId: id,
					agentDisplayName: agent.name,
					agentName: agent.name,
					enableLsp: lspEnabled,
					enableIrc: options.enableIrc,
					skipPythonPreflight,
					enableMCP,
					mcpManager,
					// MCP proxies are minted per build as `mcpTools` in buildSubagentSessionOptions.
					customTools: options.customTools,
					localProtocolOptions: options.localProtocolOptions,
					telemetry: subagentTelemetry,
					// Seance isolation overrides every inherited field above in one place.
					...(preparedSession ? seanceIsolationOptions(effectiveCwd) : {}),
				},
				preparedSession: preparedSession ? { promptSuffix: preparedSession.promptSuffix } : undefined,
				prompt: {
					id,
					model: progress.resolvedModel,
					agentSystemPrompt: agent.systemPrompt,
					context: options.context?.trim() ?? "",
					planReference: options.planReference?.content ?? "",
					planReferencePath: options.planReference?.path ?? "",
					worktree: worktree ?? "",
					structured,
					outputSchema: normalizedOutputSchema,
					outputSchemaOverridesAgent: options.outputSchemaOverridesAgent === true,
					ircEnabled,
					ircRoot: {},
					ircRenders: new Map(),
					reviving: false,
				},
			};

			const sessionManager = await awaitAbortable(sessionManagerPromise);
			if (preparedSession) openedSessionManager = sessionManager;
			if (options.parentArtifactManager && !preparedSession) {
				sessionManager.adoptArtifactManager(options.parentArtifactManager);
			}
			sessionOpenedAt = performance.now();
			await refreshSubagentIrcRoot(sessionSpec.prompt, sessionManager, sessionFile);

			// A seance fork inherits the source's model roles; they describe the
			// source run, not this consult, so the consult still pins its own chain.
			const hasExistingModelRole = !preparedSession && sessionManager.getLastModelChangeRole() !== undefined;
			// Subscribe before the builder mints proxies so a manager change during
			// session startup is replayed on bind instead of lost.
			const mcpFollower = mcpManager
				? followMCPTools(mcpManager, explicitSubagentToolNames(sessionSpec))
				: undefined;
			let session: AgentSession;
			let sessionPromise: Promise<CreateAgentSessionResult> | undefined;
			try {
				sessionPromise = createAgentSession(
					buildSubagentSessionOptions(sessionSpec, subagentSettings, sessionManager, null, {
						workPoolYieldItems: options.workPoolYieldItems ?? [],
						// A revived session restores the tier history it persisted (including
						// tiers a provider rejected or an extension changed since spawn); only
						// the fresh spawn resolves the per-agent override.
						resolveServiceTierByFamily,
						onFirstChatDispatch: () => {
							firstChatDispatchAt ??= performance.now();
						},
					}),
				);
				({ session } = await awaitAbortable(sessionPromise));
				if (preparedSession) untrackedSession = session;
				// Stash the sibling family candidate once the child session exists,
				// independent of its initial model, so a later model change (retry
				// fallback, model switch) still finds it. Consumption is gated per
				// request by AgentSession.getPromptCacheKeyForModel; the first primary
				// request on an opted-in model persists it to the header so fork and
				// reopen keep it. An empty parent lineage derives no candidate:
				// ":<agent>" would coalesce every such parent onto one family.
				if (options.parentPromptCacheKey) {
					sessionManager.setTaskSiblingCandidate(`${options.parentPromptCacheKey}:${agent.name}`);
				}
			} catch (err) {
				mcpFollower?.dispose();
				// Abort raced session startup. The session may still resolve later
				// holding live LSP/MCP child processes — dispose it when it does so
				// a cancelled subagent cannot leak them.
				if (preparedSession) {
					pendingSessionDisposal = sessionPromise
						?.then(created => created.session.dispose())
						.then(
							() => {},
							() => {},
						);
				} else {
					void sessionPromise?.then(created => created.session.dispose()).catch(() => {});
				}
				throw err;
			}
			mcpFollower?.bind(session);
			// The SDK records a new session's initial model as the default role.
			// Pin the child's own chain so a parent default sharing that model
			// cannot steal its fallback routing. Resumed history keeps its role.
			if (
				!hasExistingModelRole &&
				retryFallbackRole &&
				model &&
				session.model &&
				formatModelStringWithRouting(session.model) === formatModelStringWithRouting(model)
			) {
				sessionManager.appendModelChange(formatModelStringWithRouting(model), retryFallbackRole);
			}
			sessionCreatedAt = performance.now();

			monitor.setActiveSession(session);
			if (preparedSession) untrackedSession = undefined;
			// Run-state notifications precede deferrable wire-level `agent_end`,
			// so adopted keep-alive lifecycle cannot get stuck during prompt unwind.
			const registry = AgentRegistry.global();
			registry.syncSessionStatus(id, session);
			const runRef = registry.get(id);
			if (runRef) {
				// Agent Hub kills bypass this run's caller signal: lifecycle.release()
				// detaches the session and publishes an `aborted` tombstone directly.
				// Bridge that exact registry generation back into the monitor so the
				// prompt race and owning async task job settle promptly.
				registryAbortUnsubscribe = registry.onChange(event => {
					if (event.type === "status_changed" && event.ref === runRef && event.ref.status === "aborted") {
						monitor.requestAbort("signal");
					}
				});
				// Close the subscribe-after-read race with a kill that landed while
				// createAgentSession was returning.
				if (runRef.status === "aborted") monitor.requestAbort("signal");
			}
			// Todos are parent-owned bookkeeping and stripped from subagents —
			// except under prewalk, whose plan nudge + todo gate require the
			// subagent to commit its own todo list before the hand-off.
			const isParentOwnedTool = (name: string): boolean => !prewalk && name === "todo";
			if (sessionFile !== null) {
				const reviveCapture: WarmReviveCapture = {
					sessionFile,
					spec: sessionSpec,
					perCallModel: perCallModelGrants !== undefined,
					settings: captureSubagentSettings(settings, subagentSettings),
					parentArtifactManager: preparedSession ? undefined : options.parentArtifactManager,
					keepTodo: prewalk !== undefined,
					wake: wakeOptions,
					agentName: agent.name,
					pendingCacheCandidate: undefined,
				};
				trackSubagentSettings(session, reviveCapture);
				trackSubagentPendingCandidate(session, reviveCapture);
				trackSubagentIrcRoster(session, sessionSpec.prompt);
				reviveSession = createWarmSubagentReviver(reviveCapture);
			}

			// Emit lifecycle start event
			const startedPayload = {
				id,
				agent: agent.name,
				parentToolCallId: options.parentToolCallId,
				detached: options.detached,
				agentSource: agent.source,
				description: options.description,
				status: "started" as const,
				sessionFile: subtaskSessionFile,
				index,
			};
			emitSubagentFrame(options.eventBus, options.subagentEventBus, TASK_SUBAGENT_LIFECYCLE_CHANNEL, startedPayload);

			const subagentToolNames = session.getEnabledToolNames();
			const filteredSubagentTools = subagentToolNames.filter(name => !isParentOwnedTool(name));
			if (filteredSubagentTools.length !== subagentToolNames.length) {
				await awaitAbortable(session.setActiveToolsByName(filteredSubagentTools));
			}
			if (options.workPoolYieldItems) {
				await awaitAbortable(session.setWorkPoolYieldItems(options.workPoolYieldItems));
			}
			const enabledSubagentTools = session.getEnabledToolNames();
			// The enabled set includes the synthetic write transport injected for
			// explicit tool lists that omitted write. `session_init.tools` is later
			// replayed as an explicit grant during cold revival, so persist write
			// only when the original agent contract granted it.
			const persistedSubagentTools =
				toolNames !== undefined && !toolNames.includes("write")
					? enabledSubagentTools.filter(name => name !== "write")
					: enabledSubagentTools;

			session.sessionManager.appendSessionInit({
				// Blocks as sent; the session appends a newer session_init whenever a model call's base changes.
				systemPrompt: session.agent.state.systemPrompt,
				task,
				tools: persistedSubagentTools,
				mountedTools: session.getMountedXdevToolNames(),
				agent: agent.name,
				modelRole: modelRole ?? resolveExplicitModelRole(modelOverride ?? agent.model, subagentSettings),
				resolvedModel: progress.resolvedModel,
				...(perCallModelGrants
					? {
							perCallModel: true,
							// Display selectors can conflate literal :level ids with effort, so revival records each separately.
							perCallModelIdentity: formatModelStringWithRouting(session.model!),
							perCallThinkingLevel: session.configuredThinkingLevel() ?? null,
						}
					: {}),
				// Deferred model resolution installs this role inside createAgentSession,
				// so read it back from the settings both install paths write.
				retryFallback: getRetryFallbackRole(subagentSettings, subagentRetryFallbackRole(id)),
				readOnly: isReadOnlyAgent(agent),
				spawns: spawnsEnv,
				readSummarize: agent.readSummarize,
				advisor: advisorSelection ? (advisorRolePattern ?? "on") : undefined,
				compactionThreshold: options.compactionThresholdOverride,
				outputSchema,
				outputSchemaMode: options.outputSchemaMode,
				restrictToolNames: restrictToolNames || undefined,
				// Isolated runs are never revivable (worktree merged + cleaned):
				// stamp the contract so cold revival leaves them transcript-only
				// even when the workspace was retained for recovery.
				isolated: worktree !== undefined || undefined,
			});

			abortSignal.addEventListener(
				"abort",
				() => {
					void monitor.abortActiveSession();
				},
				{ once: true, signal: sessionAbortController.signal },
			);
			// Defensive: if the wall-clock timer (or external signal) fired during
			// the awaited setup above, the listener registration races the dispatch
			// and may not observe the already-fired abort event. Mirror it manually.
			if (abortSignal.aborted) {
				void monitor.abortActiveSession();
			}

			// No closure in this block may capture `session`: JSC gives every closure in a
			// block one shared scope object, so the lifecycle reviver built above would
			// then pin the parked, disposed session for the life of the process.
			const pendingExtensionMessages: Array<Promise<unknown>> = [];
			await awaitAbortable(
				initializeExtensions(session, {
					reportSendError: (action, err) => logger.error("Extension send failed", { action, error: err.message }),
					reportRuntimeError: err =>
						logger.error("Extension error", { path: err.extensionPath, error: err.error }),
					trackExtensionSend: task => {
						pendingExtensionMessages.push(task.catch(() => {}));
					},
					filterActiveTools: toolNames => toolNames.filter(name => !isParentOwnedTool(name)),
				}),
			);
			while (pendingExtensionMessages.length > 0) {
				await awaitAbortable(Promise.all(pendingExtensionMessages.splice(0)));
			}

			unsubscribe = monitor.attach(session);

			checkAbort();
			// Autoload skills via sendCustomMessage (same mechanic as /skill:<name>)
			if (options.autoloadSkills?.length) {
				for (const skill of options.autoloadSkills) {
					const { message, details } = await buildSkillPromptMessage(skill, { args: "" }, "autoload", session);
					await session.sendCustomMessage(
						{
							customType: SKILL_PROMPT_MESSAGE_TYPE,
							content: message,
							display: false,
							details: { name: details.name, path: details.path },
						},
						{ triggerTurn: false },
					);
				}
			}

			readyAt = performance.now();
			// The run's monitor would take a wake turn's answer (a message result's
			// last report turn, or a `yield`) as the run's result. Only a kept-alive
			// agent has wake turns left to answer held messages in.
			if (options.keepAlive !== false) releaseIrcWakes = session.holdIrcWakes();
			const outcome = await driveSessionToResult(session, monitor, task, {
				solutionSpace: options.solutionSpace,
				structured,
			});
			// Acceptance boundary (#11079): the run's final result is settled, so
			// stamp the lifecycle and terminalize a ref the run-state mirror left
			// `running` before the (possibly slow) cleanup below.
			if (resultDelivered(outcome, monitor, structured)) {
				AgentRegistry.global().markResultAccepted(id, session, monitor.yieldAcceptedAt());
			}
			exitCode = outcome.exitCode;
			error = outcome.error;
			aborted = outcome.aborted;
			abortReasonText = outcome.abortReasonText;
		} catch (err) {
			exitCode = 1;
			if (!abortSignal.aborted) {
				error = err instanceof Error ? err.stack || err.message : String(err);
			}
		} finally {
			const cleanupDeadlineAt = Date.now() + cleanupGraceMs;
			const cleanupChangeStatus =
				worktree === undefined
					? "This task was not isolated, so its changes may remain in the working directory."
					: "No isolated changes were applied.";
			const lateCleanups: Promise<void>[] = [];
			let deferredSessionShutdown: Promise<void> | undefined;
			const deferCleanup = (completion: Promise<void>): void => {
				lateCleanups.push(completion);
				// The run's terminal outcome (a successful `yield`, or a genuine
				// abort) is already settled; `aborted` reflects the authoritative
				// run status after the abort-signal reconciliation below. Late
				// cleanup (advisor drain, session disposal, owner-job reaping)
				// draining past the deadline is orthogonal — it MUST NOT downgrade
				// a non-aborted run to `aborted`, which discarded valid `agent()`
				// results (issue #9670). The deferred work still completes
				// asynchronously via `lateCleanups`/`onCleanupDeferred`.
				if (!aborted) return;
				exitCode = 1;
				abortReasonText = `cleanup exceeded ${cleanupGraceMs} ms`;
				error ??= `Task aborted. Cleanup did not finish within ${cleanupGraceMs} ms. ${cleanupChangeStatus}`;
			};
			if (abortSignal.aborted) {
				aborted = monitor.isAbortedRun();
				if (aborted) {
					abortReasonText ??= monitor.resolveAbortReasonText();
				}
				if (exitCode === 0) exitCode = 1;
			}
			sessionAbortController.abort();
			const activeSessionAbort = monitor.waitForActiveSessionAbort();
			try {
				await untilAborted(
					AbortSignal.timeout(Math.max(0, cleanupDeadlineAt - Date.now())),
					() => activeSessionAbort,
				);
			} catch (cleanupError) {
				if (Date.now() >= cleanupDeadlineAt) {
					deferCleanup(activeSessionAbort);
				} else {
					logger.warn("Subagent abort cleanup failed", {
						id,
						error: cleanupError instanceof Error ? cleanupError.message : String(cleanupError),
					});
				}
			}
			if (registryAbortUnsubscribe) {
				registryAbortUnsubscribe();
				registryAbortUnsubscribe = null;
			}
			if (unsubscribe) {
				try {
					unsubscribe();
				} catch {
					// Ignore unsubscribe errors
				}
				unsubscribe = null;
			}
			const jobManager = options.asyncJobManager;
			if (jobManager) {
				const reap = await jobManager.cancelAndReapOwnerJobs(id, cleanupDeadlineAt);
				if (!reap.settled) {
					deferCleanup(reap.completion);
					logger.warn("Subagent async job cleanup exceeded its deadline", {
						id,
						pendingJobIds: reap.pendingJobIds,
					});
				}
			}
			const session = monitor.takeActiveSession();
			if (session) {
				monitor.captureSalvage(session);
				if (options.keepAlive !== false && (!preparedSession || readyAt !== undefined)) {
					attachIrcWakeTurnMonitor(session, wakeOptions);
				}
				await finalizeSubagentLifecycle({
					id,
					session,
					aborted,
					abortKind: monitor.abortKind(),
					keepAlive: options.keepAlive !== false && (!preparedSession || readyAt !== undefined),
					isolated: worktree !== undefined,
					agentIdleTtlMs,
					reviveSession,
					cleanupDeadlineAt,
					onRelease: options.onRelease,
					onCleanupDeferred: completion => {
						deferredSessionShutdown = completion;
						deferCleanup(completion);
					},
				});
			}
			if (jobManager) {
				if (deferredSessionShutdown) {
					const finalReap = Promise.allSettled([deferredSessionShutdown]).then(async () => {
						const reap = await jobManager.cancelAndReapOwnerJobs(id, Date.now());
						await reap.completion;
					});
					lateCleanups.push(finalReap);
				} else {
					const reap = await jobManager.cancelAndReapOwnerJobs(id, cleanupDeadlineAt);
					if (!reap.settled) {
						deferCleanup(reap.completion);
						logger.warn("Subagent async job cleanup exceeded its deadline after session shutdown", {
							id,
							pendingJobIds: reap.pendingJobIds,
						});
					}
				}
			}
			if (preparedSession && untrackedSession) {
				const incompleteSession = untrackedSession;
				untrackedSession = undefined;
				const disposal = Promise.resolve().then(() => incompleteSession.dispose());
				pendingSessionDisposal = disposal.then(
					() => {},
					() => {},
				);
				try {
					await untilAborted(AbortSignal.timeout(Math.max(0, cleanupDeadlineAt - Date.now())), () => disposal);
				} catch (cleanupError) {
					if (Date.now() >= cleanupDeadlineAt) {
						deferCleanup(disposal);
					} else {
						logger.warn("Incomplete subagent session disposal failed", {
							id,
							error: cleanupError instanceof Error ? cleanupError.message : String(cleanupError),
						});
					}
				}
			}
			if (preparedSession && readyAt === undefined) {
				const removeFailedFork = (async () => {
					await pendingSessionDisposal;
					if (deferredSessionShutdown) await deferredSessionShutdown;
					let manager = openedSessionManager;
					if (!manager && pendingSessionManager) {
						manager = await pendingSessionManager.catch(() => undefined);
					}
					if (manager) {
						const ownedSessionFile = manager.getSessionFile();
						if (ownedSessionFile) await manager.dropSession(ownedSessionFile);
					}
				})().catch(cleanupError => {
					logger.warn("Failed to remove incomplete prepared session fork", {
						id,
						sessionFile: openedSessionManager?.getSessionFile(),
						error: cleanupError instanceof Error ? cleanupError.message : String(cleanupError),
					});
				});
				try {
					await untilAborted(
						AbortSignal.timeout(Math.max(0, cleanupDeadlineAt - Date.now())),
						() => removeFailedFork,
					);
				} catch (cleanupError) {
					if (Date.now() >= cleanupDeadlineAt) {
						deferCleanup(removeFailedFork);
					} else {
						logger.warn("Incomplete prepared session fork cleanup failed", {
							id,
							error: cleanupError instanceof Error ? cleanupError.message : String(cleanupError),
						});
					}
				}
			}
			if (lateCleanups.length > 0) {
				const completion = Promise.allSettled(lateCleanups).then(() => {});
				trackLateCleanup(completion, { id, resource: "subagent" });
				options.onCleanupDeferred?.(completion);
			}
		}

		// Launch-latency breakdown (subagent invocation → first chat dispatch).
		// Phase deltas are performance.now() spans; the task-tool concurrency
		// brackets use the Date.now epochs captured by the spawn site
		// (invokedAt before acquire, acquiredAt after) so queue wait and
		// pre-run setup are reported apart.
		const span = (from: number | undefined, to: number | undefined): number | undefined =>
			from !== undefined && to !== undefined ? Math.round(to - from) : undefined;
		const queueMs =
			options.invokedAt !== undefined && options.acquiredAt !== undefined
				? Math.round(options.acquiredAt - options.invokedAt)
				: undefined;
		const preRunMs = options.acquiredAt !== undefined ? Math.round(startTime - options.acquiredAt) : undefined;
		const setupToFirstChatMs = span(perfStart, firstChatDispatchAt);
		const invokeToFirstChatMs =
			options.invokedAt !== undefined && setupToFirstChatMs !== undefined
				? Math.round(startTime - options.invokedAt) + setupToFirstChatMs
				: undefined;
		logger.debug("subagent launch timing", {
			id,
			agent: agent.name,
			queueMs,
			preRunMs,
			resolveMs: span(perfStart, resolvedAt),
			sessionOpenMs: span(resolvedAt, sessionOpenedAt),
			createSessionMs: span(sessionOpenedAt, sessionCreatedAt),
			readyMs: span(sessionCreatedAt, readyAt),
			promptToFirstChatMs: span(readyAt, firstChatDispatchAt),
			setupToFirstChatMs,
			invokeToFirstChatMs,
		});
		return {
			exitCode,
			error,
			aborted,
			abortReason: aborted ? abortReasonText : undefined,
			durationMs: Date.now() - startTime,
		};
	};

	try {
		const done = await runSubagent();
		monitor.finish();

		const result = await finalizeRunResult({
			monitor,
			done,
			index,
			id,
			agent,
			task,
			assignment,
			modelOverride,
			modelRole,
			structured,
			outputSchema,
			outputSchemaMode: options.outputSchemaMode,
			outputSchemaSource: options.outputSchemaSource,
			signal,
			artifactsDir: options.artifactsDir,
			eventBus: options.eventBus,
			subagentEventBus: options.subagentEventBus,
			parentToolCallId: options.parentToolCallId,
			detached: options.detached,
			sessionFile: subtaskSessionFile,
			startTime,
		});
		AgentRegistry.global().setHistory(id, { outputPath: result.outputPath });
		return result;
	} finally {
		// The result is published: messages held during the run get their own
		// turns, unless the caller still has work to finish first.
		if (releaseIrcWakes && options.deferIrcWakeRelease) options.deferIrcWakeRelease(releaseIrcWakes);
		else releaseIrcWakes?.();
	}
}

/**
 * CDP façade over `chrome.debugger`.
 *
 * Puppeteer clients (the omp browser tool: one supervisor connection plus one
 * per tab worker) connect to this bridge as if it were Chrome's browser
 * debugging endpoint. Chrome only allows a single debugger attachment per tab,
 * so the bridge owns ONE `chrome.debugger` attachment per tab (via the
 * extension) and multiplexes every downstream connection over it with minted
 * per-connection session ids.
 *
 * Emulated surface (everything else is forwarded to `chrome.debugger`):
 * - the browser target (`/json/version` handshake, `Browser.getVersion`)
 * - the `Target.*` domain, including puppeteer's tab → page auto-attach
 *   hierarchy (see puppeteer-core `cdp/ExtensionTransport.ts`, the reference
 *   implementation for this emulation)
 *
 * Session id namespaces seen by a downstream connection:
 * - minted tab pseudo-sessions (`ST<tab>.<conn>.<n>`) — Target emulation only
 * - minted page pseudo-sessions (`SP<tab>.<conn>.<n>`) — forwarded to the
 *   tab's root debugger session
 * - real child session ids (OOPIFs, workers) — created by Chrome under the
 *   shared root session and passed through verbatim
 */
import { createHash } from "node:crypto";
import { VERSION } from "@oh-my-pi/pi-utils/dirs";
import { BROWSER_PROTOCOL_TIMEOUT_MS } from "../launch";
import {
	DISCARDED_TABS_PROTOCOL_VERSION,
	EXTENSION_RELOAD_PROTOCOL_VERSION,
	isOlderOmpVersion,
	isOmpVersion,
} from "./protocol";
import type { ExtToRelayMessage, RelayRpcRequest, RelayToExtMessage, TabSnapshot } from "./protocol";

/** Transport-agnostic websocket surface the bridge writes to. */
export interface RelaySocket {
	send(text: string): void;
	close(): void;
}

interface CdpCommand {
	id: number;
	method: string;
	params?: Record<string, unknown>;
	sessionId?: string;
}

/**
 * Per-pseudo-session Runtime domain state.
 * - `default`: never toggled Runtime — still receives the relay's legacy
 *   root-event fan-out, so omp's own patched-puppeteer client (which
 *   pull-acquires contexts and never sends `Runtime.enable`) keeps getting
 *   `Runtime.executionContextCreated`.
 * - `enabled`: ran `Runtime.enable`; gets the existing-context replay.
 * - `disabled`: explicitly ran `Runtime.disable`; silenced until it re-enables.
 */
type RuntimeState = "default" | "enabled" | "disabled";

interface SessionRef {
	kind: "tab" | "page";
	/** Registry key of the owning tab (`<instance code>:<chrome tabId>`). */
	tabKey: string;
	tabId: number;
	runtimeState: RuntimeState;
	/** Context ids already announced to this pseudo-session. */
	readonly runtimeContexts: Set<number>;
	/** In-flight `Runtime.enable` for this session; duplicates await it. */
	runtimeEnabling: Promise<void> | null;
	/** Monotonic ownership token for enable rollback and replay. */
	runtimeEpoch: number;
	/** Sent `Target.setAutoAttach`; only such a session is told about real child targets. */
	autoAttach: boolean;
	/** Asked for `Page.setInterceptFileChooserDialog`; the tab keeps it on while any of its sessions does. */
	interceptsFileChooser: boolean;
}

interface TargetInfo {
	targetId: string;
	type: "tab" | "page" | "browser";
	title: string;
	url: string;
	attached: boolean;
	canAccessOpener: boolean;
}

class CdpConnection {
	discover = false;
	autoAttach = false;
	/** Minted pseudo-sessions owned by this connection. */
	readonly sessions = new Map<string, SessionRef>();
	/** Tabs this connection claimed as drive targets (`OMP.claimTarget` / `Target.createTarget`). */
	readonly claims = new Set<string>();
	/** Real child session id → the session it was announced on; its events and detach go there. */
	readonly childParents = new Map<string, string>();

	constructor(
		readonly id: number,
		readonly socket: RelaySocket,
	) {}

	sessionsForTab(tabKey: string, kind?: "tab" | "page"): string[] {
		const out: string[] = [];
		for (const [sessionId, ref] of this.sessions) {
			if (ref.tabKey === tabKey && (!kind || ref.kind === kind)) out.push(sessionId);
		}
		return out;
	}

	/** This tab's first page session that armed auto-attach; one per connection so no child is announced twice. */
	childTargetSessionForTab(tabKey: string): string | undefined {
		for (const [sessionId, ref] of this.sessions) {
			if (ref.tabKey === tabKey && ref.kind === "page" && ref.autoAttach) return sessionId;
		}
		return undefined;
	}
}

/** Transport replacement is retryable and must not permanently ban a tab. */
class ExtensionReplacedError extends Error {}

/**
 * Rewrites the files of the extension Chrome knows as `extensionId` to this omp's, when that is the copy this relay
 * may update; resolves whether the files on disk are now this omp's (then the bridge asks the extension to reload).
 */
export type RelayBridgeExtensionUpdater = (extensionId: string) => Promise<boolean>;

/** A connected extension browser instance; one per browser/profile. */
interface ExtInstance {
	instanceId: string;
	/** Short code derived from the instance id and browser run; names target ids (`TAB<code>.<tabId>`). */
	code: string;
	socket: RelaySocket | null;
	info: {
		userAgent: string;
		browserVersion: string;
		discardedTabsProtocol?: number;
		ompVersion?: string;
		reloadProtocol?: number;
	} | null;
	/** Chrome extension id from the socket's `Origin`; null when the upgrade carried none. */
	extensionId: string | null;
	/** The relay is rewriting this extension's files to reload it: not ready meanwhile (its socket closes after). */
	updating: boolean;
	/** `Date.now()` when its socket closed; null while connected. */
	goneSince: number | null;
	/** Settles at its next hello; created by the first caller that waits for one. */
	reconnected: PromiseWithResolvers<void> | null;
}

/**
 * Deterministic per-instance code for target ids: stable across relay restarts and service-worker restarts, new
 * after a browser restart (when Chrome reuses tab ids). Older extensions send no browser session.
 */
function instanceCode(instanceId: string, browserSession: string): string {
	const identity = browserSession ? `${instanceId}/${browserSession}` : instanceId;
	return createHash("sha256").update(identity).digest("base64url").slice(0, 8);
}

function tabKeyOf(extCode: string, tabId: number): string {
	return `${extCode}:${tabId}`;
}

function tabTargetIdFromKey(key: string): string {
	return `TAB${key.replace(":", ".")}`;
}

function pageTargetIdFromKey(key: string): string {
	return `PAGE${key.replace(":", ".")}`;
}

function parseTargetId(targetId: string): { key: string; kind: "tab" | "page" } | null {
	const match = /^(TAB|PAGE)([^.]+)\.(\d+)$/.exec(targetId);
	if (!match) return null;
	const kind: "tab" | "page" = match[1] === "TAB" ? "tab" : "page";
	return { key: `${match[2]}:${match[3]}`, kind };
}

class TabState {
	/** Assigned in the constructor body from the owning instance. */
	readonly tabKey: string;
	url: string;
	title: string;
	active: boolean;
	/** Discarded tabs cannot answer debugger calls. */
	discarded: boolean;
	windowId: number;
	pinned: boolean;
	/** Chrome tab group id from the last snapshot; -1 when ungrouped. */
	groupId: number;
	/** Whether `chrome.debugger` is currently attached to this tab. */
	attached = false;
	/**
	 * Why Chrome refused omp this tab (its attach error, or the user cancelling the debugger bar); while set the
	 * tab is not adoptable. Cleared on navigation.
	 */
	refusal: string | undefined;
	/** Explicit debugger cancellation cannot be retried until navigation. */
	banned = false;
	/** Whether targets for this tab were announced to discovering connections. */
	announced = false;
	attaching: Promise<boolean> | null = null;
	/** Discard cancels the waiter but keeps the extension RPC alive for late cleanup. */
	attachCancelled = false;
	attachGeneration = 0;
	cancelAttach: (() => void) | null = null;
	/** Retry when a revived tab's canceled attach request finally settles. */
	retryAttachAfterDiscard = false;
	/** Relay-initiated detach in flight; reattach serializes behind it. */
	detaching: Promise<void> | null = null;
	/** A successful attach completed after the most recently requested relay detach. */
	reattachedAfterDetach = false;
	/** The relay asked the extension to close this tab (`Target.closeTarget`); its coming detach is not Chrome's own. */
	closing = false;
	/** True after the relay put this tab in the omp group; `ompGroupId` holds that group. */
	grouped = false;
	/** Group RPC in flight — suppresses duplicate requests from load-time tabUpdated bursts. */
	grouping = false;
	ompGroupId: number | undefined;
	/** Normalized session label for omp-owned tab grouping. */
	label?: string;
	/** Creator's temporary claim; the worker that owns this new tab takes it over. */
	provisionalClaimConnId?: number;
	/** User pulled the tab out of the omp group — never re-group it. */
	groupOptOut = false;
	/** The app in front of the user when omp's input last reached this tab, and when; a window the tab opens uses it once. */
	frontAtInput: { app: FrontApp; at: number } | null = null;
	/**
	 * The extension created this tab for omp in the current browser session
	 * (hello `ownedTabIds`, or `Target.createTarget` here). The orphan reaper
	 * closes only such tabs, so a stale record whose tab id Chrome reused after
	 * a restart can never close a user tab.
	 */
	ompCreated = false;
	/**
	 * Real Chrome sessions (OOPIF/worker children) under this tab's attachment: the child session
	 * that reported each (none for the root) and its `Target.attachedToTarget` params.
	 */
	readonly realSessions = new Map<string, { parent: string | undefined; event: Record<string, unknown> }>();
	/** Live execution contexts from the shared root debugger session. */
	readonly runtimeContexts = new Map<number, Record<string, unknown>>();
	/** Whether the shared root Runtime domain has been enabled by the bridge. */
	rootRuntimeEnabled = false;
	rootRuntimeEnabling: Promise<void> | null = null;
	/** Invalidates an in-flight Runtime enable when the debugger detaches. */
	runtimeGeneration = 0;
	/** Settled by the next detach Chrome reports on its own (not one the relay requested). */
	chromeDetach = Promise.withResolvers<void>();

	constructor(
		readonly instanceId: string,
		readonly extCode: string,
		readonly tabId: number,
		snap: TabSnapshot,
	) {
		this.tabKey = tabKeyOf(extCode, tabId);
		this.url = snap.url;
		this.title = snap.title;
		this.active = snap.active;
		this.discarded = snap.discarded;
		this.windowId = snap.windowId;
		this.pinned = snap.pinned;
		this.groupId = snap.groupId;
	}

	update(snap: TabSnapshot): void {
		this.url = snap.url;
		this.title = snap.title;
		this.active = snap.active;
		this.discarded = snap.discarded;
		this.windowId = snap.windowId;
		this.pinned = snap.pinned;
		this.groupId = snap.groupId;
	}
}

/** URLs `chrome.debugger` cannot attach to; hidden from downstream discovery entirely. */
const INELIGIBLE_URL = /^(chrome|devtools|edge|view-source|chrome-extension|chrome-untrusted|chrome-search):/i;

const RPC_TIMEOUT_MS = 20_000;
/** How long after its timeout a late RPC result is still undone; a wedged extension must not grow the map forever. */
const LATE_RPC_KEEP_MS = 60_000;
const CDP_ERROR_METHOD_NOT_FOUND = -32601;
const CDP_ERROR_SERVER = -32000;
/**
 * How long a new tab waits for the browser it belongs in (that of `nearTargetId` or of a tab the client drives) to
 * reconnect after its socket closed: the extension's longest reconnect backoff (10 s) plus its hello.
 */
const AFFINE_RECONNECT_WAIT_MS = 12_000;
/** Chrome's answer to a command in flight when it ends the debugger attachment. */
const DETACHED_COMMAND_ERROR = /Detached while handling command/;
/** How long such a failure waits for the extension to report the detach itself. */
const CHROME_DETACH_REPORT_MS = 1_000;
/** {@link RelayBridge.#rpc}'s failure when the extension sent no answer within the deadline. */
class RpcTimeoutError extends Error {}
/**
 * Deadline for a command whose answer waits on the page itself (a promise it settles, a navigation it commits),
 * where {@link RPC_TIMEOUT_MS} is for one Chrome answers at once. omp's own clients give up at
 * `BROWSER_PROTOCOL_TIMEOUT_MS`, as on a launched Chrome; the relay waits a little longer so their error, not the
 * relay's, reaches the call.
 */
const PAGE_BOUND_RPC_TIMEOUT_MS = BROWSER_PROTOCOL_TIMEOUT_MS + 5_000;
/** A window a tab opens this long after omp's input reached it is still taken to be that input's doing. */
const POPUP_AFTER_INPUT_MS = 1_000;
/** How long the user's app is held in front after omp's input opened a window; Chrome activates within milliseconds. */
const KEEP_FRONT_MS = 500;
/**
 * omp's CDP inputs a page can open a window on, by method and event `type`: those that give the page user activation
 * (a button or key going down, a release, a tap). Moves, wheels, key-ups and inserted text never do, so they read no
 * front app. `true`: every event of that method.
 */
const WINDOW_OPENING_INPUT: Record<string, Record<string, true> | true> = {
	"Input.dispatchMouseEvent": { mousePressed: true, mouseReleased: true },
	"Input.emulateTouchFromMouseEvent": { mousePressed: true, mouseReleased: true },
	"Input.dispatchKeyEvent": { keyDown: true, rawKeyDown: true },
	"Input.dispatchTouchEvent": { touchStart: true, touchEnd: true },
	"Input.synthesizeTapGesture": true,
};

function canOpenWindow(method: string, params: Record<string, unknown> | undefined): boolean {
	if (!Object.hasOwn(WINDOW_OPENING_INPUT, method)) return false;
	const types = WINDOW_OPENING_INPUT[method];
	const type = params?.type;
	return types === true || (typeof type === "string" && Object.hasOwn(types, type));
}

/** The app in front of the user, as `macOSFrontApp` from `@oh-my-pi/pi-natives` reads it. */
export interface FrontApp {
	/** Puts the app back in front each time the app that took the front takes it again within `durationMs`, until the user picks an app; resolves how many times. */
	keepInFront(durationMs: number): Promise<number>;
}

/**
 * Multiplexing CDP bridge between downstream puppeteer connections and the
 * relay extension. One instance per relay server; all state lives here so an
 * extension service-worker restart only has to re-handshake.
 */
export class RelayBridge {
	/** Tab registries keyed by `<instance code>:<chrome tabId>`; one namespace per browser instance. */
	#tabs = new Map<string, TabState>();
	#conns = new Map<number, CdpConnection>();
	#connSeq = 0;
	#sessionSeq = 0;
	#rpcSeq = 0;
	/** Connected extension browser instances, keyed by stable instance id. */
	#instances = new Map<string, ExtInstance>();
	#socketInstance = new Map<RelaySocket, string>();
	/** Chrome extension id each extension socket's upgrade named in its `Origin`. */
	#socketExtensionId = new Map<RelaySocket, string>();
	/** Rewrites the files of the extension with this id to this omp's; resolves whether it did (see {@link RelayBridgeExtensionUpdater}). */
	#updateExtension: RelayBridgeExtensionUpdater | null;
	/** Per instance, the extension versions the relay already reloaded it from: never twice from the same one. */
	#updateTried = new Map<string, Set<string>>();
	/** Instance whose hello ran last: answers browser-wide requests and owns created tabs. */
	#lastHelloInstance: string | null = null;
	#extensionSeen = false;
	/**
	 * Tabs omp opened whose close failed while their browser was offline (see {@link #closeTab}), by tab key, with
	 * the URL the tab showed: closed at that browser's next hello, unless the tab is gone or shows another page.
	 */
	#closeOnHello = new Map<string, string>();
	/** `Date.now()` when the last ready extension socket closed; null while one is ready or none ever was. */
	#extensionGoneSince: number | null = null;
	#pendingRpc = new Map<
		string,
		{ resolve: (value: unknown) => void; reject: (err: Error) => void; timer: NodeJS.Timeout }
	>();
	/**
	 * Timed-out RPCs whose late success still needs undoing (a tab Chrome created after omp gave up), by
	 * `instance:id`.
	 */
	#lateRpc = new Map<string, { onResult: (result: unknown) => void; timer: NodeJS.Timeout }>();
	/** Real child session id → owning tab key, learned from `Target.attachedToTarget` events. */
	#realSessionTabs = new Map<string, string>();
	#log: (message: string, data?: Record<string, unknown>) => void;
	/** Tab-group appearance for driven tabs; null disables grouping. */
	#group: { title: string; color: string } | null;
	/** Tabs awaiting the next group RPC; drained one batch at a time. */
	#groupQueue: TabState[] = [];
	/** True while {@link #drainGroupQueue} runs — group RPCs must never overlap. */
	#groupDraining = false;
	/** Each tab's last file chooser interception transition; see {@link #serializeInterception}. */
	#interceptionTransitions = new Map<string, Promise<void>>();
	/** Reads the app in front of the user; set by {@link keepFrontAppWith} where the relay can put it back (macOS). */
	#readFrontApp: (() => FrontApp | null) | undefined;
	/**
	 * When the running hold on the user's app ends (`Date.now()` ms), at its deadline or once it settles, whichever is
	 * first; 0 with none. A window opened meanwhile shares it, and omp's input reads no front app then: the browser may
	 * be in front, and a later hold would keep it there.
	 */
	#keepingFrontUntil = 0;

	constructor(
		opts: {
			log?: (message: string, data?: Record<string, unknown>) => void;
			/** Group tabs the agent actively drives under one per-window Chrome tab group. */
			group?: { title: string; color: string } | null;
			/** Enables extension self-update; absent, the relay never rewrites or reloads an extension. */
			updateExtension?: RelayBridgeExtensionUpdater;
		} = {},
	) {
		this.#log = opts.log ?? (() => {});
		this.#group = opts.group ?? null;
		this.#updateExtension = opts.updateExtension ?? null;
	}

	/** True once an extension has completed its hello handshake, and the relay is not rewriting its files. */
	get ready(): boolean {
		for (const inst of this.#instances.values()) {
			if (inst.socket && inst.info && !inst.updating) return true;
		}
		return false;
	}

	/** The instance whose hello ran last (browser-wide requests route there). */
	#lastHello(): ExtInstance | undefined {
		if (this.#lastHelloInstance) {
			const inst = this.#instances.get(this.#lastHelloInstance);
			if (inst?.socket) return inst;
		}
		for (const inst of this.#instances.values()) {
			if (inst.socket) return inst;
		}
		return undefined;
	}

	/**
	 * The browser the caller's tabs live in: the one named by `nearTargetId` (a tab the caller drives on another
	 * connection; omp gives every tab its own), else one holding a tab this connection drives. Offline or not.
	 */
	#affineInstance(conn: CdpConnection, nearTargetId: unknown): ExtInstance | undefined {
		const near = typeof nearTargetId === "string" ? parseTargetId(nearTargetId) : null;
		if (near) {
			// The target id names its browser even after the user closed that tab.
			const code = near.key.slice(0, near.key.indexOf(":"));
			const inst = [...this.#instances.values()].find(inst => inst.code === code);
			if (inst) return inst;
		}
		const own = [...conn.claims].map(key => this.#tabs.get(key)).find(tab => tab !== undefined);
		return own && this.#instances.get(own.instanceId);
	}

	/** Wait for an offline browser's hello, up to {@link AFFINE_RECONNECT_WAIT_MS} after its socket closed. */
	async #awaitReconnect(inst: ExtInstance): Promise<void> {
		if (inst.socket || inst.goneSince === null) return;
		const left = inst.goneSince + AFFINE_RECONNECT_WAIT_MS - Date.now();
		if (left <= 0) return;
		inst.reconnected ??= Promise.withResolvers<void>();
		const timeout = Promise.withResolvers<void>();
		const timer = setTimeout(timeout.resolve, left);
		try {
			await Promise.race([inst.reconnected.promise, timeout.promise]);
		} finally {
			clearTimeout(timer);
		}
	}

	/**
	 * The browser a new tab opens in: the caller's ({@link #affineInstance}), else the one showing the first selected
	 * tab (the tab an open without a target used to adopt), else the last hello, so a reconnecting extension's hello
	 * does not move new tabs to another browser.
	 */
	#instanceForNewTab(affine: ExtInstance | undefined): ExtInstance | undefined {
		if (affine?.socket) return affine;
		for (const tab of this.#tabs.values()) {
			if (!tab.active || tab.discarded || !this.#eligible(tab)) continue;
			const inst = this.#instances.get(tab.instanceId);
			if (inst?.socket) return inst;
		}
		const last = this.#lastHello();
		if (!last || [...this.#tabs.values()].some(tab => tab.instanceId === last.instanceId)) return last;
		return (
			[...this.#instances.values()].find(
				inst => inst.socket && [...this.#tabs.values()].some(tab => tab.instanceId === inst.instanceId),
			) ?? last
		);
	}

	/** True after the first hello, and stays true: separates a reaped service worker from an absent extension. */
	get extensionSeen(): boolean {
		return this.#extensionSeen;
	}

	/** Milliseconds since the last ready extension disconnected, or null while one is connected or none ever was. */
	get extensionGoneForMs(): number | null {
		return this.#extensionGoneSince === null ? null : Date.now() - this.#extensionGoneSince;
	}

	/** Downstream CDP clients (omp browser sessions, puppeteer) connected right now. */
	get cdpClientCount(): number {
		return this.#conns.size;
	}

	/** Payload for `GET /json/version`. */
	versionInfo(wsUrl: string): Record<string, string | number> {
		const info = this.#lastHello()?.info;
		let hasCompatibleExtension = false;
		// The oldest connected extension's installing omp, so a current browser cannot hide a stale one.
		// A stamp of unknown age yields to any other, so it cannot hide one either.
		let oldestExtensionOmp: string | undefined;
		for (const instance of this.#instances.values()) {
			if (!instance.socket || instance.info?.discardedTabsProtocol !== DISCARDED_TABS_PROTOCOL_VERSION) continue;
			// Its files are being rewritten; it says which version it runs once it is back.
			if (instance.updating) continue;
			hasCompatibleExtension = true;
			const ompVersion = instance.info.ompVersion ?? "";
			if (
				oldestExtensionOmp === undefined ||
				isOlderOmpVersion(ompVersion, oldestExtensionOmp) ||
				(oldestExtensionOmp !== "" && !isOmpVersion(oldestExtensionOmp))
			) {
				oldestExtensionOmp = ompVersion;
			}
		}
		const ua = info?.userAgent ?? "";
		return {
			Browser: info?.browserVersion ?? "Chrome/unknown",
			"Protocol-Version": "1.3",
			"User-Agent": ua,
			"V8-Version": "",
			"WebKit-Version": "",
			webSocketDebuggerUrl: wsUrl,
			ompRelayVersion: VERSION,
			ompRelayDiscardedTabsProtocol: String(DISCARDED_TABS_PROTOCOL_VERSION),
			ompExtensionDiscardedTabsProtocol: String(hasCompatibleExtension ? DISCARDED_TABS_PROTOCOL_VERSION : 0),
			ompRelayCdpClients: this.#conns.size,
			ompExtensionVersion: oldestExtensionOmp ?? "",
		};
	}

	/** Payload for `GET /json/list` (debugging aid; per-target endpoints are not served). */
	listTargets(): Array<Record<string, string>> {
		const out: Array<Record<string, string>> = [];
		for (const tab of this.#tabs.values()) {
			if (!this.#eligible(tab)) continue;
			out.push({
				id: pageTargetIdFromKey(tab.tabKey),
				type: "page",
				title: tab.title,
				url: tab.url,
				active: String(tab.active),
				discarded: String(tab.discarded),
			});
		}
		return out;
	}

	// ---- extension lifecycle -------------------------------------------------

	#rejectPendingExtensionRpcs(instanceId: string, error: Error): void {
		const prefix = `${instanceId}:`;
		for (const [key, pending] of this.#pendingRpc) {
			if (!key.startsWith(prefix)) continue;
			clearTimeout(pending.timer);
			pending.reject(error);
			this.#pendingRpc.delete(key);
		}
	}

	/**
	 * A new extension socket connected; its hello assigns (or reuses) a browser instance.
	 * `extensionId` is the Chrome extension id its upgrade's `Origin` named, if any.
	 */
	extConnected(socket: RelaySocket, extensionId?: string): void {
		if (extensionId) this.#socketExtensionId.set(socket, extensionId);
		this.#log("extension socket connected");
	}

	extClosed(socket: RelaySocket): void {
		this.#socketExtensionId.delete(socket);
		const instanceId = this.#socketInstance.get(socket);
		if (instanceId === undefined) return;
		this.#socketInstance.delete(socket);
		const inst = this.#instances.get(instanceId);
		if (!inst || inst.socket !== socket) return;
		inst.socket = null;
		inst.goneSince = Date.now();
		inst.updating = false;
		this.#rejectPendingExtensionRpcs(instanceId, new Error("relay extension disconnected"));
		// Keep the instance's tabs listed (the browser may reconnect), but drop
		// debugger state: the attachment died with the service worker.
		for (const tab of this.#tabs.values()) {
			if (tab.instanceId !== instanceId) continue;
			tab.attached = false;
			tab.attaching = null;
			this.#resetRuntime(tab);
			// The extension dissolves omp groups on disconnect (or died along
			// with them); grouping state is unknowable until the next hello.
			tab.grouped = false;
			tab.grouping = false;
			tab.ompGroupId = undefined;
		}
		this.#groupQueue = this.#groupQueue.filter(tab => tab.instanceId !== instanceId);
		if (!this.ready) this.#extensionGoneSince ??= Date.now();
	}

	extMessage(socket: RelaySocket, raw: string): void {
		let msg: ExtToRelayMessage;
		try {
			msg = JSON.parse(raw) as ExtToRelayMessage;
		} catch {
			this.#log("dropping malformed extension message");
			return;
		}
		if (msg.t === "hello") {
			this.#onHello(socket, msg);
			return;
		}
		const instanceId = this.#socketInstance.get(socket);
		if (instanceId === undefined) return;
		const inst = this.#instances.get(instanceId);
		if (!inst || inst.socket !== socket) return;
		switch (msg.t) {
			case "rpcResult": {
				const key = `${instanceId}:${msg.id}`;
				const pending = this.#pendingRpc.get(key);
				if (!pending) {
					const late = this.#lateRpc.get(key);
					if (!late) return;
					this.#lateRpc.delete(key);
					clearTimeout(late.timer);
					if (msg.ok) late.onResult(msg.result);
					if (this.#conns.size === 0) void this.#updateIdleExtensions();
					return;
				}
				this.#pendingRpc.delete(key);
				clearTimeout(pending.timer);
				if (msg.ok) pending.resolve(msg.result);
				else pending.reject(new Error(msg.error ?? "extension rpc failed"));
				return;
			}
			case "cdpEvent":
				this.#onCdpEvent(tabKeyOf(inst.code, msg.tabId), msg.sessionId, msg.method, msg.params);
				return;
			case "detached":
				this.#onTabDetached(tabKeyOf(inst.code, msg.tabId), msg.reason, msg.relayInitiated === true);
				return;
			case "tabCreated":
				this.#onTabUpsert(msg.tab, instanceId);
				return;
			case "tabUpdated":
				this.#onTabUpsert(msg.tab, instanceId);
				return;
			case "tabRemoved":
				this.#onTabRemoved(tabKeyOf(inst.code, msg.tabId));
				return;
			case "ping":
				socket.send(JSON.stringify({ t: "pong" } satisfies RelayToExtMessage));
				return;
		}
	}

	#onHello(socket: RelaySocket, msg: Extract<ExtToRelayMessage, { t: "hello" }>): void {
		// Hellos without an instance id (legacy extension builds) share one anon
		// instance and keep the historical latest-wins replacement semantics.
		const instanceId = typeof msg.instanceId === "string" && msg.instanceId.length > 0 ? msg.instanceId : "anon";
		const code = instanceCode(instanceId, typeof msg.browserSession === "string" ? msg.browserSession : "");
		let inst = this.#instances.get(instanceId);
		if (!inst) {
			inst = {
				instanceId,
				code,
				socket: null,
				info: null,
				goneSince: null,
				reconnected: null,
				extensionId: null,
				updating: false,
			};
			this.#instances.set(instanceId, inst);
		} else if (inst.socket && inst.socket !== socket) {
			// Same browser reconnected (service-worker restart): retire the old
			// socket. Debugger-derived state dies with the old attachment, so
			// reset runtime state exactly like the old single-slot replace did;
			// the hello's attachedTabIds reconciliation runs right after.
			for (const tab of this.#tabs.values()) {
				if (tab.instanceId === instanceId) this.#resetRuntime(tab);
			}
			this.#rejectPendingExtensionRpcs(instanceId, new ExtensionReplacedError());
			this.#socketInstance.delete(inst.socket);
			inst.socket.close();
		}
		if (inst.code !== code) {
			// The browser restarted, and Chrome reuses tab ids: retire the previous run's targets, and the closes
			// queued for them, so an old target id cannot name a tab the user opened since.
			for (const [key, tab] of this.#tabs) {
				if (tab.instanceId === instanceId) this.#onTabRemoved(key);
			}
			for (const key of this.#closeOnHello.keys()) {
				if (key.startsWith(`${inst.code}:`)) this.#closeOnHello.delete(key);
			}
			inst.code = code;
		}
		inst.socket = socket;
		inst.goneSince = null;
		inst.reconnected?.resolve();
		inst.reconnected = null;
		this.#socketInstance.set(socket, instanceId);
		inst.extensionId = this.#socketExtensionId.get(socket) ?? null;
		inst.updating = false;
		inst.info = {
			userAgent: msg.userAgent,
			browserVersion: msg.browserVersion,
			discardedTabsProtocol: msg.discardedTabsProtocol,
			ompVersion: typeof msg.ompVersion === "string" ? msg.ompVersion : undefined,
			reloadProtocol: msg.reloadProtocol,
		};
		this.#lastHelloInstance = instanceId;
		this.#extensionSeen = true;
		this.#extensionGoneSince = null;
		// The hello GC is scoped to this instance: another browser's tabs are
		// untouched, which is what lets Chrome and Edge share one relay.
		const seen = new Set<number>();
		const attachedNow = new Set(msg.attachedTabIds);
		for (const snap of msg.tabs) {
			seen.add(snap.tabId);
			this.#onTabUpsert(snap, instanceId, { silent: true });
		}
		for (const [key, tab] of this.#tabs) {
			if (tab.instanceId !== instanceId || seen.has(tab.tabId)) continue;
			this.#onTabRemoved(key);
		}
		// Absent on older extensions: keep what this relay learned from its own createTarget calls.
		const ompCreated = Array.isArray(msg.ownedTabIds) ? new Set(msg.ownedTabIds) : null;
		// Close the tabs whose close failed while this browser was offline, unless the user closed them meanwhile or
		// the id now names another page.
		for (const [key, url] of this.#closeOnHello) {
			if (!key.startsWith(`${inst.code}:`)) continue;
			if (this.#claimed(key)) {
				this.#closeOnHello.delete(key);
				continue;
			}
			this.#closeOnHello.delete(key);
			const closed = this.#tabs.get(key);
			if (closed?.url === url) void this.#closeTab(key, closed.tabId, inst).catch(() => undefined);
		}
		for (const tab of this.#tabs.values()) {
			if (tab.instanceId !== instanceId) continue;
			if (ompCreated) tab.ompCreated = ompCreated.has(tab.tabId);
			const wasAttached = tab.attached;
			tab.attached = attachedNow.has(tab.tabId);
			tab.attaching = null;
			tab.cancelAttach = null;
			tab.attachCancelled = false;
			if (!tab.attached) this.#forgetChildren(tab);
			if (tab.discarded) {
				// Retire held sessions now; revival will reannounce and attach the tab.
				this.#retractTab(tab);
				this.#detachIfUnheld(tab.tabKey);
				continue;
			}
			// A service-worker restart can drop attachments while downstream
			// connections still hold sessions: restore them best-effort.
			if (wasAttached && !tab.attached && this.#sessionHolders(tab.tabKey).length > 0) {
				void this.#ensureAttached(tab).then(ok => {
					if (!ok) this.#onTabDetached(tab.tabKey, "reattach_failed", false);
				});
			}
			// A tab the hello brings that no client was told about, such as one a browser opened before its
			// extension connected, is announced now: no later change has to happen for Puppeteer to see it.
			if (!tab.announced && this.#eligible(tab)) this.#announceTab(tab);
		}
		this.#syncGrouping();
		this.#log("extension connected", {
			instanceId,
			tabs: msg.tabs.length,
			version: msg.browserVersion,
			omp: inst.info.ompVersion,
		});
		this.#maybeUpdateExtension(inst);
	}

	// ---- extension self-update ------------------------------------------------

	/**
	 * The older omp version this extension runs, when the relay may replace it: the extension reloads on request,
	 * its script carries an omp version older than this relay's, its socket named its Chrome id, and the relay has
	 * not already reloaded it from that version (a reload that brings the same version back must not loop).
	 */
	#outdatedReloadable(inst: ExtInstance): string | null {
		const ompVersion = inst.info?.ompVersion ?? "";
		if (inst.info?.reloadProtocol !== EXTENSION_RELOAD_PROTOCOL_VERSION || !inst.extensionId) return null;
		if (!isOmpVersion(ompVersion) || !isOlderOmpVersion(ompVersion, VERSION)) return null;
		return this.#updateTried.get(inst.instanceId)?.has(ompVersion) ? null : ompVersion;
	}

	/**
	 * Why reloading this extension now would cost someone something, or null. A reload drops the extension's
	 * socket and every debugger attachment it holds, so it waits for no CDP client to be connected (no claimed
	 * tab, no held session) and none of the extension's tabs to be attached, attaching or detaching. It also waits
	 * out the extension's calls in flight and the tab closes queued for its next hello: the reloaded extension
	 * reports a new browser session, which retires the target ids they name, so a tab omp opened would stay open.
	 */
	#reloadBlocker(inst: ExtInstance): string | null {
		if (!inst.socket) return "disconnected";
		if (this.#conns.size > 0) return "CDP clients connected";
		for (const tab of this.#tabs.values()) {
			if (tab.instanceId === inst.instanceId && (tab.attached || tab.attaching || tab.detaching)) {
				return "tabs attached";
			}
		}
		// A call past its timeout whose late result still closes what it made (a tab created after omp gave up) counts.
		for (const key of [...this.#pendingRpc.keys(), ...this.#lateRpc.keys()]) {
			if (key.startsWith(`${inst.instanceId}:`)) return "extension calls pending";
		}
		for (const key of this.#closeOnHello.keys()) {
			if (key.startsWith(`${inst.code}:`)) return "tab closes queued";
		}
		return null;
	}

	/** Rewrite an outdated extension's files to this omp's and ask it to reload, when that costs nothing. */
	#maybeUpdateExtension(inst: ExtInstance): void {
		const updateExtension = this.#updateExtension;
		if (!updateExtension || inst.updating) return;
		const from = this.#outdatedReloadable(inst);
		if (from === null) return;
		const busy = this.#reloadBlocker(inst);
		if (busy !== null) {
			this.#log("extension update deferred", { instanceId: inst.instanceId, from, reason: busy });
			return;
		}
		const socket = inst.socket!;
		// Not ready while the files change: a client waits for the reloaded extension instead of connecting.
		inst.updating = true;
		void updateExtension(inst.extensionId!)
			.catch(err => {
				this.#log("extension update failed", { error: err instanceof Error ? err.message : String(err) });
				return false;
			})
			.then(updated => {
				if (inst.socket !== socket || !inst.updating) return;
				// A client may have connected or a tab attached while the files were written.
				const busy = updated ? this.#reloadBlocker(inst) : "files not rewritten";
				if (busy !== null) {
					inst.updating = false;
					this.#log("extension update stopped", { instanceId: inst.instanceId, from, reason: busy });
					return;
				}
				const tried = this.#updateTried.get(inst.instanceId) ?? new Set<string>();
				tried.add(from);
				this.#updateTried.set(inst.instanceId, tried);
				socket.send(JSON.stringify({ t: "reload" } satisfies RelayToExtMessage));
				this.#log("extension reloading into update", { instanceId: inst.instanceId, from, to: VERSION });
				// Retire the socket now, as if the reload had closed it: nothing new may reach a browser that is
				// about to drop its socket and attachments. An extension that ignored the request redials.
				socket.close();
				this.extClosed(socket);
			});
	}

	/**
	 * With no CDP client left, once every tab's attach and detach has settled (their cleanup included, which can start
	 * another detach): update the extensions that were kept busy. An attach left running after its tab was discarded
	 * is not awaited twice; its own RPC retries the update when it settles.
	 */
	async #updateIdleExtensions(): Promise<void> {
		const awaited = new Set<Promise<unknown>>();
		for (;;) {
			const busy = Array.from(this.#tabs.values(), tab => tab.attaching ?? tab.detaching).filter(
				(p): p is Promise<boolean> | Promise<void> => p !== null && !awaited.has(p),
			);
			if (busy.length === 0) break;
			for (const p of busy) awaited.add(p);
			await Promise.all(busy);
		}
		if (this.#conns.size > 0) return;
		for (const inst of this.#instances.values()) this.#maybeUpdateExtension(inst);
	}

	// ---- downstream (puppeteer) lifecycle -------------------------------------

	/** Register a downstream CDP websocket; returns the connection id. */
	cdpConnected(socket: RelaySocket): number {
		const conn = new CdpConnection(++this.#connSeq, socket);
		this.#conns.set(conn.id, conn);
		this.#log("cdp client connected", { conn: conn.id });
		return conn.id;
	}

	cdpClosed(connId: number): void {
		const conn = this.#conns.get(connId);
		if (!conn) return;
		this.#conns.delete(connId);
		const touched = new Set<string>();
		const intercepting = new Set<string>();
		for (const ref of conn.sessions.values()) {
			touched.add(ref.tabKey);
			if (ref.interceptsFileChooser) intercepting.add(ref.tabKey);
		}
		conn.sessions.clear();
		for (const tabKey of intercepting) this.#releaseFileChooserInterception(tabKey);
		// Tabs this client claimed leave the omp group unless another claimant
		// remains — session holders don't count: the long-lived registry
		// connection holds sessions on every tab without driving any of them.
		for (const tabId of conn.claims) {
			const tab = this.#tabs.get(tabId);
			if (tab?.provisionalClaimConnId === connId) tab.provisionalClaimConnId = undefined;
			if (tab) this.#syncTabGrouping(tab);
		}
		conn.claims.clear();
		// Drop the debugger (and its infobar) from tabs nobody drives anymore.
		for (const tabKey of touched) this.#detachIfUnheld(tabKey);
		this.#log("cdp client closed", { conn: connId });
		if (this.#conns.size === 0) void this.#updateIdleExtensions();
	}

	cdpMessage(connId: number, raw: string): void {
		const conn = this.#conns.get(connId);
		if (!conn) return;
		let msg: CdpCommand;
		try {
			msg = JSON.parse(raw) as CdpCommand;
		} catch {
			return;
		}
		if (typeof msg.id !== "number" || typeof msg.method !== "string") return;
		void this.#handleCdpCommand(conn, msg).catch(err => {
			this.#replyError(conn, msg, err instanceof Error ? err.message : String(err));
		});
	}

	// ---- command routing -------------------------------------------------------

	async #handleCdpCommand(conn: CdpConnection, msg: CdpCommand): Promise<void> {
		const sessionId = msg.sessionId;
		if (!sessionId) {
			await this.#handleBrowserCommand(conn, msg);
			return;
		}
		const ref = conn.sessions.get(sessionId);
		if (ref?.kind === "tab") {
			this.#handleTabSessionCommand(conn, msg, ref);
			return;
		}
		if (ref?.kind === "page") {
			await this.#handlePageSessionCommand(conn, msg, sessionId, ref);
			return;
		}
		const realTabKey = this.#realSessionTabs.get(sessionId);
		if (realTabKey !== undefined) {
			const announce =
				msg.method === "Target.setAutoAttach" && msg.params?.autoAttach === true && conn.childParents.has(sessionId)
					? () => this.#announceChildren(conn, realTabKey, sessionId, sessionId)
					: undefined;
			await this.#forwardToTab(conn, msg, realTabKey, sessionId, announce);
			return;
		}
		this.#replyError(conn, msg, `Unknown session id ${sessionId}`);
	}

	async #handlePageSessionCommand(
		conn: CdpConnection,
		msg: CdpCommand,
		sessionId: string,
		ref: SessionRef,
	): Promise<void> {
		if (msg.method === "Runtime.disable") {
			ref.runtimeState = "disabled";
			ref.runtimeEpoch++;
			ref.runtimeContexts.clear();
			// Abandon any in-flight enable's ownership: a later enable starts fresh
			// rather than joining a cycle that predates this disable.
			ref.runtimeEnabling = null;
			this.#reply(conn, msg, {});
			return;
		}
		if (msg.method !== "Runtime.enable") {
			if (msg.method === "Target.setAutoAttach") {
				// Armed while in flight (Chrome reports existing children before it
				// answers); a failed request restores the previous state.
				const previous = ref.autoAttach;
				ref.autoAttach = msg.params?.autoAttach === true;
				const announce = () => {
					const parent = conn.childTargetSessionForTab(ref.tabKey);
					if (parent && conn.sessions.get(sessionId) === ref)
						this.#announceChildren(conn, ref.tabKey, undefined, parent);
				};
				if (!(await this.#forwardToTab(conn, msg, ref.tabKey, undefined, ref.autoAttach ? announce : undefined))) {
					ref.autoAttach = previous;
				}
				return;
			}
			if (msg.method === "Page.setInterceptFileChooserDialog") {
				// Every session of a tab shares one debugger attachment, so interception is tab-wide here: one
				// session switching it off must not cancel another session's chooser wait.
				await this.#serializeInterception(ref.tabKey, async () => {
					const previous = ref.interceptsFileChooser;
					ref.interceptsFileChooser = msg.params?.enabled === true;
					const params = { ...msg.params, enabled: this.#interceptsFileChooser(ref.tabKey) };
					if (!(await this.#forwardToTab(conn, { ...msg, params }, ref.tabKey, undefined))) {
						ref.interceptsFileChooser = previous;
					}
				});
				return;
			}
			await this.#forwardToTab(conn, msg, ref.tabKey, undefined);
			return;
		}
		// A pipelined duplicate must await the in-flight enable, never ack early:
		// the root cycle may still fail, and success must trail the context replay.
		if (ref.runtimeEnabling) {
			await this.#awaitEnable(conn, msg, ref.runtimeEnabling);
			return;
		}
		if (ref.runtimeState === "enabled") {
			this.#reply(conn, msg, {});
			return;
		}
		const enabling = this.#enableSessionRuntime(conn, sessionId, ref);
		ref.runtimeEnabling = enabling;
		try {
			await this.#awaitEnable(conn, msg, enabling);
		} finally {
			if (ref.runtimeEnabling === enabling) ref.runtimeEnabling = null;
		}
	}

	/** Reply to one `Runtime.enable` command with the shared enable's outcome. */
	async #awaitEnable(conn: CdpConnection, msg: CdpCommand, enabling: Promise<void>): Promise<void> {
		try {
			await enabling;
			this.#reply(conn, msg, {});
		} catch (err) {
			this.#replyError(conn, msg, err instanceof Error ? err.message : String(err));
		}
	}

	/**
	 * Drive the shared root `Runtime.enable` for a session and replay the live
	 * contexts to it. Rejects if the root cycle fails so every joined caller
	 * observes the failure instead of a spurious success.
	 */
	async #enableSessionRuntime(conn: CdpConnection, sessionId: string, ref: SessionRef): Promise<void> {
		const prev = ref.runtimeState;
		const epoch = ++ref.runtimeEpoch;
		ref.runtimeState = "enabled";
		const tab = this.#tabs.get(ref.tabKey);
		if (!tab) {
			ref.runtimeState = prev;
			throw new Error(`No tab ${ref.tabKey}`);
		}
		try {
			await this.#ensureRuntimeEnabled(tab);
			// A disable or newer enable may have taken ownership while the root
			// RPC was in flight; only the latest enable may replay or roll back.
			if (conn.sessions.get(sessionId) === ref && ref.runtimeEpoch === epoch && ref.runtimeState === "enabled") {
				this.#replayRuntimeContexts(conn, sessionId, ref, tab);
			}
		} catch (err) {
			if (ref.runtimeEpoch === epoch) {
				ref.runtimeState = prev;
				ref.runtimeContexts.clear();
			}
			throw err;
		}
	}

	async #ensureRuntimeEnabled(tab: TabState): Promise<void> {
		if (tab.rootRuntimeEnabled) return;
		if (tab.rootRuntimeEnabling) return await tab.rootRuntimeEnabling;

		const enabling = this.#cycleRuntime(tab);
		tab.rootRuntimeEnabling = enabling;
		const generation = tab.runtimeGeneration;
		try {
			await enabling;
			if (tab.runtimeGeneration === generation) tab.rootRuntimeEnabled = true;
		} finally {
			if (tab.rootRuntimeEnabling === enabling) tab.rootRuntimeEnabling = null;
		}
	}

	async #cycleRuntime(tab: TabState): Promise<void> {
		const inst = this.#instanceFor(tab);
		await this.#send(tab, inst, "Runtime.disable");
		await this.#send(tab, inst, "Runtime.enable");
	}

	/**
	 * Run one command on the tab's debugger attachment. One whose answer waits on the page itself (a promise it
	 * settles, a navigation it commits) gets {@link PAGE_BOUND_RPC_TIMEOUT_MS}; any other gets {@link RPC_TIMEOUT_MS}.
	 */
	async #send(
		tab: TabState,
		inst: ExtInstance,
		method: string,
		params?: Record<string, unknown>,
		sessionId?: string,
	): Promise<unknown> {
		const pageBound =
			params?.awaitPromise === true || method === "Runtime.awaitPromise" || method === "Page.navigate";
		const timeoutMs = pageBound ? PAGE_BOUND_RPC_TIMEOUT_MS : RPC_TIMEOUT_MS;
		try {
			return await this.#rpc({ op: "send", tabId: tab.tabId, sessionId, method, params }, inst, timeoutMs);
		} catch (err) {
			if (!(err instanceof RpcTimeoutError)) throw err;
			throw new Error(`${method} on tab ${tab.tabId}: Chrome sent no answer within ${timeoutMs}ms`, { cause: err });
		}
	}

	#replayRuntimeContexts(conn: CdpConnection, sessionId: string, ref: SessionRef, tab: TabState): void {
		for (const [contextId, params] of tab.runtimeContexts) {
			if (ref.runtimeContexts.has(contextId)) continue;
			ref.runtimeContexts.add(contextId);
			conn.socket.send(JSON.stringify({ sessionId, method: "Runtime.executionContextCreated", params }));
		}
	}

	/**
	 * Chrome reports a child target once, to the first auto-attach armed over it, so a connection
	 * arming later (a tab worker after the registry connection) is told here of the children already
	 * reported under `parent` (the tab's root when undefined) that it has not heard of.
	 */
	#announceChildren(conn: CdpConnection, tabKey: string, parent: string | undefined, sessionId: string): void {
		const tab = this.#tabs.get(tabKey);
		if (!tab) return;
		for (const [child, known] of tab.realSessions) {
			if (known.parent !== parent || conn.childParents.has(child)) continue;
			conn.childParents.set(child, sessionId);
			conn.socket.send(JSON.stringify({ sessionId, method: "Target.attachedToTarget", params: known.event }));
		}
	}

	/**
	 * Forward a command to the tab and reply to it; resolves whether the command succeeded.
	 * `beforeReply` runs on success ahead of the reply. Target lifecycle commands are answered by the
	 * relay's browser handlers instead, which reply (or throw to `cdpMessage`) themselves: they resolve `true`.
	 */
	async #forwardToTab(
		conn: CdpConnection,
		msg: CdpCommand,
		tabKey: string,
		realSessionId: string | undefined,
		beforeReply?: () => void,
	): Promise<boolean> {
		// Guard rail: a page session must never take the whole browser down.
		if (msg.method === "Browser.close") {
			this.#reply(conn, msg, {});
			return true;
		}
		// Relay-private claim: the omp tab worker marks the page it was spawned
		// to drive. Never forwarded — real Chrome rejects the unknown method.
		if (msg.method === "OMP.claimTarget") {
			try {
				this.#claimTab(
					conn,
					tabKey,
					typeof msg.params?.label === "string" ? msg.params.label : undefined,
					msg.params?.ownsTarget === true,
				);
				this.#reply(conn, msg, {});
				return true;
			} catch (err) {
				this.#replyError(conn, msg, err instanceof Error ? err.message : String(err));
				return false;
			}
		}
		const tab = this.#tabs.get(tabKey);
		if (!tab) {
			this.#replyError(conn, msg, `No tab with key ${tabKey}`);
			return false;
		}
		const inst = this.#instances.get(tab.instanceId);
		if (!inst || !inst.socket) {
			this.#replyError(conn, msg, "relay extension is not connected");
			return false;
		}
		// Sent raw, createTarget honors `newWindow` and answers with Chrome's id, which no relay command
		// resolves; close and activate are refused ("Not allowed"). Run them in this tab's browser, where a
		// new tab lands like every relay-created tab: in that browser's current window.
		if (
			msg.method === "Target.createTarget" ||
			msg.method === "Target.closeTarget" ||
			msg.method === "Target.activateTarget"
		) {
			await this.#handleBrowserCommand(conn, msg, tab);
			return true;
		}
		if (this.#readFrontApp && canOpenWindow(msg.method, msg.params)) {
			tab.frontAtInput = Date.now() < this.#keepingFrontUntil ? null : this.#readFrontAtInput(this.#readFrontApp);
		}
		try {
			const result = await this.#send(tab, inst, msg.method, msg.params, realSessionId);
			beforeReply?.();
			this.#reply(conn, msg, (result as Record<string, unknown> | undefined) ?? {});
			return true;
		} catch (err) {
			const message = err instanceof Error ? err.message : String(err);
			// Chrome fails the root session's command in flight before it reports the detach. Hold the failure
			// until the detach is reported, so the client gets `OMP.debuggerDetached` first and knows why.
			if (realSessionId === undefined && tab.attached && DETACHED_COMMAND_ERROR.test(message)) {
				await Promise.race([tab.chromeDetach.promise, Bun.sleep(CHROME_DETACH_REPORT_MS)]);
			}
			this.#replyError(conn, msg, message);
			return false;
		}
	}

	/**
	 * Read the app in front of the user with `read` as omp's input reaches a tab, to put it back when that input opens a
	 * window and Chrome brings itself forward to show it. Only where the relay can put it back (macOS).
	 */
	keepFrontAppWith(read: () => FrontApp | null): void {
		this.#readFrontApp = read;
	}

	/**
	 * The app in front of the user now, for omp's input to a tab. A read that throws (a stale native addon without
	 * `macOSFrontApp`) turns the reads off for good, so the input itself still goes out.
	 */
	#readFrontAtInput(read: () => FrontApp | null): { app: FrontApp; at: number } | null {
		try {
			const app = read();
			return app && { app, at: Date.now() };
		} catch (err) {
			this.#readFrontApp = undefined;
			this.#log("could not read the app in front; not holding it in front", {
				error: err instanceof Error ? err.message : String(err),
			});
			return null;
		}
	}

	/**
	 * Hold the app that was in front at omp's last input to `tab`, if that input can have opened the window the tab's
	 * page is opening: Chrome makes itself the active app to show it.
	 */
	#keepFrontApp(tab: TabState): void {
		const front = tab.frontAtInput;
		tab.frontAtInput = null;
		if (!front || Date.now() < this.#keepingFrontUntil || Date.now() - front.at > POPUP_AFTER_INPUT_MS) return;
		const until = Date.now() + KEEP_FRONT_MS;
		this.#keepingFrontUntil = until;
		front.app.keepInFront(KEEP_FRONT_MS).then(
			times => {
				if (times > 0) this.#log("put the user's app back in front", { times });
				if (this.#keepingFrontUntil === until) this.#keepingFrontUntil = 0;
			},
			err => {
				this.#log("could not keep the user's app in front", {
					error: err instanceof Error ? err.message : String(err),
				});
			},
		);
	}

	/**
	 * Record `conn` as a driver of the tab and reconcile grouping. Claims are
	 * explicit (worker adoption or tab creation) rather than inferred from
	 * command traffic: target discovery scans every page with the same
	 * commands a driver sends, so inference would sweep all tabs.
	 */
	#claimTab(conn: CdpConnection, tabKey: string, label?: string, handoff = false): TabState | undefined {
		const tab = this.#tabs.get(tabKey);
		if (!tab) return;
		if (tab.closing) throw new Error(`Tab ${tabKey} is closing`);
		for (const other of this.#conns.values()) {
			if (other.id === conn.id || !other.claims.has(tabKey)) continue;
			if (handoff && tab.provisionalClaimConnId === other.id) {
				other.claims.delete(tabKey);
				tab.provisionalClaimConnId = undefined;
				continue;
			}
			throw new Error(`Tab ${tabKey} is already driven by another omp session`);
		}
		if (!conn.claims.has(tabKey)) {
			conn.claims.add(tabKey);
			this.#log("tab claimed", { conn: conn.id, tabKey });
		}
		if (label !== undefined) {
			const normalized = label.trim().slice(0, 32).trim() || undefined;
			if (normalized !== tab.label) {
				tab.label = normalized;
				this.#ungroupForRelabel(tab);
			}
		}
		this.#syncTabGrouping(tab);
		return tab;
	}

	/** True while any downstream connection claims the tab as its drive target. */
	#claimed(tabKey: string): boolean {
		for (const conn of this.#conns.values()) {
			if (conn.claims.has(tabKey)) return true;
		}
		return false;
	}

	/** Tab pseudo-sessions only exist to satisfy puppeteer's Target hierarchy. */
	#handleTabSessionCommand(conn: CdpConnection, msg: CdpCommand, ref: SessionRef): void {
		switch (msg.method) {
			case "Target.setAutoAttach": {
				const tab = this.#tabs.get(ref.tabKey);
				if (!tab) {
					this.#replyError(conn, msg, `Tab ${ref.tabKey} is gone`);
					return;
				}
				// Emit before replying: puppeteer's TargetManager counts page
				// children attached before the setAutoAttach response resolves.
				const pageSession = this.#mintSession(conn, "page", tab);
				this.#emit(
					conn,
					"Target.attachedToTarget",
					{
						sessionId: pageSession,
						targetInfo: this.#pageInfo(tab, true),
						waitingForDebugger: false,
					},
					msg.sessionId,
				);
				this.#reply(conn, msg, {});
				return;
			}
			case "Runtime.runIfWaitingForDebugger":
				this.#reply(conn, msg, {});
				return;
			case "Target.detachFromTarget": {
				const child = typeof msg.params?.sessionId === "string" ? msg.params.sessionId : undefined;
				if (child) this.#releaseSession(conn, child, msg.sessionId);
				this.#reply(conn, msg, {});
				return;
			}
			default:
				this.#replyError(conn, msg, `'${msg.method}' is not supported on a tab target`, CDP_ERROR_METHOD_NOT_FOUND);
		}
	}

	/** `near`: the tab whose session sent the command; a tab it creates opens in that tab's browser. */
	async #handleBrowserCommand(conn: CdpConnection, msg: CdpCommand, near?: TabState): Promise<void> {
		switch (msg.method) {
			case "Browser.getVersion": {
				this.#reply(conn, msg, {
					protocolVersion: "1.3",
					product: this.#lastHello()?.info?.browserVersion ?? "Chrome/unknown",
					revision: "",
					userAgent: this.#lastHello()?.info?.userAgent ?? "",
					jsVersion: "",
				});
				return;
			}
			case "Target.getBrowserContexts":
				this.#reply(conn, msg, { browserContextIds: [] });
				return;
			case "Target.getTargets": {
				const targetInfos: TargetInfo[] = [];
				for (const tab of this.#tabs.values()) {
					if (this.#eligible(tab)) targetInfos.push(this.#pageInfo(tab, tab.attached));
				}
				this.#reply(conn, msg, { targetInfos });
				return;
			}
			case "Target.setDiscoverTargets": {
				conn.discover = true;
				for (const tab of this.#tabs.values()) {
					if (!this.#eligible(tab)) continue;
					tab.announced = true;
					this.#emit(conn, "Target.targetCreated", { targetInfo: this.#tabInfo(tab, tab.attached) });
					this.#emit(conn, "Target.targetCreated", { targetInfo: this.#pageInfo(tab, tab.attached) });
				}
				this.#reply(conn, msg, {});
				return;
			}
			case "Target.setAutoAttach": {
				conn.autoAttach = true;
				// Discarded tabs can stall debugger calls. Retract targets already
				// announced by Target.setDiscoverTargets so Puppeteer can connect().
				const tabs = [...this.#tabs.values()].filter(tab => this.#eligible(tab) && !tab.discarded);
				await Promise.all(tabs.map(tab => this.#ensureAttached(tab, { retryAfterDiscard: true })));
				for (const tab of tabs) {
					if (!tab.attached || tab.discarded || !this.#eligible(tab)) {
						// Failed or newly discarded tabs must not hold up connect().
						this.#retractTab(tab);
						this.#detachIfUnheld(tab.tabKey);
						continue;
					}
					this.#emitTabAttached(conn, tab);
				}
				for (const tab of this.#tabs.values()) {
					if (tab.announced && tab.discarded && this.#eligible(tab)) {
						this.#retractTab(tab);
						this.#detachIfUnheld(tab.tabKey);
					}
				}
				this.#reply(conn, msg, {});
				return;
			}
			case "Target.attachToTarget": {
				const parsed = typeof msg.params?.targetId === "string" ? parseTargetId(msg.params.targetId) : null;
				const tab = parsed ? this.#tabs.get(parsed.key) : undefined;
				if (!parsed || !tab) {
					this.#replyError(conn, msg, `No target with id ${String(msg.params?.targetId)}`);
					return;
				}
				if (tab.discarded) {
					this.#replyError(conn, msg, `Cannot attach to discarded tab ${tab.tabKey}`);
					return;
				}
				if (!(await this.#ensureAttached(tab))) {
					const reason = tab.refusal ? `: ${tab.refusal}` : "";
					this.#replyError(conn, msg, `Cannot attach to tab ${tab.tabKey} (${tab.url})${reason}`);
					return;
				}
				const sessionId = this.#mintSession(conn, parsed.kind, tab);
				const info = parsed.kind === "tab" ? this.#tabInfo(tab, true) : this.#pageInfo(tab, true);
				this.#emit(conn, "Target.attachedToTarget", { sessionId, targetInfo: info, waitingForDebugger: false });
				this.#reply(conn, msg, { sessionId });
				return;
			}
			case "Target.detachFromTarget": {
				const sessionId = typeof msg.params?.sessionId === "string" ? msg.params.sessionId : undefined;
				if (sessionId) this.#releaseSession(conn, sessionId, undefined);
				this.#reply(conn, msg, {});
				return;
			}
			case "Target.createTarget": {
				const url =
					typeof msg.params?.url === "string" && msg.params.url.length > 0 ? msg.params.url : "about:blank";
				// `nearTargetId` is the relay's own parameter: open in the browser of that tab.
				const affine = near ? undefined : this.#affineInstance(conn, msg.params?.nearTargetId);
				// Its extension may be reconnecting: another browser can be another profile, logged in elsewhere.
				if (affine && !affine.socket) {
					await this.#awaitReconnect(affine);
					if (this.#conns.get(conn.id) !== conn) return;
				}
				const inst = near ? this.#instances.get(near.instanceId) : this.#instanceForNewTab(affine);
				if (!inst || !inst.socket) {
					this.#replyError(conn, msg, "relay extension is not connected");
					return;
				}
				// CDP `background: true` creates the tab without selecting it; an extension that predates `active` ignores it.
				const active = msg.params?.background === true ? false : undefined;
				// Chrome can still create the tab after the RPC timed out: close it then, since nobody learns its id.
				const result = (await this.#rpc({ op: "createTab", url, active }, inst, RPC_TIMEOUT_MS, late => {
					const tabId = (late as { tab: TabSnapshot }).tab.tabId;
					this.#closeTab(tabKeyOf(inst.code, tabId), tabId, inst).catch(err => {
						this.#log("late relay tab close waits for the next hello", {
							tabId,
							error: err instanceof Error ? err.message : String(err),
						});
					});
				})) as { tab: TabSnapshot };
				this.#onTabUpsert(result.tab, inst.instanceId);
				// The client left while Chrome created the tab (omp gave up on a slow open), so nobody
				// can learn its id to close it later: close it now instead of leaving it in the user's browser.
				if (this.#conns.get(conn.id) !== conn) {
					await this.#closeTab(tabKeyOf(inst.code, result.tab.tabId), result.tab.tabId, inst);
					return;
				}
				// Creating a tab is an explicit act of driving it.
				const createdKey = tabKeyOf(inst.code, result.tab.tabId);
				const createdTab = this.#claimTab(conn, createdKey);
				if (createdTab) {
					createdTab.provisionalClaimConnId = conn.id;
					createdTab.ompCreated = true;
				}
				// Puppeteer waits for the new page's auto-attach. Answer once it settled: a tab Chrome refuses (an
				// extension debugger policy refuses every tab) would otherwise hold the open for its whole timeout.
				const created = this.#tabs.get(createdKey);
				if (conn.autoAttach && created && !(await this.#ensureAttached(created)) && created.refusal) {
					const refusal = created.refusal;
					await this.#closeTab(createdKey, created.tabId, inst).catch(() => undefined);
					this.#replyError(conn, msg, `Chrome refused to attach to the new tab: ${refusal}`);
					return;
				}
				this.#reply(conn, msg, { targetId: pageTargetIdFromKey(createdKey) });
				return;
			}
			case "Target.closeTarget": {
				const parsed = typeof msg.params?.targetId === "string" ? parseTargetId(msg.params.targetId) : null;
				if (!parsed) {
					this.#replyError(conn, msg, `No target with id ${String(msg.params?.targetId)}`);
					return;
				}
				const removedTab = this.#tabs.get(parsed.key);
				if (!removedTab) {
					this.#replyError(conn, msg, `No target with id ${String(msg.params?.targetId)}`);
					return;
				}
				await this.#closeTab(parsed.key, removedTab.tabId, this.#instanceFor(removedTab));
				this.#reply(conn, msg, { success: true });
				return;
			}
			case "Target.activateTarget": {
				const parsed = typeof msg.params?.targetId === "string" ? parseTargetId(msg.params.targetId) : null;
				const activatedTab = parsed ? this.#tabs.get(parsed.key) : undefined;
				if (parsed && activatedTab) {
					await this.#rpc({ op: "activateTab", tabId: activatedTab.tabId }, this.#instanceFor(activatedTab));
				} else if (near) {
					// Raw, a page session's activate failed; don't turn an unknown id into success there.
					this.#replyError(conn, msg, `No target with id ${String(msg.params?.targetId)}`);
					return;
				}
				this.#reply(conn, msg, {});
				return;
			}
			case "Target.getTargetInfo": {
				const raw = typeof msg.params?.targetId === "string" ? msg.params.targetId : undefined;
				const parsed = raw ? parseTargetId(raw) : null;
				const tab = parsed ? this.#tabs.get(parsed.key) : undefined;
				if (parsed && tab) {
					const info =
						parsed.kind === "tab" ? this.#tabInfo(tab, tab.attached) : this.#pageInfo(tab, tab.attached);
					this.#reply(conn, msg, { targetInfo: info });
					return;
				}
				this.#reply(conn, msg, {
					targetInfo: {
						targetId: "relay-browser",
						type: "browser",
						title: "",
						url: "",
						attached: true,
						canAccessOpener: false,
					} satisfies TargetInfo,
				});
				return;
			}
			case "Browser.close":
				// Never close the user's browser; acknowledge and ignore.
				this.#log("refusing Browser.close from downstream client", { conn: conn.id });
				this.#reply(conn, msg, {});
				return;
			case "Browser.setDownloadBehavior":
				this.#reply(conn, msg, {});
				return;
			case "OMP.closeOwnedTarget": {
				// Relay-private orphan reaper close. `closed: false` means the record
				// is stale (tab gone, not omp-created in this browser session, or
				// driven by a live connection) and must be dropped, never retried.
				const parsed = typeof msg.params?.targetId === "string" ? parseTargetId(msg.params.targetId) : null;
				if (!parsed) {
					this.#reply(conn, msg, { closed: false });
					return;
				}
				const code = parsed.key.slice(0, parsed.key.lastIndexOf(":"));
				const inst = [...this.#instances.values()].find(candidate => candidate.code === code);
				if (!inst?.socket) {
					// Its browser is not connected: the tab may still exist, keep the record.
					this.#replyError(conn, msg, "relay extension for this target is not connected");
					return;
				}
				const owned = this.#tabs.get(parsed.key);
				if (!owned?.ompCreated || this.#claimed(parsed.key)) {
					this.#reply(conn, msg, { closed: false });
					return;
				}
				await this.#closeTab(parsed.key, owned.tabId, inst);
				this.#reply(conn, msg, { closed: true });
				return;
			}
			case "Target.createBrowserContext":
				this.#replyError(conn, msg, "Browser contexts are not supported by the omp browser relay");
				return;
			default:
				this.#replyError(conn, msg, `'${msg.method}' wasn't found`, CDP_ERROR_METHOD_NOT_FOUND);
		}
	}

	// ---- extension events -------------------------------------------------------

	#onCdpEvent(
		tabKey: string,
		sourceSessionId: string | undefined,
		method: string,
		params?: Record<string, unknown>,
	): void {
		const tab = this.#tabs.get(tabKey);
		if (!tab) return;
		// The page (or a frame in it, on a child session) is opening a tab or window; Chrome brings itself forward
		// to show it.
		if (method === "Page.windowOpen") this.#keepFrontApp(tab);
		// Track real child sessions so downstream commands can route back.
		if (method === "Target.attachedToTarget") {
			const child = params?.sessionId;
			if (typeof child === "string" && params) {
				tab.realSessions.set(child, { parent: sourceSessionId, event: params });
				this.#realSessionTabs.set(child, tabKey);
			}
		} else if (method === "Target.detachedFromTarget") {
			const child = params?.sessionId;
			if (typeof child === "string") {
				tab.realSessions.delete(child);
				this.#realSessionTabs.delete(child);
			}
		}
		if (sourceSessionId) {
			// Event from a real child session: pass through verbatim to every
			// connection that was told about the child, tracking nested children.
			const nested = typeof params?.sessionId === "string" ? params.sessionId : undefined;
			const payload = JSON.stringify({ sessionId: sourceSessionId, method, params });
			for (const conn of this.#conns.values()) {
				if (!conn.childParents.has(sourceSessionId)) continue;
				conn.socket.send(payload);
				if (nested && method === "Target.attachedToTarget") conn.childParents.set(nested, sourceSessionId);
				else if (nested && method === "Target.detachedFromTarget") conn.childParents.delete(nested);
			}
			return;
		}
		if (method.startsWith("Runtime.")) {
			const createdContext = method === "Runtime.executionContextCreated" ? params?.context : undefined;
			const createdContextId =
				createdContext &&
				typeof createdContext === "object" &&
				"id" in createdContext &&
				typeof createdContext.id === "number"
					? createdContext.id
					: undefined;
			const destroyedContextId =
				method === "Runtime.executionContextDestroyed" && typeof params?.executionContextId === "number"
					? params.executionContextId
					: undefined;
			if (createdContextId !== undefined && params) tab.runtimeContexts.set(createdContextId, params);
			if (destroyedContextId !== undefined) tab.runtimeContexts.delete(destroyedContextId);
			if (method === "Runtime.executionContextsCleared") tab.runtimeContexts.clear();

			for (const conn of this.#conns.values()) {
				for (const [pageSession, ref] of conn.sessions) {
					if (ref.kind !== "page" || ref.tabKey !== tabKey) continue;
					if (destroyedContextId !== undefined) ref.runtimeContexts.delete(destroyedContextId);
					if (method === "Runtime.executionContextsCleared") ref.runtimeContexts.clear();
					// `default` sessions never enabled Runtime but still get the
					// legacy fan-out; only an explicit `Runtime.disable` silences one.
					if (ref.runtimeState === "disabled") continue;
					if (createdContextId !== undefined) {
						if (ref.runtimeContexts.has(createdContextId)) continue;
						ref.runtimeContexts.add(createdContextId);
					}
					conn.socket.send(JSON.stringify({ sessionId: pageSession, method, params }));
				}
			}
			return;
		}
		// Other root-session events fan out once per minted page session. A real
		// child is announced once per connection, on a session that armed
		// auto-attach, and its detach goes to that same session.
		if (method === "Target.attachedToTarget" || method === "Target.detachedFromTarget") {
			const child = params?.sessionId;
			if (typeof child !== "string") return;
			for (const conn of this.#conns.values()) {
				let parent: string | undefined;
				if (method === "Target.attachedToTarget") {
					parent = conn.childTargetSessionForTab(tabKey);
					if (parent) conn.childParents.set(child, parent);
				} else {
					parent = conn.childParents.get(child);
					conn.childParents.delete(child);
				}
				if (parent) conn.socket.send(JSON.stringify({ sessionId: parent, method, params }));
			}
			return;
		}
		for (const conn of this.#conns.values()) {
			for (const pageSession of conn.sessionsForTab(tabKey, "page")) {
				conn.socket.send(JSON.stringify({ sessionId: pageSession, method, params }));
			}
		}
	}

	#onTabDetached(tabKey: string, reason: string, relayInitiated: boolean): void {
		const tab = this.#tabs.get(tabKey);
		if (!tab) return;
		// Explicit source attribution comes from the extension that executed
		// chrome.debugger.detach, so socket replacement cannot confuse this
		// with a user cancellation or mutate an unrelated attach promise.
		if (relayInitiated) {
			// A replacement hello can observe the old attachment before the
			// pending detach completes. Reconcile that stale snapshot unless a
			// later attach has already superseded this detach.
			if (!tab.reattachedAfterDetach) tab.attached = false;
			return;
		}
		this.#log("tab detached", { tabKey, reason });
		tab.attached = false;
		tab.attaching = null;
		this.#resetRuntime(tab);
		// Only the user pressing Cancel on Chrome's debugging bar is a refusal. Chrome also detaches when
		// another extension's frame (a password manager's inline menu) starts loading in the tab: that tab
		// stays adoptable and is announced again at once; an attach Chrome refuses still bans it (#ensureAttached).
		const cancelledByUser = reason === "canceled_by_user";
		if (cancelledByUser) tab.refusal = "the user cancelled Chrome's debugging bar";
		// A user cancel releases the tab's omp-group membership; any other detach keeps it.
		if (cancelledByUser) tab.banned = true;
		this.#syncTabGrouping(tab);
		// Relay-private event, ahead of the sessions' detach: a client driving the tab learns that Chrome
		// ended the attachment, not the page, and can re-adopt it instead of waiting on a dead session. A tab
		// the relay is closing detaches on its way out (Chrome may report that before the removal): not re-adoptable.
		if (!tab.closing) {
			for (const conn of this.#conns.values()) {
				for (const pageSession of conn.sessionsForTab(tabKey, "page")) {
					this.#emit(conn, "OMP.debuggerDetached", { reason }, pageSession);
				}
			}
		}
		// Failures of commands that were in flight are released behind the event (#forwardToTab).
		tab.chromeDetach.resolve();
		tab.chromeDetach = Promise.withResolvers<void>();
		this.#retractTab(tab);
		if (!cancelledByUser && !tab.closing && this.#eligible(tab) && !tab.discarded) this.#announceTab(tab);
	}

	#onTabRemoved(tabKey: string): void {
		const tab = this.#tabs.get(tabKey);
		if (!tab) return;
		this.#retractTab(tab);
		this.#tabs.delete(tabKey);
		for (const conn of this.#conns.values()) conn.claims.delete(tabKey);
	}

	#onTabUpsert(snap: TabSnapshot, instanceId: string, opts: { silent?: boolean } = {}): void {
		const inst = this.#instances.get(instanceId);
		if (!inst) return;
		const key = tabKeyOf(inst.code, snap.tabId);
		let tab = this.#tabs.get(key);
		const becameActive = snap.active && (!tab || !tab.active || tab.windowId !== snap.windowId);
		if (!tab) {
			tab = new TabState(instanceId, inst.code, snap.tabId, snap);
			this.#tabs.set(key, tab);
		} else {
			if (tab.url !== snap.url) {
				tab.refusal = undefined;
				tab.banned = false;
			}
			// The user dragging a tab out of the omp group is an opt-out; the
			// relay never fights the user over grouping.
			if (tab.grouped && tab.ompGroupId !== undefined && snap.groupId !== tab.ompGroupId) {
				tab.grouped = false;
				tab.groupOptOut = true;
			}
			tab.update(snap);
			if (tab.discarded && tab.attaching && !tab.attachCancelled) {
				tab.attachGeneration++;
				tab.attachCancelled = true;
				tab.cancelAttach?.();
			}
		}
		if (becameActive) {
			for (const other of this.#tabs.values()) {
				if (other !== tab && other.instanceId === instanceId && other.windowId === snap.windowId)
					other.active = false;
			}
		}
		if (opts.silent) return;
		const eligible = this.#eligible(tab);
		this.#syncTabGrouping(tab);
		if (eligible && !tab.announced && !tab.discarded) {
			this.#announceTab(tab);
			return;
		}
		if ((!eligible || tab.discarded) && tab.announced) {
			// Puppeteer waits for attachments to announced targets.
			this.#retractTab(tab);
			this.#detachIfUnheld(tab.tabKey);
			return;
		}
		if (eligible && tab.announced) {
			for (const conn of this.#conns.values()) {
				if (!conn.discover) continue;
				this.#emit(conn, "Target.targetInfoChanged", { targetInfo: this.#tabInfo(tab, tab.attached) });
				this.#emit(conn, "Target.targetInfoChanged", { targetInfo: this.#pageInfo(tab, tab.attached) });
			}
		}
	}

	/** Announce an unannounced tab to discovering connections and attach it for auto-attaching ones. */
	#announceTab(tab: TabState): void {
		tab.announced = true;
		for (const conn of this.#conns.values()) {
			if (!conn.discover) continue;
			this.#emit(conn, "Target.targetCreated", { targetInfo: this.#tabInfo(tab, tab.attached) });
			this.#emit(conn, "Target.targetCreated", { targetInfo: this.#pageInfo(tab, tab.attached) });
		}
		this.#attachForAutoAttach(tab);
	}

	#attachForAutoAttach(tab: TabState): void {
		let hasAutoAttach = false;
		for (const conn of this.#conns.values()) {
			if (conn.autoAttach) {
				hasAutoAttach = true;
				break;
			}
		}
		if (!hasAutoAttach) return;
		void this.#ensureAttached(tab, { retryAfterDiscard: true }).then(ok => {
			if (!ok) {
				// A refused attach bars the tab until its URL changes. Withdraw the announcement too, or the URL change
				// finds the tab already announced and neither announces nor attaches it again.
				if (tab.refusal && tab.announced && this.#tabs.get(tab.tabKey) === tab) this.#retractTab(tab);
				return;
			}
			if (tab.discarded || !this.#eligible(tab) || this.#tabs.get(tab.tabKey) !== tab) {
				this.#retractTab(tab);
				this.#detachIfUnheld(tab.tabKey);
				return;
			}
			for (const conn of this.#conns.values()) {
				if (conn.autoAttach) this.#emitTabAttached(conn, tab);
			}
		});
	}

	// ---- tab grouping -----------------------------------------------------------

	/** Group a claimed, eligible, unpinned tab unless the user grouped or opted it out. */
	#groupWorthy(tab: TabState): boolean {
		if (!this.#claimed(tab.tabKey) || !this.#eligible(tab) || tab.pinned || tab.groupOptOut) return false;
		return tab.grouped || tab.groupId === -1;
	}

	/** Re-group every claimed tab (extension hello / reconnect). */
	#syncGrouping(): void {
		if (!this.#group) return;
		const worthy = [...this.#tabs.values()].filter(tab => this.#groupWorthy(tab) && !tab.grouped && !tab.grouping);
		if (worthy.length > 0) this.#requestGroup(worthy);
	}

	/** Reconcile one tab's group membership after a lifecycle event. */
	#syncTabGrouping(tab: TabState): void {
		if (!this.#group) return;
		if (this.#groupWorthy(tab)) {
			if (!tab.grouped && !tab.grouping) this.#requestGroup([tab]);
			return;
		}
		if (tab.grouped) {
			tab.grouped = false;
			tab.ompGroupId = undefined;
			void this.#rpc({ op: "ungroup", tabIds: [tab.tabId] }, this.#instanceFor(tab)).catch(() => {});
		}
	}

	/** Move an omp-owned tab out of its previous session group before re-grouping. */
	#ungroupForRelabel(tab: TabState): void {
		if (!tab.grouped) return;
		tab.grouped = false;
		tab.ompGroupId = undefined;
		// The old group was ours, not a user group; keep it eligible while ungroup runs.
		tab.groupId = -1;
		void this.#rpc({ op: "ungroup", tabIds: [tab.tabId] }, this.#instanceFor(tab)).catch(() => {});
	}

	/**
	 * Queue tabs for grouping and drain serially. Overlapping group RPCs race
	 * the extension's non-atomic query→create→set-title sequence and mint
	 * duplicate omp groups, so at most one group RPC is ever in flight.
	 */
	#requestGroup(tabs: TabState[]): void {
		if (!this.#group) return;
		for (const tab of tabs) {
			tab.grouping = true;
			this.#groupQueue.push(tab);
		}
		if (!this.#groupDraining) void this.#drainGroupQueue();
	}

	async #drainGroupQueue(): Promise<void> {
		const group = this.#group;
		if (!group) return;
		this.#groupDraining = true;
		try {
			while (this.#groupQueue.length > 0) {
				const batch = this.#groupQueue.splice(0);
				// A group RPC addresses one browser instance and one session label.
				const byGroup = new Map<string, { instanceId: string; label?: string; tabs: TabState[] }>();
				for (const tab of batch) {
					const key = `${tab.instanceId}\u0000${tab.label ?? ""}`;
					const entry = byGroup.get(key);
					if (entry) entry.tabs.push(tab);
					else byGroup.set(key, { instanceId: tab.instanceId, label: tab.label, tabs: [tab] });
				}
				for (const { instanceId, label, tabs } of byGroup.values()) {
					const inst = this.#instances.get(instanceId);
					if (!inst?.socket) {
						for (const tab of tabs) tab.grouping = false;
						continue;
					}
					const tabIds = tabs.map(tab => tab.tabId);
					try {
						const result = await this.#rpc(
							{ op: "group", tabIds, title: label ? `omp/${label}` : group.title, color: group.color },
							inst,
						);
						// Extension replies { grouped: { [tabId]: groupId } }; validate per entry.
						const grouped: Record<string, unknown> =
							result &&
							typeof result === "object" &&
							"grouped" in result &&
							result.grouped &&
							typeof result.grouped === "object"
								? (result.grouped as Record<string, unknown>)
								: {};
						for (const tab of tabs) {
							const groupId = grouped[String(tab.tabId)];
							if (typeof groupId !== "number") continue;
							tab.grouped = true;
							tab.ompGroupId = groupId;
						}
						this.#log("grouped tabs", { instanceId, tabIds, grouped });
					} catch (err) {
						this.#log("tab grouping failed", { error: err instanceof Error ? err.message : String(err) });
					} finally {
						for (const tab of tabs) {
							tab.grouping = false;
							if (tab.label !== label) {
								this.#ungroupForRelabel(tab);
								this.#syncTabGrouping(tab);
							}
						}
					}
				}
			}
		} finally {
			this.#groupDraining = false;
		}
	}

	/** Tear a tab out of every downstream connection (closed, detached, or now ineligible). */
	#retractTab(tab: TabState): void {
		this.#forgetChildren(tab);
		for (const conn of this.#conns.values()) {
			const tabSessions = conn.sessionsForTab(tab.tabKey, "tab");
			for (const pageSession of conn.sessionsForTab(tab.tabKey, "page")) {
				conn.sessions.delete(pageSession);
				this.#emit(
					conn,
					"Target.detachedFromTarget",
					{ sessionId: pageSession, targetId: pageTargetIdFromKey(tab.tabKey) },
					tabSessions[0],
				);
			}
			for (const tabSession of tabSessions) {
				conn.sessions.delete(tabSession);
				this.#emit(conn, "Target.detachedFromTarget", {
					sessionId: tabSession,
					targetId: tabTargetIdFromKey(tab.tabKey),
				});
			}
			if (conn.discover && tab.announced) {
				this.#emit(conn, "Target.targetDestroyed", { targetId: pageTargetIdFromKey(tab.tabKey) });
				this.#emit(conn, "Target.targetDestroyed", { targetId: tabTargetIdFromKey(tab.tabKey) });
			}
		}
		tab.announced = false;
	}

	// ---- session + attach bookkeeping --------------------------------------------

	#mintSession(conn: CdpConnection, kind: "tab" | "page", tab: TabState): string {
		const sessionId = `S${kind === "tab" ? "T" : "P"}${tab.tabId}.${conn.id}.${++this.#sessionSeq}`;
		conn.sessions.set(sessionId, {
			kind,
			tabKey: tab.tabKey,
			tabId: tab.tabId,
			runtimeState: "default",
			runtimeContexts: new Set(),
			runtimeEnabling: null,
			runtimeEpoch: 0,
			autoAttach: false,
			interceptsFileChooser: false,
		});
		return sessionId;
	}

	#releaseSession(conn: CdpConnection, sessionId: string, parentSessionId: string | undefined): void {
		const ref = conn.sessions.get(sessionId);
		if (!ref) return;
		conn.sessions.delete(sessionId);
		if (ref.interceptsFileChooser) this.#releaseFileChooserInterception(ref.tabKey);
		const targetId = ref.kind === "tab" ? tabTargetIdFromKey(ref.tabKey) : pageTargetIdFromKey(ref.tabKey);
		this.#emit(conn, "Target.detachedFromTarget", { sessionId, targetId }, parentSessionId);
		// An explicit release of the last session must drop the attachment too,
		// or it outlives every downstream session: the infobar stays up, and
		// dismissing it bans the tab for the rest of the epoch.
		this.#detachIfUnheld(ref.tabKey);
	}

	/**
	 * Release the tab's chrome.debugger attachment once no downstream session
	 * holds it. Inert while the long-lived registry connection still holds one.
	 */
	#detachIfUnheld(tabKey: string): void {
		if (this.#sessionHolders(tabKey).length > 0) return;
		const tab = this.#tabs.get(tabKey);
		if (!tab?.attached) return;
		tab.attached = false;
		this.#resetRuntime(tab);
		this.#forgetChildren(tab);
		tab.reattachedAfterDetach = false;
		const done = this.#rpc({ op: "detach", tabId: tab.tabId }, this.#instanceFor(tab))
			.then(() => {})
			.catch(() => {})
			.finally(() => {
				if (tab.detaching === done) tab.detaching = null;
			});
		tab.detaching = done;
	}

	#resetRuntime(tab: TabState): void {
		tab.runtimeContexts.clear();
		tab.rootRuntimeEnabled = false;
		tab.rootRuntimeEnabling = null;
		tab.runtimeGeneration++;
	}

	/**
	 * Drop the tab's real child sessions, which end with its debugger attachment, and send each
	 * connection told of one its detach; nested children go first, while their parent is still known.
	 */
	#forgetChildren(tab: TabState): void {
		for (const child of [...tab.realSessions.keys()].reverse()) {
			this.#realSessionTabs.delete(child);
			for (const conn of this.#conns.values()) {
				const parent = conn.childParents.get(child);
				if (parent === undefined) continue;
				conn.childParents.delete(child);
				this.#emit(conn, "Target.detachedFromTarget", { sessionId: child }, parent);
			}
		}
		tab.realSessions.clear();
	}

	/** Connections currently holding any session on a tab. */
	#sessionHolders(tabKey: string): CdpConnection[] {
		const out: CdpConnection[] = [];
		for (const conn of this.#conns.values()) {
			if (conn.sessionsForTab(tabKey).length > 0) out.push(conn);
		}
		return out;
	}

	/** Whether any live session on a tab, across connections, has file chooser interception on. */
	#interceptsFileChooser(tabKey: string): boolean {
		for (const conn of this.#conns.values()) {
			for (const ref of conn.sessions.values()) {
				if (ref.tabKey === tabKey && ref.interceptsFileChooser) return true;
			}
		}
		return false;
	}

	/**
	 * Switch interception off once no live session of the tab asks for it: a session that went away without disabling
	 * it (a worker killed mid-upload) would otherwise leave the shared attachment swallowing every chooser.
	 */
	#releaseFileChooserInterception(tabKey: string): void {
		void this.#serializeInterception(tabKey, async () => {
			if (this.#interceptsFileChooser(tabKey)) return;
			const tab = this.#tabs.get(tabKey);
			const inst = tab?.attached ? this.#instances.get(tab.instanceId) : undefined;
			if (!tab || !inst) return;
			const params = { enabled: false };
			await this.#rpc(
				{ op: "send", tabId: tab.tabId, method: "Page.setInterceptFileChooserDialog", params },
				inst,
			).catch(() => {});
		});
	}

	/**
	 * Run a tab's interception transitions one at a time, each sending the tab-wide state as it stands when it runs.
	 * The extension starts RPCs independently, so overlapping transitions could settle out of order; a failed one's
	 * rollback would then restore a state another transition had already changed on the tab.
	 */
	#serializeInterception(tabKey: string, run: () => Promise<void>): Promise<void> {
		const pending = this.#interceptionTransitions.get(tabKey);
		const result = pending ? pending.then(run) : run();
		const tail = result.catch(() => {});
		this.#interceptionTransitions.set(tabKey, tail);
		void tail.then(() => {
			if (this.#interceptionTransitions.get(tabKey) === tail) this.#interceptionTransitions.delete(tabKey);
		});
		return result;
	}

	#emitTabAttached(conn: CdpConnection, tab: TabState): void {
		if (conn.sessionsForTab(tab.tabKey, "tab").length > 0) return;
		const sessionId = this.#mintSession(conn, "tab", tab);
		this.#emit(conn, "Target.attachedToTarget", {
			sessionId,
			targetInfo: this.#tabInfo(tab, true),
			waitingForDebugger: false,
		});
	}

	async #ensureAttached(tab: TabState, opts: { retryAfterDiscard?: boolean } = {}): Promise<boolean> {
		if (tab.discarded) return false;
		// The extension emits the detach echo before resolving the RPC. Awaiting
		// prevents a replacement attach racing either operation.
		while (tab.detaching) await tab.detaching;
		if (tab.discarded) return false;
		if (tab.attached) return true;
		if (tab.banned) return false;
		// A failed RPC may be transient; an explicit later attempt can retry it.
		tab.refusal = undefined;
		if (!this.#eligible(tab)) return false;
		const inst = this.#instances.get(tab.instanceId);
		if (!inst?.socket) return false;
		if (tab.attaching) {
			if (tab.attachCancelled && opts.retryAfterDiscard) tab.retryAttachAfterDiscard = true;
			return await tab.attaching;
		}
		const generation = tab.attachGeneration;
		const cancelled = Promise.withResolvers<boolean>();
		const request = this.#rpc({ op: "attach", tabId: tab.tabId }, inst)
			.then(() => {
				tab.attached = true;
				tab.reattachedAfterDetach = true;
				if (tab.discarded) this.#detachIfUnheld(tab.tabKey);
				return !tab.discarded;
			})
			.catch(err => {
				const error = err instanceof Error ? err.message : String(err);
				this.#log("attach failed", { tabKey: tab.tabKey, url: tab.url, error });
