export interface ScreenshotOptions {
	selector?: string;
	fullPage?: boolean;
	silent?: boolean;
	annotate?: boolean;
	format?: "png" | "jpeg";
	quality?: number;
	ifChanged?: boolean;
	threshold?: number;
}

