			hostname: "127.0.0.1",
			port: 0,
			fetch(req) {
				if (new URL(req.url).pathname !== "/json") return new Response("Not found", { status: 404 });
				return available ? Response.json(relayEntries) : new Response("unavailable", { status: 503 });
			},
		});
		relayJson = `http://127.0.0.1:${relay.port}`;
